COPY supabase_migrations.schema_migrations (version, statements, name, created_by, idempotency_key) FROM stdin;
20250807092512	{"-- Create profiles table for user data\nCREATE TABLE public.profiles (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  user_id UUID NOT NULL UNIQUE REFERENCES auth.users(id) ON DELETE CASCADE,\n  display_name TEXT,\n  level INTEGER NOT NULL DEFAULT 1,\n  experience_points INTEGER NOT NULL DEFAULT 0,\n  streak_days INTEGER NOT NULL DEFAULT 0,\n  total_sessions INTEGER NOT NULL DEFAULT 0,\n  achievements TEXT[] DEFAULT '{}',\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()\n);\n\n-- Enable RLS\nALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;\n\n-- Create policies\nCREATE POLICY \\"Users can view their own profile\\" \nON public.profiles \nFOR SELECT \nUSING (auth.uid() = user_id);\n\nCREATE POLICY \\"Users can update their own profile\\" \nON public.profiles \nFOR UPDATE \nUSING (auth.uid() = user_id);\n\nCREATE POLICY \\"Users can insert their own profile\\" \nON public.profiles \nFOR INSERT \nWITH CHECK (auth.uid() = user_id);\n\n-- Create function to update timestamps\nCREATE OR REPLACE FUNCTION public.update_updated_at_column()\nRETURNS TRIGGER AS $$\nBEGIN\n  NEW.updated_at = now();\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Create trigger for automatic timestamp updates\nCREATE TRIGGER update_profiles_updated_at\nBEFORE UPDATE ON public.profiles\nFOR EACH ROW\nEXECUTE FUNCTION public.update_updated_at_column();\n\n-- Create function to handle new user registration\nCREATE OR REPLACE FUNCTION public.handle_new_user()\nRETURNS TRIGGER AS $$\nBEGIN\n  INSERT INTO public.profiles (user_id, display_name)\n  VALUES (\n    NEW.id, \n    COALESCE(NEW.raw_user_meta_data->>'display_name', NEW.email)\n  );\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER;\n\n-- Create trigger to automatically create profile for new users\nCREATE TRIGGER on_auth_user_created\n  AFTER INSERT ON auth.users\n  FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();"}		elvisiondragon@gmail.com	\N
20250807093439	{"-- Create storage bucket for audio files\nINSERT INTO storage.buckets (id, name, public) \nVALUES ('audio-files', 'audio-files', true);\n\n-- Create policies for audio file access\nCREATE POLICY \\"Anyone can view audio files\\" \nON storage.objects \nFOR SELECT \nUSING (bucket_id = 'audio-files');\n\nCREATE POLICY \\"Authenticated users can upload audio\\" \nON storage.objects \nFOR INSERT \nWITH CHECK (bucket_id = 'audio-files' AND auth.uid() IS NOT NULL);\n\nCREATE POLICY \\"Users can update their own audio files\\" \nON storage.objects \nFOR UPDATE \nUSING (bucket_id = 'audio-files' AND auth.uid()::text = (storage.foldername(name))[1]);\n\nCREATE POLICY \\"Users can delete their own audio files\\" \nON storage.objects \nFOR DELETE \nUSING (bucket_id = 'audio-files' AND auth.uid()::text = (storage.foldername(name))[1]);\n\n-- Create table for managing audio content\nCREATE TABLE public.audio_tracks (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  title TEXT NOT NULL,\n  description TEXT,\n  file_path TEXT NOT NULL,\n  file_url TEXT,\n  duration INTEGER, -- in seconds\n  category TEXT DEFAULT 'verse', -- verse, meditation, ambient, etc.\n  created_by UUID REFERENCES auth.users(id) ON DELETE CASCADE,\n  is_public BOOLEAN DEFAULT true,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()\n);\n\n-- Enable RLS\nALTER TABLE public.audio_tracks ENABLE ROW LEVEL SECURITY;\n\n-- Create policies for audio tracks\nCREATE POLICY \\"Anyone can view public audio tracks\\" \nON public.audio_tracks \nFOR SELECT \nUSING (is_public = true);\n\nCREATE POLICY \\"Users can view their own audio tracks\\" \nON public.audio_tracks \nFOR SELECT \nUSING (auth.uid() = created_by);\n\nCREATE POLICY \\"Authenticated users can create audio tracks\\" \nON public.audio_tracks \nFOR INSERT \nWITH CHECK (auth.uid() = created_by);\n\nCREATE POLICY \\"Users can update their own audio tracks\\" \nON public.audio_tracks \nFOR UPDATE \nUSING (auth.uid() = created_by);\n\nCREATE POLICY \\"Users can delete their own audio tracks\\" \nON public.audio_tracks \nFOR DELETE \nUSING (auth.uid() = created_by);\n\n-- Add trigger for timestamps\nCREATE TRIGGER update_audio_tracks_updated_at\nBEFORE UPDATE ON public.audio_tracks\nFOR EACH ROW\nEXECUTE FUNCTION public.update_updated_at_column();"}		elvisiondragon@gmail.com	\N
20250808075342	{"-- Delete the existing verse tracks to make room for verse 1, 2, and 3\nDELETE FROM audio_tracks WHERE category = 'verse';"}		elvisiondragon@gmail.com	\N
20250808052754	{"-- Update the current user's streak to 7 days\nUPDATE profiles \nSET streak_days = 7 \nWHERE user_id = auth.uid();"}		elvisiondragon@gmail.com	\N
20250808052923	{"-- Update streak_days to 7 for all users (since we don't have a specific user context)\nUPDATE profiles \nSET streak_days = 7;"}		elvisiondragon@gmail.com	\N
20250808060332	{"-- Create chat_messages table for persistent community chat\nCREATE TABLE public.chat_messages (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  user_id UUID NOT NULL,\n  user_name TEXT NOT NULL,\n  user_level INTEGER NOT NULL DEFAULT 1,\n  is_vip BOOLEAN DEFAULT false,\n  message TEXT NOT NULL,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()\n);\n\n-- Enable Row Level Security\nALTER TABLE public.chat_messages ENABLE ROW LEVEL SECURITY;\n\n-- Create policies - everyone can read, only authenticated users can insert\nCREATE POLICY \\"Anyone can view chat messages\\" \nON public.chat_messages \nFOR SELECT \nUSING (true);\n\nCREATE POLICY \\"Authenticated users can create chat messages\\" \nON public.chat_messages \nFOR INSERT \nWITH CHECK (auth.uid() = user_id);\n\n-- Add index for better performance on timestamp queries\nCREATE INDEX idx_chat_messages_created_at ON public.chat_messages(created_at DESC);\n\n-- Enable realtime for live chat updates\nALTER TABLE public.chat_messages REPLICA IDENTITY FULL;\nALTER PUBLICATION supabase_realtime ADD TABLE public.chat_messages;"}		elvisiondragon@gmail.com	\N
20250808074406	{"-- Create reflections table for spiritual journal\nCREATE TABLE public.reflections (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  user_id UUID NOT NULL,\n  question TEXT NOT NULL,\n  reflection TEXT NOT NULL,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()\n);\n\n-- Enable RLS\nALTER TABLE public.reflections ENABLE ROW LEVEL SECURITY;\n\n-- Create policies\nCREATE POLICY \\"Users can view their own reflections\\" \nON public.reflections \nFOR SELECT \nUSING (auth.uid() = user_id);\n\nCREATE POLICY \\"Users can create their own reflections\\" \nON public.reflections \nFOR INSERT \nWITH CHECK (auth.uid() = user_id);\n\nCREATE POLICY \\"Users can update their own reflections\\" \nON public.reflections \nFOR UPDATE \nUSING (auth.uid() = user_id);\n\nCREATE POLICY \\"Users can delete their own reflections\\" \nON public.reflections \nFOR DELETE \nUSING (auth.uid() = user_id);\n\n-- Add trigger for automatic timestamp updates\nCREATE TRIGGER update_reflections_updated_at\nBEFORE UPDATE ON public.reflections\nFOR EACH ROW\nEXECUTE FUNCTION public.update_updated_at_column();"}		elvisiondragon@gmail.com	\N
20250808112853	{"-- Add avatar_url column to profiles table if it doesn't exist\nALTER TABLE public.profiles \nADD COLUMN IF NOT EXISTS avatar_url TEXT;\n\n-- Create a storage bucket for profile pictures if it doesn't exist\nINSERT INTO storage.buckets (id, name, public) \nVALUES ('profile-pictures', 'profile-pictures', true)\nON CONFLICT (id) DO NOTHING;\n\n-- Create policies for profile picture uploads\nCREATE POLICY \\"Users can view profile pictures\\" \nON storage.objects \nFOR SELECT \nUSING (bucket_id = 'profile-pictures');\n\nCREATE POLICY \\"Users can upload their own profile picture\\" \nON storage.objects \nFOR INSERT \nWITH CHECK (bucket_id = 'profile-pictures' AND auth.uid()::text = (storage.foldername(name))[1]);\n\nCREATE POLICY \\"Users can update their own profile picture\\" \nON storage.objects \nFOR UPDATE \nUSING (bucket_id = 'profile-pictures' AND auth.uid()::text = (storage.foldername(name))[1]);\n\nCREATE POLICY \\"Users can delete their own profile picture\\" \nON storage.objects \nFOR DELETE \nUSING (bucket_id = 'profile-pictures' AND auth.uid()::text = (storage.foldername(name))[1]);"}		elvisiondragon@gmail.com	\N
