20250810040738	{"-- Update Andin's profile to level 9 with 15000 XP\nUPDATE profiles \nSET \n  experience_points = 15000,\n  level = 9,\n  display_name = 'Andin'\nWHERE user_id = '8c2cd3b1-6b77-4df9-92c5-467182ecd13d';"}		elvisiondragon@gmail.com	\N
20250810124827	{"-- Create user_activities table to track XP earning activities\nCREATE TABLE public.user_activities (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  user_id UUID NOT NULL,\n  activity_type TEXT NOT NULL,\n  xp_earned INTEGER NOT NULL DEFAULT 0,\n  metadata JSONB DEFAULT '{}',\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()\n);\n\n-- Create xp_transactions table to log all XP gains\nCREATE TABLE public.xp_transactions (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  user_id UUID NOT NULL,\n  xp_amount INTEGER NOT NULL,\n  transaction_type TEXT NOT NULL,\n  reason TEXT,\n  activity_id UUID,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()\n);\n\n-- Enable RLS on both tables\nALTER TABLE public.user_activities ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.xp_transactions ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for user_activities\nCREATE POLICY \\"Users can view their own activities\\" \nON public.user_activities \nFOR SELECT \nUSING (auth.uid() = user_id);\n\nCREATE POLICY \\"Users can create their own activities\\" \nON public.user_activities \nFOR INSERT \nWITH CHECK (auth.uid() = user_id);\n\n-- RLS policies for xp_transactions\nCREATE POLICY \\"Users can view their own XP transactions\\" \nON public.xp_transactions \nFOR SELECT \nUSING (auth.uid() = user_id);\n\nCREATE POLICY \\"Users can create their own XP transactions\\" \nON public.xp_transactions \nFOR INSERT \nWITH CHECK (auth.uid() = user_id);\n\n-- Function to calculate level from XP\nCREATE OR REPLACE FUNCTION public.calculate_level_from_xp(total_xp INTEGER)\nRETURNS INTEGER AS $$\nDECLARE\n  level INTEGER := 1;\n  xp_needed INTEGER := 100;\n  current_xp INTEGER := total_xp;\nBEGIN\n  WHILE current_xp >= xp_needed LOOP\n    current_xp := current_xp - xp_needed;\n    level := level + 1;\n    \n    -- XP requirements per level\n    IF level <= 3 THEN\n      xp_needed := 100;\n    ELSIF level <= 6 THEN\n      xp_needed := 150;\n    ELSIF level <= 10 THEN\n      xp_needed := 200;\n    ELSE\n      xp_needed := 250;\n    END IF;\n  END LOOP;\n  \n  RETURN level;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Function to get XP needed for next level\nCREATE OR REPLACE FUNCTION public.get_xp_for_next_level(current_level INTEGER)\nRETURNS INTEGER AS $$\nBEGIN\n  IF current_level <= 3 THEN\n    RETURN 100;\n  ELSIF current_level <= 6 THEN\n    RETURN 150;\n  ELSIF current_level <= 10 THEN\n    RETURN 200;\n  ELSE\n    RETURN 250;\n  END IF;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Function to award XP and update level\nCREATE OR REPLACE FUNCTION public.award_xp(\n  p_user_id UUID,\n  p_xp_amount INTEGER,\n  p_activity_type TEXT,\n  p_reason TEXT DEFAULT NULL,\n  p_metadata JSONB DEFAULT '{}'\n)\nRETURNS VOID AS $$\nDECLARE\n  new_total_xp INTEGER;\n  new_level INTEGER;\n  old_level INTEGER;\nBEGIN\n  -- Get current level\n  SELECT level INTO old_level FROM public.profiles WHERE user_id = p_user_id;\n  \n  -- Update experience points\n  UPDATE public.profiles \n  SET experience_points = experience_points + p_xp_amount,\n      updated_at = now()\n  WHERE user_id = p_user_id\n  RETURNING experience_points INTO new_total_xp;\n  \n  -- Calculate new level\n  new_level := public.calculate_level_from_xp(new_total_xp);\n  \n  -- Update level if changed\n  IF new_level != old_level THEN\n    UPDATE public.profiles \n    SET level = new_level,\n        updated_at = now()\n    WHERE user_id = p_user_id;\n  END IF;\n  \n  -- Log the activity\n  INSERT INTO public.user_activities (user_id, activity_type, xp_earned, metadata)\n  VALUES (p_user_id, p_activity_type, p_xp_amount, p_metadata);\n  \n  -- Log the XP transaction\n  INSERT INTO public.xp_transactions (user_id, xp_amount, transaction_type, reason)\n  VALUES (p_user_id, p_xp_amount, 'earned', COALESCE(p_reason, p_activity_type));\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER;\n\n-- Function to check daily chat limit\nCREATE OR REPLACE FUNCTION public.check_daily_chat_limit(p_user_id UUID)\nRETURNS BOOLEAN AS $$\nDECLARE\n  daily_chat_count INTEGER;\nBEGIN\n  SELECT COUNT(*) INTO daily_chat_count\n  FROM public.user_activities\n  WHERE user_id = p_user_id\n    AND activity_type = 'chat_message'\n    AND created_at >= CURRENT_DATE;\n    \n  RETURN daily_chat_count < 10;\nEND;\n$$ LANGUAGE plpgsql;"}		elvisiondragon@gmail.com	\N
20250810125653	{"-- Create notification settings table\nCREATE TABLE public.notification_settings (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,\n  chat_notifications_enabled BOOLEAN NOT NULL DEFAULT true,\n  quiet_hours_start TIME,\n  quiet_hours_end TIME,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  UNIQUE(user_id)\n);\n\n-- Create device tokens table\nCREATE TABLE public.device_tokens (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,\n  token TEXT NOT NULL,\n  platform TEXT NOT NULL CHECK (platform IN ('ios', 'android', 'web')),\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  UNIQUE(user_id, token)\n);\n\n-- Enable RLS\nALTER TABLE public.notification_settings ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.device_tokens ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for notification_settings\nCREATE POLICY \\"Users can view their own notification settings\\"\nON public.notification_settings\nFOR SELECT\nUSING (auth.uid() = user_id);\n\nCREATE POLICY \\"Users can insert their own notification settings\\"\nON public.notification_settings\nFOR INSERT\nWITH CHECK (auth.uid() = user_id);\n\nCREATE POLICY \\"Users can update their own notification settings\\"\nON public.notification_settings\nFOR UPDATE\nUSING (auth.uid() = user_id);\n\n-- RLS policies for device_tokens\nCREATE POLICY \\"Users can view their own device tokens\\"\nON public.device_tokens\nFOR SELECT\nUSING (auth.uid() = user_id);\n\nCREATE POLICY \\"Users can insert their own device tokens\\"\nON public.device_tokens\nFOR INSERT\nWITH CHECK (auth.uid() = user_id);\n\nCREATE POLICY \\"Users can update their own device tokens\\"\nON public.device_tokens\nFOR UPDATE\nUSING (auth.uid() = user_id);\n\nCREATE POLICY \\"Users can delete their own device tokens\\"\nON public.device_tokens\nFOR DELETE\nUSING (auth.uid() = user_id);\n\n-- Function to send chat notification\nCREATE OR REPLACE FUNCTION public.notify_chat_message()\nRETURNS TRIGGER\nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nBEGIN\n  -- Call edge function to send push notifications\n  -- This will be handled by the edge function we'll create\n  PERFORM net.http_post(\n    url := 'https://8fda2b20-72ff-449c-bd0b-71d9a561716d.functions.supabase.co/send-chat-notification',\n    headers := '{\\"Content-Type\\": \\"application/json\\", \\"Authorization\\": \\"Bearer ' || current_setting('request.jwt.claims', true)::json->>'sub' || '\\"}',\n    body := json_build_object(\n      'message_id', NEW.id,\n      'sender_id', NEW.user_id,\n      'sender_name', NEW.user_name,\n      'message', NEW.message\n    )::text\n  );\n  \n  RETURN NEW;\nEND;\n$$;\n\n-- Trigger to send notifications on new chat messages\nCREATE TRIGGER on_chat_message_created\n  AFTER INSERT ON public.chat_messages\n  FOR EACH ROW\n  EXECUTE FUNCTION public.notify_chat_message();\n\n-- Update triggers for timestamps\nCREATE TRIGGER update_notification_settings_updated_at\n  BEFORE UPDATE ON public.notification_settings\n  FOR EACH ROW\n  EXECUTE FUNCTION public.update_updated_at_column();\n\nCREATE TRIGGER update_device_tokens_updated_at\n  BEFORE UPDATE ON public.device_tokens\n  FOR EACH ROW\n  EXECUTE FUNCTION public.update_updated_at_column();"}		elvisiondragon@gmail.com	\N
20250810024126	{"-- Fix the notify_chat_message function to handle JWT claims properly\nCREATE OR REPLACE FUNCTION public.notify_chat_message()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n  jwt_claims json;\n  user_id text;\nBEGIN\n  -- Safely get JWT claims\n  BEGIN\n    jwt_claims := current_setting('request.jwt.claims', true)::json;\n    user_id := jwt_claims->>'sub';\n  EXCEPTION\n    WHEN OTHERS THEN\n      -- If JWT claims are not available or invalid, use the user_id from the message\n      user_id := NEW.user_id::text;\n  END;\n  \n  -- Call edge function to send push notifications\n  PERFORM net.http_post(\n    url := 'https://nlrgdhpmsittuwiiindq.supabase.co/functions/v1/send-chat-notification',\n    headers := jsonb_build_object(\n      'Content-Type', 'application/json',\n      'Authorization', 'Bearer ' || COALESCE(user_id, 'anonymous')\n    )::text,\n    body := jsonb_build_object(\n      'message_id', NEW.id,\n      'sender_id', NEW.user_id,\n      'sender_name', NEW.user_name,\n      'message', NEW.message\n    )::text\n  );\n  \n  RETURN NEW;\nEND;\n$function$;\n\n-- Create the trigger if it doesn't exist\nDROP TRIGGER IF EXISTS notify_chat_message_trigger ON public.chat_messages;\nCREATE TRIGGER notify_chat_message_trigger\n  AFTER INSERT ON public.chat_messages\n  FOR EACH ROW\n  EXECUTE FUNCTION public.notify_chat_message();"}		elvisiondragon@gmail.com	\N
20250810024837	{"-- Drop the problematic notify_chat_message function that requires net schema\nDROP FUNCTION IF EXISTS public.notify_chat_message() CASCADE;"}		elvisiondragon@gmail.com	\N
20250810040451	{"-- Update level calculation function with new requirements\nCREATE OR REPLACE FUNCTION public.calculate_level_from_xp(total_xp integer)\nRETURNS integer\nLANGUAGE plpgsql\nAS $function$\nDECLARE\n  level INTEGER := 1;\nBEGIN\n  -- New level requirements: 1=100, 2=500, 3=1500, 4=3000\n  IF total_xp >= 3000 THEN\n    RETURN 4;\n  ELSIF total_xp >= 1500 THEN\n    RETURN 3;\n  ELSIF total_xp >= 500 THEN\n    RETURN 2;\n  ELSIF total_xp >= 100 THEN\n    RETURN 1;\n  ELSE\n    RETURN 1;\n  END IF;\nEND;\n$function$;\n\n-- Update XP for next level function\nCREATE OR REPLACE FUNCTION public.get_xp_for_next_level(current_level integer)\nRETURNS integer\nLANGUAGE plpgsql\nAS $function$\nBEGIN\n  CASE current_level\n    WHEN 1 THEN RETURN 500;\n    WHEN 2 THEN RETURN 1500;\n    WHEN 3 THEN RETURN 3000;\n    ELSE RETURN 3000; -- Max level reached\n  END CASE;\nEND;\n$function$;\n\n-- Create function to check daily journal limit (5 XP per day)\nCREATE OR REPLACE FUNCTION public.check_daily_journal_limit(p_user_id uuid)\nRETURNS boolean\nLANGUAGE plpgsql\nAS $function$\nDECLARE\n  daily_journal_xp INTEGER;\nBEGIN\n  SELECT COALESCE(SUM(xp_earned), 0) INTO daily_journal_xp\n  FROM public.user_activities\n  WHERE user_id = p_user_id\n    AND activity_type = 'journal_entry'\n    AND created_at >= CURRENT_DATE;\n    \n  RETURN daily_journal_xp < 5;\nEND;\n$function$;\n\n-- Create function to check daily audio limit (20 XP per day)\nCREATE OR REPLACE FUNCTION public.check_daily_audio_limit(p_user_id uuid)\nRETURNS boolean\nLANGUAGE plpgsql\nAS $function$\nDECLARE\n  daily_audio_xp INTEGER;\nBEGIN\n  SELECT COALESCE(SUM(xp_earned), 0) INTO daily_audio_xp\n  FROM public.user_activities\n  WHERE user_id = p_user_id\n    AND activity_type = 'audio_completed'\n    AND created_at >= CURRENT_DATE;\n    \n  RETURN daily_audio_xp < 20;\nEND;\n$function$;"}		elvisiondragon@gmail.com	\N
20250810040711	{"-- Update level calculation function to support level 9\nCREATE OR REPLACE FUNCTION public.calculate_level_from_xp(total_xp integer)\nRETURNS integer\nLANGUAGE plpgsql\nAS $function$\nDECLARE\n  level INTEGER := 1;\nBEGIN\n  -- Extended level requirements to support level 9\n  IF total_xp >= 15000 THEN\n    RETURN 9;\n  ELSIF total_xp >= 10000 THEN\n    RETURN 8;\n  ELSIF total_xp >= 7500 THEN\n    RETURN 7;\n  ELSIF total_xp >= 5000 THEN\n    RETURN 6;\n  ELSIF total_xp >= 4000 THEN\n    RETURN 5;\n  ELSIF total_xp >= 3000 THEN\n    RETURN 4;\n  ELSIF total_xp >= 1500 THEN\n    RETURN 3;\n  ELSIF total_xp >= 500 THEN\n    RETURN 2;\n  ELSIF total_xp >= 100 THEN\n    RETURN 1;\n  ELSE\n    RETURN 1;\n  END IF;\nEND;\n$function$;\n\n-- Update XP for next level function to support higher levels\nCREATE OR REPLACE FUNCTION public.get_xp_for_next_level(current_level integer)\nRETURNS integer\nLANGUAGE plpgsql\nAS $function$\nBEGIN\n  CASE current_level\n    WHEN 1 THEN RETURN 500;\n    WHEN 2 THEN RETURN 1500;\n    WHEN 3 THEN RETURN 3000;\n    WHEN 4 THEN RETURN 4000;\n    WHEN 5 THEN RETURN 5000;\n    WHEN 6 THEN RETURN 7500;\n    WHEN 7 THEN RETURN 10000;\n    WHEN 8 THEN RETURN 15000;\n    ELSE RETURN 15000; -- Max level reached\n  END CASE;\nEND;\n$function$;"}		elvisiondragon@gmail.com	\N
20250810041459	{"-- Update mochseno91@gmail.com user (Senz) to level 6 with 4000+ XP\nUPDATE profiles \nSET \n  experience_points = 4500,\n  level = 6\nWHERE user_id = '38625adb-dcfb-4bac-b473-2e6ee37af72e';\n\n-- Check if Jason exists and update if needed (placeholder for now since Jason wasn't found in current query)\n-- We'll need to create Jason's profile or find the correct user"}		elvisiondragon@gmail.com	\N
20250810060159	{"-- Update the calculate_level_from_xp function to change level 2 requirement from 500 to 150\nCREATE OR REPLACE FUNCTION public.calculate_level_from_xp(total_xp integer)\nRETURNS integer\nLANGUAGE plpgsql\nAS $function$\nDECLARE\n  level INTEGER := 1;\nBEGIN\n  -- Updated level requirements with level 2 now requiring 150 XP instead of 500\n  IF total_xp >= 15000 THEN\n    RETURN 9;\n  ELSIF total_xp >= 10000 THEN\n    RETURN 8;\n  ELSIF total_xp >= 7500 THEN\n    RETURN 7;\n  ELSIF total_xp >= 5000 THEN\n    RETURN 6;\n  ELSIF total_xp >= 4000 THEN\n    RETURN 5;\n  ELSIF total_xp >= 3000 THEN\n    RETURN 4;\n  ELSIF total_xp >= 1500 THEN\n    RETURN 3;\n  ELSIF total_xp >= 150 THEN\n    RETURN 2;\n  ELSIF total_xp >= 100 THEN\n    RETURN 1;\n  ELSE\n    RETURN 1;\n  END IF;\nEND;\n$function$;\n\n-- Update all users' levels based on the new XP requirements\nUPDATE public.profiles \nSET level = public.calculate_level_from_xp(experience_points),\n    updated_at = now()\nWHERE experience_points IS NOT NULL;"}		elvisiondragon@gmail.com	\N
20250810061006	{"-- Award 140 XP to user srcindocs@gmail.com\nDO $$\nDECLARE\n  target_user_id UUID;\nBEGIN\n  -- Get the user_id for the email srcindocs@gmail.com\n  SELECT user_id INTO target_user_id \n  FROM public.profiles \n  WHERE user_id IN (\n    SELECT id FROM auth.users WHERE email = 'srcindocs@gmail.com'\n  );\n  \n  -- If user found, award XP\n  IF target_user_id IS NOT NULL THEN\n    PERFORM public.award_xp(\n      target_user_id,\n      140,\n      'admin_bonus',\n      'Manual XP award by admin',\n      '{\\"source\\": \\"admin_action\\"}'::jsonb\n    );\n    RAISE NOTICE 'Successfully awarded 140 XP to user srcindocs@gmail.com';\n  ELSE\n    RAISE NOTICE 'User with email srcindocs@gmail.com not found';\n  END IF;\nEND $$;"}		elvisiondragon@gmail.com	\N
20250810090938	{"-- Add language support to audio_tracks and profiles tables\nALTER TABLE public.audio_tracks \nADD COLUMN language TEXT DEFAULT 'id';\n\n-- Update all existing audio tracks to be Indonesian\nUPDATE public.audio_tracks \nSET language = 'id' \nWHERE language IS NULL;\n\n-- Add preferred language to user profiles\nALTER TABLE public.profiles \nADD COLUMN preferred_language TEXT DEFAULT 'auto';\n\n-- Create index for better performance\nCREATE INDEX idx_audio_tracks_language ON public.audio_tracks(language);\nCREATE INDEX idx_audio_tracks_category_language ON public.audio_tracks(category, language);\n\n-- Update existing audio tracks to use Indonesian folder structure\nUPDATE public.audio_tracks \nSET file_path = 'indonesia/' || file_path \nWHERE file_path IS NOT NULL \nAND file_path NOT LIKE 'indonesia/%' \nAND file_path NOT LIKE 'english/%';"}		elvisiondragon@gmail.com	\N
20250810091702	{"-- Add 5 community comments about the language switching feature\nINSERT INTO public.chat_messages (user_id, user_name, message, user_level, is_vip, created_at) VALUES\n(\n  gen_random_uuid(),\n  'Hans Müller',\n  'Luar biasa! Akhirnya ada aplikasi yang otomatis mengerti saya tanpa perlu ganti bahasa manual.',\n  2,\n  false,\n  now() - interval '5 minutes'\n),\n(\n  gen_random_uuid(),\n  'Claire Dubois',\n  'Ini keren sekali! Rasanya seperti aplikasi ini bicara langsung dengan saya dalam bahasa ibu.',\n  2,\n  false,\n  now() - interval '4 minutes'\n),\n(\n  gen_random_uuid(),\n  'John Smith',\n  'Hebat banget! Seperti aplikasi ini dibuat khusus untuk saya, di mana pun saya berada.',\n  2,\n  false,\n  now() - interval '3 minutes'\n),\n(\n  gen_random_uuid(),\n  'Khalid Al-Farouq',\n  'Benar-benar memukau! Aplikasi ini paham bahasa saya dan membuat pengalaman terasa alami.',\n  2,\n  false,\n  now() - interval '2 minutes'\n),\n(\n  gen_random_uuid(),\n  'Haruki Tanaka',\n  'Ini luar biasa! Rasanya seperti aplikasi ini diciptakan khusus untuk saya.',\n  2,\n  false,\n  now() - interval '1 minute'\n);"}		elvisiondragon@gmail.com	\N
20250810092113	{"-- Update the community comments with new text\nUPDATE public.chat_messages \nSET message = 'Akhirnya! Sebuah aplikasi yang tidak merepotkan. Saya buka, dan semuanya sudah dalam bahasa Jerman'\nWHERE user_name = 'Hans Müller';\n\nUPDATE public.chat_messages \nSET message = 'Cara aplikasi ini menyambut saya dalam bahasa Prancis terasa begitu personal'\nWHERE user_name = 'Claire Dubois';\n\nUPDATE public.chat_messages \nSET message = 'Keren'\nWHERE user_name = 'John Smith';\n\nUPDATE public.chat_messages \nSET message = 'Semoga lancar'\nWHERE user_name = 'Khalid Al-Farouq';\n\nUPDATE public.chat_messages \nSET message = 'Saya suka desainnya'\nWHERE user_name = 'Haruki Tanaka';"}		elvisiondragon@gmail.com	\N
20250810092836	{"-- Update Hans Müller's message to mention English instead of German\nUPDATE public.chat_messages \nSET message = 'Akhirnya! Sebuah aplikasi yang tidak merepotkan. Saya buka, dan semuanya sudah dalam bahasa Inggris'\nWHERE user_name = 'Hans Müller';\n\n-- Update Claire Dubois's message to ask about All father voice\nUPDATE public.chat_messages \nSET message = 'Cara aplikasi ini menyambut saya dalam suara terasa begitu personal, siapakah itu All father yang dimaksud ?'\nWHERE user_name = 'Claire Dubois';"}		elvisiondragon@gmail.com	\N
