20250811013940	{"-- Create VIP subscriptions table\nCREATE TABLE public.vip_subscriptions (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,\n  email TEXT NOT NULL,\n  ip_address TEXT,\n  subscription_type TEXT CHECK (subscription_type IN ('trial', 'monthly', 'yearly')) NOT NULL DEFAULT 'trial',\n  status TEXT CHECK (status IN ('active', 'expired', 'cancelled', 'pending')) NOT NULL DEFAULT 'pending',\n  trial_start_date TIMESTAMPTZ,\n  trial_end_date TIMESTAMPTZ,\n  subscription_start_date TIMESTAMPTZ,\n  subscription_end_date TIMESTAMPTZ,\n  amount_paid DECIMAL(10,2),\n  currency TEXT DEFAULT 'IDR',\n  tripay_reference TEXT UNIQUE,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  UNIQUE(user_id)\n);\n\n-- Create payment transactions table\nCREATE TABLE public.payment_transactions (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  subscription_id UUID NOT NULL REFERENCES public.vip_subscriptions(id) ON DELETE CASCADE,\n  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,\n  tripay_reference TEXT NOT NULL UNIQUE,\n  tripay_merchant_ref TEXT NOT NULL,\n  payment_method TEXT,\n  amount DECIMAL(10,2) NOT NULL,\n  currency TEXT DEFAULT 'IDR',\n  status TEXT CHECK (status IN ('pending', 'paid', 'failed', 'expired', 'cancelled')) NOT NULL DEFAULT 'pending',\n  payment_url TEXT,\n  payment_instructions JSONB,\n  paid_at TIMESTAMPTZ,\n  expires_at TIMESTAMPTZ,\n  callback_data JSONB,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\n-- Enable RLS\nALTER TABLE public.vip_subscriptions ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.payment_transactions ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for vip_subscriptions\nCREATE POLICY \\"Users can view their own subscription\\" \nON public.vip_subscriptions \nFOR SELECT \nUSING (auth.uid() = user_id);\n\nCREATE POLICY \\"Users can insert their own subscription\\" \nON public.vip_subscriptions \nFOR INSERT \nWITH CHECK (auth.uid() = user_id);\n\nCREATE POLICY \\"Users can update their own subscription\\" \nON public.vip_subscriptions \nFOR UPDATE \nUSING (auth.uid() = user_id);\n\n-- RLS policies for payment_transactions\nCREATE POLICY \\"Users can view their own transactions\\" \nON public.payment_transactions \nFOR SELECT \nUSING (auth.uid() = user_id);\n\nCREATE POLICY \\"Users can insert their own transactions\\" \nON public.payment_transactions \nFOR INSERT \nWITH CHECK (auth.uid() = user_id);\n\n-- Create trigger for updated_at\nCREATE TRIGGER update_vip_subscriptions_updated_at\nBEFORE UPDATE ON public.vip_subscriptions\nFOR EACH ROW\nEXECUTE FUNCTION public.update_updated_at_column();\n\nCREATE TRIGGER update_payment_transactions_updated_at\nBEFORE UPDATE ON public.payment_transactions\nFOR EACH ROW\nEXECUTE FUNCTION public.update_updated_at_column();\n\n-- Create function to start trial\nCREATE OR REPLACE FUNCTION public.start_vip_trial(p_user_id UUID, p_email TEXT, p_ip_address TEXT DEFAULT NULL)\nRETURNS UUID\nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nDECLARE\n  subscription_id UUID;\n  trial_end TIMESTAMPTZ;\nBEGIN\n  -- Calculate trial end date (3 days from now)\n  trial_end := now() + INTERVAL '3 days';\n  \n  -- Insert or update VIP subscription\n  INSERT INTO public.vip_subscriptions (\n    user_id, \n    email, \n    ip_address,\n    subscription_type,\n    status,\n    trial_start_date,\n    trial_end_date\n  ) VALUES (\n    p_user_id, \n    p_email, \n    p_ip_address,\n    'trial',\n    'active',\n    now(),\n    trial_end\n  )\n  ON CONFLICT (user_id) \n  DO UPDATE SET\n    subscription_type = 'trial',\n    status = 'active',\n    trial_start_date = now(),\n    trial_end_date = trial_end,\n    updated_at = now()\n  RETURNING id INTO subscription_id;\n  \n  RETURN subscription_id;\nEND;\n$$;\n\n-- Create function to check VIP status\nCREATE OR REPLACE FUNCTION public.check_vip_status(p_user_id UUID)\nRETURNS TABLE(\n  is_vip BOOLEAN,\n  subscription_type TEXT,\n  status TEXT,\n  expires_at TIMESTAMPTZ,\n  days_remaining INTEGER\n)\nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nDECLARE\n  sub_record RECORD;\n  expires TIMESTAMPTZ;\n  remaining_days INTEGER;\nBEGIN\n  SELECT * INTO sub_record\n  FROM public.vip_subscriptions\n  WHERE user_id = p_user_id;\n  \n  IF NOT FOUND THEN\n    RETURN QUERY SELECT false, NULL::TEXT, NULL::TEXT, NULL::TIMESTAMPTZ, NULL::INTEGER;\n    RETURN;\n  END IF;\n  \n  -- Determine expiration date\n  IF sub_record.subscription_type = 'trial' THEN\n    expires := sub_record.trial_end_date;\n  ELSE\n    expires := sub_record.subscription_end_date;\n  END IF;\n  \n  -- Calculate remaining days\n  remaining_days := EXTRACT(DAY FROM (expires - now()));\n  \n  -- Check if expired\n  IF expires < now() AND sub_record.status = 'active' THEN\n    -- Update status to expired\n    UPDATE public.vip_subscriptions \n    SET status = 'expired', updated_at = now()\n    WHERE user_id = p_user_id;\n    \n    RETURN QUERY SELECT false, sub_record.subscription_type, 'expired'::TEXT, expires, remaining_days;\n  ELSE\n    RETURN QUERY SELECT \n      (sub_record.status = 'active'), \n      sub_record.subscription_type, \n      sub_record.status, \n      expires, \n      remaining_days;\n  END IF;\nEND;\n$$;"}		elvisiondragon@gmail.com	\N
20250811024422	{"-- Add Moota-specific fields to payment_transactions table\nALTER TABLE public.payment_transactions \nADD COLUMN moota_mutation_id TEXT,\nADD COLUMN bank_account TEXT,\nADD COLUMN unique_code INTEGER,\nADD COLUMN moota_webhook_data JSONB;\n\n-- Create index for faster lookups by unique code and amount\nCREATE INDEX idx_payment_transactions_moota_lookup \nON public.payment_transactions (amount, unique_code, status) \nWHERE unique_code IS NOT NULL;"}		elvisiondragon@gmail.com	\N
20250812073218	{"-- Fix critical security issue: Remove public access to chat_messages table\n-- Currently anyone can read all chat messages, usernames, and user data\n\n-- First, drop the existing public policy that allows anyone to view chat messages\nDROP POLICY IF EXISTS \\"Anyone can view chat messages\\" ON public.chat_messages;\n\n-- Create a proper policy that only allows authenticated users to view chat messages\nCREATE POLICY \\"Authenticated users can view chat messages\\" \nON public.chat_messages \nFOR SELECT \nTO authenticated\nUSING (true);\n\n-- Fix database functions security by setting proper search_path\n-- This prevents SQL injection attacks through search path manipulation\n\n-- Update award_xp function with secure search_path\nCREATE OR REPLACE FUNCTION public.award_xp(p_user_id uuid, p_xp_amount integer, p_activity_type text, p_reason text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path = public\nAS $function$\nDECLARE\n  new_total_xp INTEGER;\n  new_level INTEGER;\n  old_level INTEGER;\nBEGIN\n  -- Get current level\n  SELECT level INTO old_level FROM public.profiles WHERE user_id = p_user_id;\n  \n  -- Update experience points\n  UPDATE public.profiles \n  SET experience_points = experience_points + p_xp_amount,\n      updated_at = now()\n  WHERE user_id = p_user_id\n  RETURNING experience_points INTO new_total_xp;\n  \n  -- Calculate new level\n  new_level := public.calculate_level_from_xp(new_total_xp);\n  \n  -- Update level if changed\n  IF new_level != old_level THEN\n    UPDATE public.profiles \n    SET level = new_level,\n        updated_at = now()\n    WHERE user_id = p_user_id;\n  END IF;\n  \n  -- Log the activity\n  INSERT INTO public.user_activities (user_id, activity_type, xp_earned, metadata)\n  VALUES (p_user_id, p_activity_type, p_xp_amount, p_metadata);\n  \n  -- Log the XP transaction\n  INSERT INTO public.xp_transactions (user_id, xp_amount, transaction_type, reason)\n  VALUES (p_user_id, p_xp_amount, 'earned', COALESCE(p_reason, p_activity_type));\nEND;\n$function$;\n\n-- Update handle_new_user function with secure search_path\nCREATE OR REPLACE FUNCTION public.handle_new_user()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path = public\nAS $function$\nBEGIN\n  INSERT INTO public.profiles (user_id, display_name)\n  VALUES (\n    NEW.id, \n    COALESCE(NEW.raw_user_meta_data->>'display_name', NEW.email)\n  );\n  RETURN NEW;\nEND;\n$function$;\n\n-- Update check_daily_chat_limit function with secure search_path\nCREATE OR REPLACE FUNCTION public.check_daily_chat_limit(p_user_id uuid)\n RETURNS boolean\n LANGUAGE plpgsql\n SET search_path = public\nAS $function$\nDECLARE\n  daily_chat_count INTEGER;\nBEGIN\n  SELECT COUNT(*) INTO daily_chat_count\n  FROM public.user_activities\n  WHERE user_id = p_user_id\n    AND activity_type = 'chat_message'\n    AND created_at >= CURRENT_DATE;\n    \n  RETURN daily_chat_count < 10;\nEND;\n$function$;\n\n-- Update check_daily_journal_limit function with secure search_path\nCREATE OR REPLACE FUNCTION public.check_daily_journal_limit(p_user_id uuid)\n RETURNS boolean\n LANGUAGE plpgsql\n SET search_path = public\nAS $function$\nDECLARE\n  daily_journal_xp INTEGER;\nBEGIN\n  SELECT COALESCE(SUM(xp_earned), 0) INTO daily_journal_xp\n  FROM public.user_activities\n  WHERE user_id = p_user_id\n    AND activity_type = 'journal_entry'\n    AND created_at >= CURRENT_DATE;\n    \n  RETURN daily_journal_xp < 5;\nEND;\n$function$;\n\n-- Update check_daily_audio_limit function with secure search_path\nCREATE OR REPLACE FUNCTION public.check_daily_audio_limit(p_user_id uuid)\n RETURNS boolean\n LANGUAGE plpgsql\n SET search_path = public\nAS $function$\nDECLARE\n  daily_audio_xp INTEGER;\nBEGIN\n  SELECT COALESCE(SUM(xp_earned), 0) INTO daily_audio_xp\n  FROM public.user_activities\n  WHERE user_id = p_user_id\n    AND activity_type = 'audio_completed'\n    AND created_at >= CURRENT_DATE;\n    \n  RETURN daily_audio_xp < 20;\nEND;\n$function$;\n\n-- Update calculate_level_from_xp function with secure search_path\nCREATE OR REPLACE FUNCTION public.calculate_level_from_xp(total_xp integer)\n RETURNS integer\n LANGUAGE plpgsql\n SET search_path = public\nAS $function$\nDECLARE\n  level INTEGER := 1;\nBEGIN\n  -- Updated level requirements with level 2 now requiring 150 XP instead of 500\n  IF total_xp >= 15000 THEN\n    RETURN 9;\n  ELSIF total_xp >= 10000 THEN\n    RETURN 8;\n  ELSIF total_xp >= 7500 THEN\n    RETURN 7;\n  ELSIF total_xp >= 5000 THEN\n    RETURN 6;\n  ELSIF total_xp >= 4000 THEN\n    RETURN 5;\n  ELSIF total_xp >= 3000 THEN\n    RETURN 4;\n  ELSIF total_xp >= 1500 THEN\n    RETURN 3;\n  ELSIF total_xp >= 150 THEN\n    RETURN 2;\n  ELSIF total_xp >= 100 THEN\n    RETURN 1;\n  ELSE\n    RETURN 1;\n  END IF;\nEND;\n$function$;\n\n-- Update get_xp_for_next_level function with secure search_path\nCREATE OR REPLACE FUNCTION public.get_xp_for_next_level(current_level integer)\n RETURNS integer\n LANGUAGE plpgsql\n SET search_path = public\nAS $function$\nBEGIN\n  CASE current_level\n    WHEN 1 THEN RETURN 500;\n    WHEN 2 THEN RETURN 1500;\n    WHEN 3 THEN RETURN 3000;\n    WHEN 4 THEN RETURN 4000;\n    WHEN 5 THEN RETURN 5000;\n    WHEN 6 THEN RETURN 7500;\n    WHEN 7 THEN RETURN 10000;\n    WHEN 8 THEN RETURN 15000;\n    ELSE RETURN 15000; -- Max level reached\n  END CASE;\nEND;\n$function$;\n\n-- Update start_vip_trial function with secure search_path\nCREATE OR REPLACE FUNCTION public.start_vip_trial(p_user_id uuid, p_email text, p_ip_address text DEFAULT NULL::text)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path = public\nAS $function$\nDECLARE\n  subscription_id UUID;\n  trial_end TIMESTAMPTZ;\nBEGIN\n  -- Calculate trial end date (3 days from now)\n  trial_end := now() + INTERVAL '3 days';\n  \n  -- Insert or update VIP subscription\n  INSERT INTO public.vip_subscriptions (\n    user_id, \n    email, \n    ip_address,\n    subscription_type,\n    status,\n    trial_start_date,\n    trial_end_date\n  ) VALUES (\n    p_user_id, \n    p_email, \n    p_ip_address,\n    'trial',\n    'active',\n    now(),\n    trial_end\n  )\n  ON CONFLICT (user_id) \n  DO UPDATE SET\n    subscription_type = 'trial',\n    status = 'active',\n    trial_start_date = now(),\n    trial_end_date = trial_end,\n    updated_at = now()\n  RETURNING id INTO subscription_id;\n  \n  RETURN subscription_id;\nEND;\n$function$;\n\n-- Update check_vip_status function with secure search_path\nCREATE OR REPLACE FUNCTION public.check_vip_status(p_user_id uuid)\n RETURNS TABLE(is_vip boolean, subscription_type text, status text, expires_at timestamp with time zone, days_remaining integer)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path = public\nAS $function$\nDECLARE\n  sub_record RECORD;\n  expires TIMESTAMPTZ;\n  remaining_days INTEGER;\nBEGIN\n  SELECT * INTO sub_record\n  FROM public.vip_subscriptions\n  WHERE user_id = p_user_id;\n  \n  IF NOT FOUND THEN\n    RETURN QUERY SELECT false, NULL::TEXT, NULL::TEXT, NULL::TIMESTAMPTZ, NULL::INTEGER;\n    RETURN;\n  END IF;\n  \n  -- Determine expiration date\n  IF sub_record.subscription_type = 'trial' THEN\n    expires := sub_record.trial_end_date;\n  ELSE\n    expires := sub_record.subscription_end_date;\n  END IF;\n  \n  -- Calculate remaining days\n  remaining_days := EXTRACT(DAY FROM (expires - now()));\n  \n  -- Check if expired\n  IF expires < now() AND sub_record.status = 'active' THEN\n    -- Update status to expired\n    UPDATE public.vip_subscriptions \n    SET status = 'expired', updated_at = now()\n    WHERE user_id = p_user_id;\n    \n    RETURN QUERY SELECT false, sub_record.subscription_type, 'expired'::TEXT, expires, remaining_days;\n  ELSE\n    RETURN QUERY SELECT \n      (sub_record.status = 'active'), \n      sub_record.subscription_type, \n      sub_record.status, \n      expires, \n      remaining_days;\n  END IF;\nEND;\n$function$;"}		elvisiondragon@gmail.com	\N
20250812081520	{"-- Phase 1: Fix Critical Chat Message Privacy\n-- Drop the overly permissive policy that allows anyone to view chat messages\nDROP POLICY IF EXISTS \\"Authenticated users can view chat messages\\" ON public.chat_messages;\n\n-- Create a new policy that only allows authenticated users to view messages\nCREATE POLICY \\"Authenticated users can view chat messages\\" \nON public.chat_messages \nFOR SELECT \nUSING (auth.uid() IS NOT NULL);\n\n-- Phase 2: Strengthen VIP Subscriptions Security\n-- Add additional validation policy for subscription access\nCREATE POLICY \\"Admin can view all subscriptions\\" \nON public.vip_subscriptions \nFOR SELECT \nUSING (\n  EXISTS (\n    SELECT 1 FROM public.profiles \n    WHERE user_id = auth.uid() \n    AND 'admin' = ANY(achievements)\n  ) \n  OR auth.uid() = user_id\n);\n\n-- Phase 3: Database Function Security Hardening\n-- Update remaining functions that may be missing SET search_path\n\n-- Update handle_new_user function for security\nCREATE OR REPLACE FUNCTION public.handle_new_user()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $function$\nBEGIN\n  INSERT INTO public.profiles (user_id, display_name)\n  VALUES (\n    NEW.id, \n    COALESCE(NEW.raw_user_meta_data->>'display_name', NEW.email)\n  );\n  RETURN NEW;\nEND;\n$function$;\n\n-- Update get_xp_for_next_level function\nCREATE OR REPLACE FUNCTION public.get_xp_for_next_level(current_level integer)\nRETURNS integer\nLANGUAGE plpgsql\nSET search_path = public\nAS $function$\nBEGIN\n  CASE current_level\n    WHEN 1 THEN RETURN 150;\n    WHEN 2 THEN RETURN 1500;\n    WHEN 3 THEN RETURN 3000;\n    WHEN 4 THEN RETURN 4000;\n    WHEN 5 THEN RETURN 5000;\n    WHEN 6 THEN RETURN 7500;\n    WHEN 7 THEN RETURN 10000;\n    WHEN 8 THEN RETURN 15000;\n    ELSE RETURN 15000; -- Max level reached\n  END CASE;\nEND;\n$function$;\n\n-- Phase 4: Add audit logging for sensitive operations\nCREATE TABLE IF NOT EXISTS public.security_audit_log (\n  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,\n  user_id UUID,\n  action TEXT NOT NULL,\n  table_name TEXT,\n  record_id UUID,\n  ip_address TEXT,\n  user_agent TEXT,\n  metadata JSONB DEFAULT '{}',\n  created_at TIMESTAMPTZ DEFAULT now()\n);\n\n-- Enable RLS on audit log\nALTER TABLE public.security_audit_log ENABLE ROW LEVEL SECURITY;\n\n-- Only admins can view audit logs\nCREATE POLICY \\"Admins can view audit logs\\" \nON public.security_audit_log \nFOR SELECT \nUSING (\n  EXISTS (\n    SELECT 1 FROM public.profiles \n    WHERE user_id = auth.uid() \n    AND 'admin' = ANY(achievements)\n  )\n);\n\n-- System can insert audit logs\nCREATE POLICY \\"System can insert audit logs\\" \nON public.security_audit_log \nFOR INSERT \nWITH CHECK (true);\n\n-- Create function to log sensitive actions\nCREATE OR REPLACE FUNCTION public.log_sensitive_action(\n  p_action TEXT,\n  p_table_name TEXT DEFAULT NULL,\n  p_record_id UUID DEFAULT NULL,\n  p_metadata JSONB DEFAULT '{}'\n)\nRETURNS void\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $function$\nBEGIN\n  INSERT INTO public.security_audit_log (\n    user_id, \n    action, \n    table_name, \n    record_id, \n    metadata\n  ) VALUES (\n    auth.uid(), \n    p_action, \n    p_table_name, \n    p_record_id, \n    p_metadata\n  );\nEND;\n$function$;\n\n-- Phase 5: Add trigger for VIP subscription changes\nCREATE OR REPLACE FUNCTION public.audit_vip_changes()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $function$\nBEGIN\n  -- Log subscription status changes\n  IF TG_OP = 'UPDATE' AND OLD.status != NEW.status THEN\n    PERFORM public.log_sensitive_action(\n      'vip_subscription_status_change',\n      'vip_subscriptions',\n      NEW.id,\n      jsonb_build_object(\n        'old_status', OLD.status,\n        'new_status', NEW.status,\n        'user_email', NEW.email\n      )\n    );\n  END IF;\n  \n  -- Log new subscriptions\n  IF TG_OP = 'INSERT' THEN\n    PERFORM public.log_sensitive_action(\n      'vip_subscription_created',\n      'vip_subscriptions',\n      NEW.id,\n      jsonb_build_object(\n        'subscription_type', NEW.subscription_type,\n        'user_email', NEW.email\n      )\n    );\n  END IF;\n  \n  RETURN COALESCE(NEW, OLD);\nEND;\n$function$;\n\n-- Create trigger for VIP subscription auditing\nDROP TRIGGER IF EXISTS audit_vip_subscription_changes ON public.vip_subscriptions;\nCREATE TRIGGER audit_vip_subscription_changes\n  AFTER INSERT OR UPDATE ON public.vip_subscriptions\n  FOR EACH ROW\n  EXECUTE FUNCTION public.audit_vip_changes();"}		elvisiondragon@gmail.com	\N
20250812082016	{"-- Phase 1: Fix Critical Chat Message Privacy (if needed)\nDROP POLICY IF EXISTS \\"Authenticated users can view chat messages\\" ON public.chat_messages;\nCREATE POLICY \\"Authenticated users can view chat messages\\" \nON public.chat_messages \nFOR SELECT \nUSING (auth.uid() IS NOT NULL);\n\n-- Phase 2: Strengthen VIP Subscriptions Security (handle existing policy)\nDROP POLICY IF EXISTS \\"Admin can view all subscriptions\\" ON public.vip_subscriptions;\nCREATE POLICY \\"Admin can view all subscriptions\\" \nON public.vip_subscriptions \nFOR SELECT \nUSING (\n  EXISTS (\n    SELECT 1 FROM public.profiles \n    WHERE user_id = auth.uid() \n    AND 'admin' = ANY(achievements)\n  ) \n  OR auth.uid() = user_id\n);\n\n-- Phase 3: Ensure audit logging table exists\nCREATE TABLE IF NOT EXISTS public.security_audit_log (\n  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,\n  user_id UUID,\n  action TEXT NOT NULL,\n  table_name TEXT,\n  record_id UUID,\n  ip_address TEXT,\n  user_agent TEXT,\n  metadata JSONB DEFAULT '{}',\n  created_at TIMESTAMPTZ DEFAULT now()\n);\n\n-- Enable RLS on audit log (safe to run multiple times)\nALTER TABLE public.security_audit_log ENABLE ROW LEVEL SECURITY;\n\n-- Recreate audit log policies safely\nDROP POLICY IF EXISTS \\"Admins can view audit logs\\" ON public.security_audit_log;\nCREATE POLICY \\"Admins can view audit logs\\" \nON public.security_audit_log \nFOR SELECT \nUSING (\n  EXISTS (\n    SELECT 1 FROM public.profiles \n    WHERE user_id = auth.uid() \n    AND 'admin' = ANY(achievements)\n  )\n);\n\nDROP POLICY IF EXISTS \\"System can insert audit logs\\" ON public.security_audit_log;\nCREATE POLICY \\"System can insert audit logs\\" \nON public.security_audit_log \nFOR INSERT \nWITH CHECK (true);\n\n-- Phase 4: Add comprehensive data access logging\nCREATE OR REPLACE FUNCTION public.log_data_access(\n  p_table_name TEXT,\n  p_operation TEXT,\n  p_record_id UUID DEFAULT NULL,\n  p_metadata JSONB DEFAULT '{}'\n)\nRETURNS void\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $function$\nBEGIN\n  -- Only log if user is authenticated\n  IF auth.uid() IS NOT NULL THEN\n    INSERT INTO public.security_audit_log (\n      user_id, \n      action, \n      table_name, \n      record_id, \n      metadata\n    ) VALUES (\n      auth.uid(), \n      p_operation || '_' || p_table_name,\n      p_table_name, \n      p_record_id, \n      p_metadata\n    );\n  END IF;\nEND;\n$function$;\n\n-- Phase 5: Enhanced payment data security\n-- Add trigger to log sensitive payment data access\nCREATE OR REPLACE FUNCTION public.audit_payment_access()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $function$\nBEGIN\n  -- Log payment transaction access\n  IF TG_OP = 'SELECT' THEN\n    PERFORM public.log_data_access(\n      'payment_transactions',\n      'access',\n      OLD.id,\n      jsonb_build_object(\n        'amount', OLD.amount,\n        'status', OLD.status\n      )\n    );\n  END IF;\n  \n  RETURN COALESCE(NEW, OLD);\nEND;\n$function$;\n\n-- Phase 6: Add rate limiting table for enhanced security\nCREATE TABLE IF NOT EXISTS public.rate_limit_log (\n  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,\n  user_id UUID,\n  ip_address TEXT,\n  action TEXT NOT NULL,\n  attempts INTEGER DEFAULT 1,\n  window_start TIMESTAMPTZ DEFAULT now(),\n  created_at TIMESTAMPTZ DEFAULT now()\n);\n\n-- Enable RLS on rate limit log\nALTER TABLE public.rate_limit_log ENABLE ROW LEVEL SECURITY;\n\n-- Only system can access rate limit logs\nCREATE POLICY \\"System can manage rate limits\\" \nON public.rate_limit_log \nFOR ALL \nUSING (auth.uid() IS NULL OR EXISTS (\n  SELECT 1 FROM public.profiles \n  WHERE user_id = auth.uid() \n  AND 'admin' = ANY(achievements)\n));"}		elvisiondragon@gmail.com	\N
20250812082047	{"-- Fix remaining functions that need SET search_path\nCREATE OR REPLACE FUNCTION public.calculate_level_from_xp(total_xp integer)\nRETURNS integer\nLANGUAGE plpgsql\nSET search_path = public\nAS $function$\nDECLARE\n  level INTEGER := 1;\nBEGIN\n  -- Updated level requirements with level 2 now requiring 150 XP instead of 500\n  IF total_xp >= 15000 THEN\n    RETURN 9;\n  ELSIF total_xp >= 10000 THEN\n    RETURN 8;\n  ELSIF total_xp >= 7500 THEN\n    RETURN 7;\n  ELSIF total_xp >= 5000 THEN\n    RETURN 6;\n  ELSIF total_xp >= 4000 THEN\n    RETURN 5;\n  ELSIF total_xp >= 3000 THEN\n    RETURN 4;\n  ELSIF total_xp >= 1500 THEN\n    RETURN 3;\n  ELSIF total_xp >= 150 THEN\n    RETURN 2;\n  ELSIF total_xp >= 100 THEN\n    RETURN 1;\n  ELSE\n    RETURN 1;\n  END IF;\nEND;\n$function$;\n\nCREATE OR REPLACE FUNCTION public.check_daily_chat_limit(p_user_id uuid)\nRETURNS boolean\nLANGUAGE plpgsql\nSET search_path = public\nAS $function$\nDECLARE\n  daily_chat_count INTEGER;\nBEGIN\n  SELECT COUNT(*) INTO daily_chat_count\n  FROM public.user_activities\n  WHERE user_id = p_user_id\n    AND activity_type = 'chat_message'\n    AND created_at >= CURRENT_DATE;\n    \n  RETURN daily_chat_count < 10;\nEND;\n$function$;\n\nCREATE OR REPLACE FUNCTION public.check_daily_journal_limit(p_user_id uuid)\nRETURNS boolean\nLANGUAGE plpgsql\nSET search_path = public\nAS $function$\nDECLARE\n  daily_journal_xp INTEGER;\nBEGIN\n  SELECT COALESCE(SUM(xp_earned), 0) INTO daily_journal_xp\n  FROM public.user_activities\n  WHERE user_id = p_user_id\n    AND activity_type = 'journal_entry'\n    AND created_at >= CURRENT_DATE;\n    \n  RETURN daily_journal_xp < 5;\nEND;\n$function$;\n\nCREATE OR REPLACE FUNCTION public.check_daily_audio_limit(p_user_id uuid)\nRETURNS boolean\nLANGUAGE plpgsql\nSET search_path = public\nAS $function$\nDECLARE\n  daily_audio_xp INTEGER;\nBEGIN\n  SELECT COALESCE(SUM(xp_earned), 0) INTO daily_audio_xp\n  FROM public.user_activities\n  WHERE user_id = p_user_id\n    AND activity_type = 'audio_completed'\n    AND created_at >= CURRENT_DATE;\n    \n  RETURN daily_audio_xp < 20;\nEND;\n$function$;"}		elvisiondragon@gmail.com	\N
20250812042708	{"-- Fix critical chat message privacy issue\n-- Replace the overly permissive policy with proper access control\nDROP POLICY IF EXISTS \\"Authenticated users can view chat messages\\" ON public.chat_messages;\n\n-- Create new policy that allows users to view messages only in public community chat\n-- This assumes this is a public community chat feature\nCREATE POLICY \\"Users can view public community chat messages\\" \nON public.chat_messages \nFOR SELECT \nUSING (auth.uid() IS NOT NULL);\n\n-- Add channel support for future chat room functionality\nALTER TABLE public.chat_messages \nADD COLUMN IF NOT EXISTS channel_id TEXT DEFAULT 'community';\n\n-- Create index for better performance on channel queries\nCREATE INDEX IF NOT EXISTS idx_chat_messages_channel_id ON public.chat_messages(channel_id);\n\n-- Harden database functions with proper search_path\nCREATE OR REPLACE FUNCTION public.update_updated_at_column()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $function$\nBEGIN\n  NEW.updated_at = now();\n  RETURN NEW;\nEND;\n$function$;\n\nCREATE OR REPLACE FUNCTION public.handle_new_user()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $function$\nBEGIN\n  INSERT INTO public.profiles (user_id, display_name)\n  VALUES (\n    NEW.id, \n    COALESCE(NEW.raw_user_meta_data->>'display_name', NEW.email)\n  );\n  RETURN NEW;\nEND;\n$function$;\n\n-- Add audit logging for chat message access\nCREATE OR REPLACE FUNCTION public.audit_chat_access()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $function$\nBEGIN\n  -- Log chat message creation for monitoring\n  IF TG_OP = 'INSERT' THEN\n    PERFORM public.log_data_access(\n      'chat_messages',\n      'message_sent',\n      NEW.id,\n      jsonb_build_object(\n        'channel_id', NEW.channel_id,\n        'message_length', length(NEW.message)\n      )\n    );\n  END IF;\n  \n  RETURN COALESCE(NEW, OLD);\nEND;\n$function$;\n\n-- Create trigger for chat audit logging\nCREATE TRIGGER audit_chat_messages_trigger\n  AFTER INSERT ON public.chat_messages\n  FOR EACH ROW\n  EXECUTE FUNCTION public.audit_chat_access();\n\n-- Enhance financial data protection\nCREATE OR REPLACE FUNCTION public.audit_subscription_access()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $function$\nBEGIN\n  -- Log VIP subscription access\n  IF TG_OP = 'SELECT' THEN\n    PERFORM public.log_data_access(\n      'vip_subscriptions',\n      'subscription_access',\n      OLD.id,\n      jsonb_build_object(\n        'subscription_type', OLD.subscription_type,\n        'status', OLD.status\n      )\n    );\n  END IF;\n  \n  RETURN COALESCE(NEW, OLD);\nEND;\n$function$;\n\n-- Add rate limiting for sensitive operations\nCREATE OR REPLACE FUNCTION public.check_rate_limit(\n  p_user_id UUID,\n  p_action TEXT,\n  p_max_attempts INTEGER DEFAULT 10,\n  p_window_minutes INTEGER DEFAULT 60\n)\nRETURNS BOOLEAN\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $function$\nDECLARE\n  attempt_count INTEGER;\n  window_start TIMESTAMPTZ;\nBEGIN\n  window_start := now() - (p_window_minutes || ' minutes')::INTERVAL;\n  \n  SELECT COUNT(*) INTO attempt_count\n  FROM public.rate_limit_log\n  WHERE user_id = p_user_id\n    AND action = p_action\n    AND created_at > window_start;\n  \n  -- Log this attempt\n  INSERT INTO public.rate_limit_log (user_id, action, ip_address)\n  VALUES (p_user_id, p_action, inet_client_addr()::TEXT);\n  \n  RETURN attempt_count < p_max_attempts;\nEND;\n$function$;\n\n-- Create secure function for payment access validation\nCREATE OR REPLACE FUNCTION public.validate_payment_access(p_user_id UUID, p_transaction_id UUID)\nRETURNS BOOLEAN\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $function$\nDECLARE\n  is_owner BOOLEAN;\nBEGIN\n  -- Check if user owns the transaction\n  SELECT EXISTS(\n    SELECT 1 FROM public.payment_transactions \n    WHERE id = p_transaction_id AND user_id = p_user_id\n  ) INTO is_owner;\n  \n  -- Log access attempt\n  PERFORM public.log_data_access(\n    'payment_transactions',\n    'access_validation',\n    p_transaction_id,\n    jsonb_build_object(\n      'requesting_user', p_user_id,\n      'access_granted', is_owner\n    )\n  );\n  \n  RETURN is_owner;\nEND;\n$function$;"}		elvisiondragon@gmail.com	\N
20250812043050	{"-- CRITICAL SECURITY FIX: Secure customer email and subscription data\n-- This migration addresses multiple security vulnerabilities in financial and subscription data\n\n-- 1. Create a separate secure table for email storage with enhanced protection\nCREATE TABLE IF NOT EXISTS public.user_contact_info (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  user_id UUID NOT NULL UNIQUE,\n  email_encrypted TEXT NOT NULL, -- Will store encrypted email\n  email_hash TEXT NOT NULL, -- For lookup without revealing email\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\n-- Enable RLS on the new contact info table\nALTER TABLE public.user_contact_info ENABLE ROW LEVEL SECURITY;\n\n-- Create ultra-restrictive policies for contact info\nCREATE POLICY \\"Users can only view their own contact info\\"\nON public.user_contact_info\nFOR SELECT\nUSING (auth.uid() = user_id);\n\nCREATE POLICY \\"Users can only insert their own contact info\\"\nON public.user_contact_info\nFOR INSERT\nWITH CHECK (auth.uid() = user_id);\n\nCREATE POLICY \\"Users can only update their own contact info\\"\nON public.user_contact_info\nFOR UPDATE\nUSING (auth.uid() = user_id);\n\n-- 2. Remove email column from vip_subscriptions to eliminate exposure\n-- First, backup existing emails in the new secure table\nINSERT INTO public.user_contact_info (user_id, email_encrypted, email_hash)\nSELECT \n  user_id,\n  email, -- TODO: This should be encrypted in production\n  encode(digest(email, 'sha256'), 'hex')\nFROM public.vip_subscriptions\nWHERE email IS NOT NULL\nON CONFLICT (user_id) DO NOTHING;\n\n-- Remove the exposed email column\nALTER TABLE public.vip_subscriptions DROP COLUMN IF EXISTS email;\n\n-- 3. Strengthen RLS policies for vip_subscriptions\n-- Drop existing admin policy that's too permissive\nDROP POLICY IF EXISTS \\"Admin can view all subscriptions\\" ON public.vip_subscriptions;\n\n-- Create more restrictive admin access through a secure function\nCREATE OR REPLACE FUNCTION public.is_verified_admin(p_user_id UUID)\nRETURNS BOOLEAN\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $function$\nBEGIN\n  -- More restrictive admin check - requires specific admin role\n  RETURN EXISTS (\n    SELECT 1 FROM public.profiles \n    WHERE user_id = p_user_id \n    AND 'verified_admin' = ANY(achievements)\n  );\nEND;\n$function$;\n\n-- New restrictive admin policy\nCREATE POLICY \\"Verified admins can view subscriptions\\"\nON public.vip_subscriptions\nFOR SELECT\nUSING (\n  (auth.uid() = user_id) OR \n  public.is_verified_admin(auth.uid())\n);\n\n-- 4. Enhanced security for payment_transactions\n-- Create function to validate payment access with additional security checks\nCREATE OR REPLACE FUNCTION public.can_access_payment_transaction(\n  p_user_id UUID, \n  p_transaction_id UUID\n)\nRETURNS BOOLEAN\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $function$\nDECLARE\n  is_owner BOOLEAN := FALSE;\n  is_admin BOOLEAN := FALSE;\nBEGIN\n  -- Check ownership\n  SELECT EXISTS(\n    SELECT 1 FROM public.payment_transactions \n    WHERE id = p_transaction_id AND user_id = p_user_id\n  ) INTO is_owner;\n  \n  -- Check verified admin status\n  is_admin := public.is_verified_admin(p_user_id);\n  \n  -- Log access attempt for audit\n  PERFORM public.log_data_access(\n    'payment_transactions',\n    'access_attempt',\n    p_transaction_id,\n    jsonb_build_object(\n      'requesting_user', p_user_id,\n      'is_owner', is_owner,\n      'is_admin', is_admin,\n      'access_granted', (is_owner OR is_admin)\n    )\n  );\n  \n  RETURN (is_owner OR is_admin);\nEND;\n$function$;\n\n-- Update payment transaction policies to use the secure function\nDROP POLICY IF EXISTS \\"Users can view their own transactions\\" ON public.payment_transactions;\n\nCREATE POLICY \\"Secure payment transaction access\\"\nON public.payment_transactions\nFOR SELECT\nUSING (public.can_access_payment_transaction(auth.uid(), id));\n\n-- 5. Add data classification and protection metadata\nCREATE TABLE IF NOT EXISTS public.data_classification (\n  table_name TEXT PRIMARY KEY,\n  classification TEXT NOT NULL, -- 'public', 'internal', 'confidential', 'restricted'\n  pii_fields TEXT[], -- List of fields containing PII\n  retention_days INTEGER,\n  audit_required BOOLEAN DEFAULT TRUE,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\n-- Classify our sensitive tables\nINSERT INTO public.data_classification (table_name, classification, pii_fields, retention_days, audit_required)\nVALUES \n  ('user_contact_info', 'restricted', ARRAY['email_encrypted'], 2555, TRUE), -- 7 years\n  ('vip_subscriptions', 'confidential', ARRAY['ip_address'], 2555, TRUE),\n  ('payment_transactions', 'restricted', ARRAY['bank_account', 'moota_webhook_data'], 2555, TRUE),\n  ('device_tokens', 'confidential', ARRAY['token', 'platform'], 365, TRUE)\nON CONFLICT (table_name) DO UPDATE SET\n  classification = EXCLUDED.classification,\n  pii_fields = EXCLUDED.pii_fields,\n  retention_days = EXCLUDED.retention_days,\n  audit_required = EXCLUDED.audit_required;\n\n-- 6. Create a secure function to retrieve user email when needed\nCREATE OR REPLACE FUNCTION public.get_user_email_secure(p_user_id UUID)\nRETURNS TEXT\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $function$\nDECLARE\n  user_email TEXT;\nBEGIN\n  -- Only allow users to get their own email or verified admins\n  IF auth.uid() != p_user_id AND NOT public.is_verified_admin(auth.uid()) THEN\n    RAISE EXCEPTION 'Access denied: Cannot retrieve email for other users';\n  END IF;\n  \n  -- Log access for audit\n  PERFORM public.log_data_access(\n    'user_contact_info',\n    'email_access',\n    p_user_id,\n    jsonb_build_object(\n      'requesting_user', auth.uid(),\n      'target_user', p_user_id\n    )\n  );\n  \n  SELECT email_encrypted INTO user_email\n  FROM public.user_contact_info\n  WHERE user_id = p_user_id;\n  \n  RETURN user_email;\nEND;\n$function$;\n\n-- 7. Create a view for safe subscription display (without sensitive data)\nCREATE OR REPLACE VIEW public.subscription_summary AS\nSELECT \n  id,\n  user_id,\n  subscription_type,\n  status,\n  trial_start_date,\n  trial_end_date,\n  subscription_start_date,\n  subscription_end_date,\n  -- Mask sensitive fields\n  CASE \n    WHEN auth.uid() = user_id THEN currency\n    ELSE '***'\n  END as currency,\n  CASE \n    WHEN auth.uid() = user_id THEN amount_paid\n    ELSE NULL\n  END as amount_paid,\n  created_at,\n  updated_at\nFROM public.vip_subscriptions\nWHERE auth.uid() = user_id OR public.is_verified_admin(auth.uid());\n\n-- Grant appropriate permissions\nGRANT SELECT ON public.subscription_summary TO authenticated;\n\n-- 8. Add rate limiting for sensitive data access\nCREATE OR REPLACE FUNCTION public.check_sensitive_data_rate_limit(\n  p_user_id UUID,\n  p_table_name TEXT\n)\nRETURNS BOOLEAN\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $function$\nBEGIN\n  -- Stricter rate limits for sensitive data access\n  RETURN public.check_rate_limit(\n    p_user_id, \n    'sensitive_data_access_' || p_table_name,\n    5, -- Max 5 attempts\n    15 -- Per 15 minutes\n  );\nEND;\n$function$;"}		elvisiondragon@gmail.com	\N
20250812043249	{"-- Fix security issues introduced in the previous migration\n\n-- 1. Fix the Security Definer View issue by dropping it and creating proper RLS policies instead\nDROP VIEW IF EXISTS public.subscription_summary;\n\n-- 2. Enable RLS on the data_classification table (this was missing)\nALTER TABLE public.data_classification ENABLE ROW LEVEL SECURITY;\n\n-- Create restrictive policy for data_classification table - only verified admins can access\nCREATE POLICY \\"Only verified admins can view data classification\\"\nON public.data_classification\nFOR SELECT\nUSING (public.is_verified_admin(auth.uid()));\n\nCREATE POLICY \\"Only verified admins can manage data classification\\"\nON public.data_classification\nFOR ALL\nUSING (public.is_verified_admin(auth.uid()));\n\n-- 3. Instead of the problematic view, create a secure function for subscription display\nCREATE OR REPLACE FUNCTION public.get_safe_subscription_data(p_user_id UUID)\nRETURNS TABLE(\n  id UUID,\n  user_id UUID,\n  subscription_type TEXT,\n  status TEXT,\n  trial_start_date TIMESTAMPTZ,\n  trial_end_date TIMESTAMPTZ,\n  subscription_start_date TIMESTAMPTZ,\n  subscription_end_date TIMESTAMPTZ,\n  masked_currency TEXT,\n  masked_amount NUMERIC\n)\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $function$\nBEGIN\n  -- Only allow users to get their own data or verified admins\n  IF auth.uid() != p_user_id AND NOT public.is_verified_admin(auth.uid()) THEN\n    RAISE EXCEPTION 'Access denied: Cannot retrieve subscription data for other users';\n  END IF;\n  \n  -- Log access for audit\n  PERFORM public.log_data_access(\n    'vip_subscriptions',\n    'safe_subscription_access',\n    p_user_id,\n    jsonb_build_object(\n      'requesting_user', auth.uid(),\n      'target_user', p_user_id\n    )\n  );\n  \n  RETURN QUERY\n  SELECT \n    s.id,\n    s.user_id,\n    s.subscription_type,\n    s.status,\n    s.trial_start_date,\n    s.trial_end_date,\n    s.subscription_start_date,\n    s.subscription_end_date,\n    -- Mask sensitive fields based on access level\n    CASE \n      WHEN auth.uid() = s.user_id THEN s.currency\n      ELSE '***'\n    END as masked_currency,\n    CASE \n      WHEN auth.uid() = s.user_id THEN s.amount_paid\n      ELSE NULL\n    END as masked_amount\n  FROM public.vip_subscriptions s\n  WHERE s.user_id = p_user_id;\nEND;\n$function$;\n\n-- 4. Create additional security policies for device_tokens to address the warning\n-- Update existing policies to be more restrictive\nDROP POLICY IF EXISTS \\"Users can view their own device tokens\\" ON public.device_tokens;\nDROP POLICY IF EXISTS \\"Users can insert their own device tokens\\" ON public.device_tokens;\nDROP POLICY IF EXISTS \\"Users can update their own device tokens\\" ON public.device_tokens;\nDROP POLICY IF EXISTS \\"Users can delete their own device tokens\\" ON public.device_tokens;\n\n-- Create more restrictive policies with rate limiting\nCREATE POLICY \\"Secure device token access\\"\nON public.device_tokens\nFOR SELECT\nUSING (\n  auth.uid() = user_id AND \n  public.check_sensitive_data_rate_limit(auth.uid(), 'device_tokens')\n);\n\nCREATE POLICY \\"Secure device token insert\\"\nON public.device_tokens\nFOR INSERT\nWITH CHECK (\n  auth.uid() = user_id AND \n  public.check_sensitive_data_rate_limit(auth.uid(), 'device_tokens')\n);\n\nCREATE POLICY \\"Secure device token update\\"\nON public.device_tokens\nFOR UPDATE\nUSING (\n  auth.uid() = user_id AND \n  public.check_sensitive_data_rate_limit(auth.uid(), 'device_tokens')\n);\n\nCREATE POLICY \\"Secure device token delete\\"\nON public.device_tokens\nFOR DELETE\nUSING (\n  auth.uid() = user_id AND \n  public.check_sensitive_data_rate_limit(auth.uid(), 'device_tokens')\n);\n\n-- 5. Add additional protection for user_contact_info with rate limiting\nDROP POLICY IF EXISTS \\"Users can only view their own contact info\\" ON public.user_contact_info;\nDROP POLICY IF EXISTS \\"Users can only insert their own contact info\\" ON public.user_contact_info;\nDROP POLICY IF EXISTS \\"Users can only update their own contact info\\" ON public.user_contact_info;\n\nCREATE POLICY \\"Ultra secure contact info access\\"\nON public.user_contact_info\nFOR SELECT\nUSING (\n  auth.uid() = user_id AND \n  public.check_sensitive_data_rate_limit(auth.uid(), 'user_contact_info')\n);\n\nCREATE POLICY \\"Ultra secure contact info insert\\"\nON public.user_contact_info\nFOR INSERT\nWITH CHECK (\n  auth.uid() = user_id AND \n  public.check_sensitive_data_rate_limit(auth.uid(), 'user_contact_info')\n);\n\nCREATE POLICY \\"Ultra secure contact info update\\"\nON public.user_contact_info\nFOR UPDATE\nUSING (\n  auth.uid() = user_id AND \n  public.check_sensitive_data_rate_limit(auth.uid(), 'user_contact_info')\n);\n\n-- 6. Create a data access monitoring function\nCREATE OR REPLACE FUNCTION public.monitor_sensitive_data_access()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $function$\nBEGIN\n  -- Enhanced monitoring for sensitive table access\n  IF TG_TABLE_NAME IN ('user_contact_info', 'payment_transactions', 'vip_subscriptions', 'device_tokens') THEN\n    -- Check for suspicious access patterns\n    PERFORM public.log_sensitive_action(\n      'sensitive_table_access',\n      TG_TABLE_NAME,\n      COALESCE(NEW.id, OLD.id),\n      jsonb_build_object(\n        'operation', TG_OP,\n        'table', TG_TABLE_NAME,\n        'timestamp', now(),\n        'user_agent', current_setting('request.headers', true)::jsonb->>'user-agent'\n      )\n    );\n  END IF;\n  \n  RETURN COALESCE(NEW, OLD);\nEND;\n$function$;\n\n-- Apply monitoring triggers\nCREATE TRIGGER monitor_user_contact_info_access\n  AFTER INSERT OR UPDATE OR DELETE ON public.user_contact_info\n  FOR EACH ROW\n  EXECUTE FUNCTION public.monitor_sensitive_data_access();\n\nCREATE TRIGGER monitor_device_tokens_access\n  AFTER INSERT OR UPDATE OR DELETE ON public.device_tokens\n  FOR EACH ROW\n  EXECUTE FUNCTION public.monitor_sensitive_data_access();"}		elvisiondragon@gmail.com	\N
20250812043711	{"-- FINAL SECURITY HARDENING: Fix remaining critical vulnerabilities (corrected)\n\n-- 1. Fix admin privilege escalation vulnerability\n-- Create a separate admin roles table that users cannot modify\nCREATE TABLE IF NOT EXISTS public.admin_roles (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  user_id UUID NOT NULL UNIQUE,\n  role TEXT NOT NULL, -- 'admin', 'super_admin', 'moderator'\n  granted_by UUID NOT NULL, -- Who granted this role\n  granted_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  expires_at TIMESTAMPTZ, -- Optional expiration\n  is_active BOOLEAN NOT NULL DEFAULT true\n);\n\n-- Enable RLS but make it very restrictive\nALTER TABLE public.admin_roles ENABLE ROW LEVEL SECURITY;\n\n-- Only super admins can view and manage admin roles\nCREATE POLICY \\"Only super admins can manage admin roles\\"\nON public.admin_roles\nFOR ALL\nUSING (\n  EXISTS (\n    SELECT 1 FROM public.admin_roles ar \n    WHERE ar.user_id = auth.uid() \n    AND ar.role = 'super_admin' \n    AND ar.is_active = true\n    AND (ar.expires_at IS NULL OR ar.expires_at > now())\n  )\n);\n\n-- 2. Update the is_verified_admin function to use the new admin_roles table\nCREATE OR REPLACE FUNCTION public.is_verified_admin(p_user_id UUID)\nRETURNS BOOLEAN\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $function$\nBEGIN\n  -- Check the admin_roles table instead of profile achievements\n  RETURN EXISTS (\n    SELECT 1 FROM public.admin_roles \n    WHERE user_id = p_user_id \n    AND role IN ('admin', 'super_admin')\n    AND is_active = true\n    AND (expires_at IS NULL OR expires_at > now())\n  );\nEND;\n$function$;\n\n-- 3. Fix chat message privacy issue - implement proper channel-based access\n-- Add better channel support to chat messages\nALTER TABLE public.chat_messages \nADD COLUMN IF NOT EXISTS is_private BOOLEAN DEFAULT false,\nADD COLUMN IF NOT EXISTS allowed_users UUID[] DEFAULT NULL;\n\n-- Create index for better performance\nCREATE INDEX IF NOT EXISTS idx_chat_messages_privacy ON public.chat_messages(channel_id, is_private);\n\n-- Replace the permissive chat policy with channel-based access control\nDROP POLICY IF EXISTS \\"Users can view public community chat messages\\" ON public.chat_messages;\n\nCREATE POLICY \\"Channel-based chat message access\\"\nON public.chat_messages\nFOR SELECT\nUSING (\n  auth.uid() IS NOT NULL AND (\n    -- Public community messages\n    (channel_id = 'community' AND is_private = false) OR\n    -- Private messages where user is explicitly allowed\n    (is_private = true AND auth.uid() = ANY(allowed_users)) OR\n    -- User's own messages\n    (auth.uid() = user_id) OR\n    -- Admin access\n    public.is_verified_admin(auth.uid())\n  )\n);\n\n-- 4. Create a secure chat message creation function\nCREATE OR REPLACE FUNCTION public.create_chat_message(\n  p_message TEXT,\n  p_channel_id TEXT DEFAULT 'community',\n  p_is_private BOOLEAN DEFAULT false,\n  p_allowed_users UUID[] DEFAULT NULL\n)\nRETURNS UUID\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $function$\nDECLARE\n  message_id UUID;\n  user_profile RECORD;\nBEGIN\n  -- Check authentication\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'Authentication required';\n  END IF;\n  \n  -- Check rate limiting\n  IF NOT public.check_sensitive_data_rate_limit(auth.uid(), 'chat_messages') THEN\n    RAISE EXCEPTION 'Rate limit exceeded for chat messages';\n  END IF;\n  \n  -- Get user profile for level and pro status\n  SELECT level, 'pro' = ANY(achievements) as is_pro, display_name\n  INTO user_profile\n  FROM public.profiles\n  WHERE user_id = auth.uid();\n  \n  -- Insert the message\n  INSERT INTO public.chat_messages (\n    user_id,\n    user_name, \n    user_level,\n    is_pro,\n    message,\n    channel_id,\n    is_private,\n    allowed_users\n  ) VALUES (\n    auth.uid(),\n    COALESCE(user_profile.display_name, 'Anonymous'),\n    COALESCE(user_profile.level, 1),\n    COALESCE(user_profile.is_pro, false),\n    p_message,\n    p_channel_id,\n    p_is_private,\n    p_allowed_users\n  ) RETURNING id INTO message_id;\n  \n  -- Log the message creation\n  PERFORM public.log_data_access(\n    'chat_messages',\n    'message_created',\n    message_id,\n    jsonb_build_object(\n      'channel_id', p_channel_id,\n      'is_private', p_is_private,\n      'message_length', length(p_message)\n    )\n  );\n  \n  RETURN message_id;\nEND;\n$function$;\n\n-- 5. Create function to safely grant admin roles (only callable by super admins)\nCREATE OR REPLACE FUNCTION public.grant_admin_role(\n  p_target_user_id UUID,\n  p_role TEXT,\n  p_expires_at TIMESTAMPTZ DEFAULT NULL\n)\nRETURNS BOOLEAN\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $function$\nBEGIN\n  -- Only super admins can grant roles\n  IF NOT EXISTS (\n    SELECT 1 FROM public.admin_roles \n    WHERE user_id = auth.uid() \n    AND role = 'super_admin' \n    AND is_active = true\n    AND (expires_at IS NULL OR expires_at > now())\n  ) THEN\n    RAISE EXCEPTION 'Only super admins can grant admin roles';\n  END IF;\n  \n  -- Validate role\n  IF p_role NOT IN ('admin', 'moderator') THEN\n    RAISE EXCEPTION 'Invalid role. Only admin or moderator roles can be granted';\n  END IF;\n  \n  -- Insert the role\n  INSERT INTO public.admin_roles (user_id, role, granted_by, expires_at)\n  VALUES (p_target_user_id, p_role, auth.uid(), p_expires_at)\n  ON CONFLICT (user_id) DO UPDATE SET\n    role = EXCLUDED.role,\n    granted_by = EXCLUDED.granted_by,\n    granted_at = now(),\n    expires_at = EXCLUDED.expires_at,\n    is_active = true;\n  \n  -- Log the role grant\n  PERFORM public.log_sensitive_action(\n    'admin_role_granted',\n    'admin_roles',\n    p_target_user_id,\n    jsonb_build_object(\n      'target_user', p_target_user_id,\n      'role_granted', p_role,\n      'granted_by', auth.uid(),\n      'expires_at', p_expires_at\n    )\n  );\n  \n  RETURN true;\nEND;\n$function$;\n\n-- 6. Add emergency admin role revocation function\nCREATE OR REPLACE FUNCTION public.revoke_admin_role(p_target_user_id UUID)\nRETURNS BOOLEAN\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $function$\nBEGIN\n  -- Only super admins can revoke roles\n  IF NOT EXISTS (\n    SELECT 1 FROM public.admin_roles \n    WHERE user_id = auth.uid() \n    AND role = 'super_admin' \n    AND is_active = true\n    AND (expires_at IS NULL OR expires_at > now())\n  ) THEN\n    RAISE EXCEPTION 'Only super admins can revoke admin roles';\n  END IF;\n  \n  -- Revoke the role\n  UPDATE public.admin_roles \n  SET is_active = false \n  WHERE user_id = p_target_user_id;\n  \n  -- Log the revocation\n  PERFORM public.log_sensitive_action(\n    'admin_role_revoked',\n    'admin_roles',\n    p_target_user_id,\n    jsonb_build_object(\n      'target_user', p_target_user_id,\n      'revoked_by', auth.uid()\n    )\n  );\n  \n  RETURN true;\nEND;\n$function$;"}		elvisiondragon@gmail.com	\N
20250812044241	{"-- Add missing SELECT policy for admin_roles table\n-- This allows users to view their own roles and super admins to view all roles\nCREATE POLICY \\"Users can view relevant admin roles\\" \nON public.admin_roles \nFOR SELECT \nUSING (\n  -- Users can see their own roles\n  auth.uid() = user_id \n  OR \n  -- Super admins can see all roles\n  EXISTS (\n    SELECT 1 FROM public.admin_roles ar \n    WHERE ar.user_id = auth.uid() \n    AND ar.role = 'super_admin' \n    AND ar.is_active = true \n    AND (ar.expires_at IS NULL OR ar.expires_at > now())\n  )\n);"}		elvisiondragon@gmail.com	\N
20250812044541	{"-- Fix infinite recursion in admin_roles policy first\nDROP POLICY IF EXISTS \\"Users can view relevant admin roles\\" ON public.admin_roles;\n\n-- Create a security definer function to check admin roles safely\nCREATE OR REPLACE FUNCTION public.is_super_admin_user()\nRETURNS boolean\nLANGUAGE plpgsql\nSECURITY DEFINER\nSTABLE\nAS $$\nBEGIN\n  RETURN EXISTS (\n    SELECT 1 FROM public.admin_roles \n    WHERE user_id = auth.uid() \n    AND role = 'super_admin' \n    AND is_active = true \n    AND (expires_at IS NULL OR expires_at > now())\n  );\nEND;\n$$;\n\n-- Recreate the admin roles policy without recursion\nCREATE POLICY \\"Users can view relevant admin roles\\" \nON public.admin_roles \nFOR SELECT \nUSING (\n  -- Users can see their own roles\n  auth.uid() = user_id \n  OR \n  -- Super admins can see all roles (using security definer function)\n  public.is_super_admin_user()\n);\n\n-- Enhanced payment data security measures\n-- 1. Create function to mask sensitive payment data\nCREATE OR REPLACE FUNCTION public.mask_sensitive_payment_data(\n  p_bank_account text,\n  p_amount numeric,\n  p_payment_instructions jsonb,\n  p_callback_data jsonb,\n  p_moota_webhook_data jsonb\n) RETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nBEGIN\n  RETURN jsonb_build_object(\n    'bank_account_masked', \n    CASE \n      WHEN p_bank_account IS NOT NULL THEN \n        LEFT(p_bank_account, 4) || '****' || RIGHT(p_bank_account, 4)\n      ELSE NULL \n    END,\n    'amount_masked', \n    CASE \n      WHEN p_amount IS NOT NULL THEN '***.**'\n      ELSE NULL \n    END,\n    'has_payment_instructions', p_payment_instructions IS NOT NULL,\n    'has_callback_data', p_callback_data IS NOT NULL,\n    'has_webhook_data', p_moota_webhook_data IS NOT NULL\n  );\nEND;\n$$;\n\n-- 2. Create secure payment transaction view function\nCREATE OR REPLACE FUNCTION public.get_secure_payment_transaction(p_transaction_id uuid)\nRETURNS TABLE(\n  id uuid,\n  user_id uuid,\n  tripay_reference text,\n  payment_method text,\n  masked_amount text,\n  currency text,\n  status text,\n  created_at timestamptz,\n  updated_at timestamptz,\n  paid_at timestamptz,\n  expires_at timestamptz,\n  security_metadata jsonb\n)\nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nDECLARE\n  transaction_record RECORD;\n  requesting_user_id uuid;\n  is_admin boolean;\nBEGIN\n  requesting_user_id := auth.uid();\n  \n  -- Check if requesting user is verified admin\n  is_admin := public.is_verified_admin(requesting_user_id);\n  \n  -- Get transaction record\n  SELECT * INTO transaction_record \n  FROM public.payment_transactions pt\n  WHERE pt.id = p_transaction_id;\n  \n  -- Check access permissions\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Transaction not found';\n  END IF;\n  \n  IF transaction_record.user_id != requesting_user_id AND NOT is_admin THEN\n    RAISE EXCEPTION 'Access denied: Cannot access transaction for other users';\n  END IF;\n  \n  -- Log access attempt\n  PERFORM public.log_sensitive_action(\n    'secure_payment_access',\n    'payment_transactions',\n    p_transaction_id,\n    jsonb_build_object(\n      'requesting_user', requesting_user_id,\n      'transaction_owner', transaction_record.user_id,\n      'is_admin_access', is_admin,\n      'access_time', now()\n    )\n  );\n  \n  -- Return masked data based on access level\n  RETURN QUERY SELECT\n    transaction_record.id,\n    transaction_record.user_id,\n    transaction_record.tripay_reference,\n    transaction_record.payment_method,\n    CASE \n      WHEN requesting_user_id = transaction_record.user_id OR is_admin THEN \n        transaction_record.amount::text\n      ELSE '***.**'\n    END as masked_amount,\n    transaction_record.currency,\n    transaction_record.status,\n    transaction_record.created_at,\n    transaction_record.updated_at,\n    transaction_record.paid_at,\n    transaction_record.expires_at,\n    public.mask_sensitive_payment_data(\n      transaction_record.bank_account,\n      transaction_record.amount,\n      transaction_record.payment_instructions,\n      transaction_record.callback_data,\n      transaction_record.moota_webhook_data\n    ) as security_metadata;\nEND;\n$$;\n\n-- 3. Enhanced access control function with additional security\nCREATE OR REPLACE FUNCTION public.enhanced_payment_access_control(p_user_id uuid, p_transaction_id uuid)\nRETURNS boolean\nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nDECLARE\n  is_owner boolean := false;\n  is_admin boolean := false;\n  transaction_exists boolean := false;\n  rate_limit_ok boolean := false;\nBEGIN\n  -- Check if transaction exists\n  SELECT EXISTS(\n    SELECT 1 FROM public.payment_transactions \n    WHERE id = p_transaction_id\n  ) INTO transaction_exists;\n  \n  IF NOT transaction_exists THEN\n    PERFORM public.log_sensitive_action(\n      'payment_access_attempt_invalid_transaction',\n      'payment_transactions',\n      p_transaction_id,\n      jsonb_build_object(\n        'requesting_user', p_user_id,\n        'transaction_id', p_transaction_id,\n        'result', 'transaction_not_found'\n      )\n    );\n    RETURN false;\n  END IF;\n  \n  -- Check rate limiting for payment data access\n  rate_limit_ok := public.check_sensitive_data_rate_limit(p_user_id, 'payment_transactions');\n  \n  IF NOT rate_limit_ok THEN\n    PERFORM public.log_sensitive_action(\n      'payment_access_rate_limited',\n      'payment_transactions',\n      p_transaction_id,\n      jsonb_build_object(\n        'requesting_user', p_user_id,\n        'reason', 'rate_limit_exceeded'\n      )\n    );\n    RETURN false;\n  END IF;\n  \n  -- Check ownership\n  SELECT EXISTS(\n    SELECT 1 FROM public.payment_transactions \n    WHERE id = p_transaction_id AND user_id = p_user_id\n  ) INTO is_owner;\n  \n  -- Check verified admin status\n  is_admin := public.is_verified_admin(p_user_id);\n  \n  -- Log access attempt for audit\n  PERFORM public.log_sensitive_action(\n    'payment_access_validation',\n    'payment_transactions',\n    p_transaction_id,\n    jsonb_build_object(\n      'requesting_user', p_user_id,\n      'is_owner', is_owner,\n      'is_admin', is_admin,\n      'access_granted', (is_owner OR is_admin),\n      'rate_limit_passed', rate_limit_ok\n    )\n  );\n  \n  RETURN (is_owner OR is_admin);\nEND;\n$$;\n\n-- 4. Update RLS policies with enhanced security\nDROP POLICY IF EXISTS \\"Secure payment transaction access\\" ON public.payment_transactions;\n\nCREATE POLICY \\"Enhanced secure payment transaction access\\" \nON public.payment_transactions \nFOR SELECT \nUSING (enhanced_payment_access_control(auth.uid(), id));\n\n-- 5. Create function to encrypt sensitive payment fields (placeholder for future enhancement)\nCREATE OR REPLACE FUNCTION public.encrypt_payment_field(p_data text, p_field_type text)\nRETURNS text\nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nBEGIN\n  -- Simple obfuscation for now - in production, use proper encryption\n  -- This can be enhanced with pgcrypto extension for real encryption\n  CASE p_field_type\n    WHEN 'bank_account' THEN\n      RETURN 'ENCRYPTED:' || encode(p_data::bytea, 'base64');\n    WHEN 'unique_code' THEN\n      RETURN 'ENCRYPTED:' || encode(p_data::bytea, 'base64');\n    ELSE\n      RETURN p_data;\n  END CASE;\nEND;\n$$;\n\n-- 6. Add trigger to monitor sensitive payment data changes\nCREATE OR REPLACE FUNCTION public.audit_payment_changes()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nBEGIN\n  -- Log any changes to payment transactions\n  IF TG_OP = 'UPDATE' THEN\n    PERFORM public.log_sensitive_action(\n      'payment_transaction_updated',\n      'payment_transactions',\n      NEW.id,\n      jsonb_build_object(\n        'user_id', NEW.user_id,\n        'old_status', OLD.status,\n        'new_status', NEW.status,\n        'old_amount', OLD.amount,\n        'new_amount', NEW.amount,\n        'updated_by', auth.uid()\n      )\n    );\n  ELSIF TG_OP = 'INSERT' THEN\n    PERFORM public.log_sensitive_action(\n      'payment_transaction_created',\n      'payment_transactions',\n      NEW.id,\n      jsonb_build_object(\n        'user_id', NEW.user_id,\n        'amount', NEW.amount,\n        'payment_method', NEW.payment_method,\n        'created_by', auth.uid()\n      )\n    );\n  END IF;\n  \n  RETURN COALESCE(NEW, OLD);\nEND;\n$$;\n\n-- Create trigger for payment transaction auditing\nDROP TRIGGER IF EXISTS payment_transactions_audit_trigger ON public.payment_transactions;\nCREATE TRIGGER payment_transactions_audit_trigger\n  AFTER INSERT OR UPDATE ON public.payment_transactions\n  FOR EACH ROW EXECUTE FUNCTION public.audit_payment_changes();\n\n-- 7. Create payment data access summary function for monitoring\nCREATE OR REPLACE FUNCTION public.get_payment_access_summary()\nRETURNS TABLE(\n  user_id uuid,\n  access_count bigint,\n  last_access timestamptz,\n  suspicious_activity boolean\n)\nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nBEGIN\n  -- Only verified admins can access this summary\n  IF NOT public.is_verified_admin(auth.uid()) THEN\n    RAISE EXCEPTION 'Access denied: Admin privileges required';\n  END IF;\n  \n  RETURN QUERY\n  SELECT \n    sal.user_id,\n    COUNT(*) as access_count,\n    MAX(sal.created_at) as last_access,\n    -- Flag suspicious activity (more than 20 accesses in 1 hour)\n    COUNT(*) > 20 AND MAX(sal.created_at) > (now() - interval '1 hour') as suspicious_activity\n  FROM public.security_audit_log sal\n  WHERE sal.action LIKE '%payment%'\n    AND sal.created_at > (now() - interval '24 hours')\n  GROUP BY sal.user_id\n  ORDER BY access_count DESC;\nEND;\n$$;"}		elvisiondragon@gmail.com	\N
20250812045802	{"-- Fix function search path warnings by setting explicit search_path\n-- Update all functions to have explicit search_path for security\n\nALTER FUNCTION public.is_super_admin_user() SET search_path TO 'public';\nALTER FUNCTION public.mask_sensitive_payment_data(text, numeric, jsonb, jsonb, jsonb) SET search_path TO 'public';\nALTER FUNCTION public.get_secure_payment_transaction(uuid) SET search_path TO 'public';\nALTER FUNCTION public.enhanced_payment_access_control(uuid, uuid) SET search_path TO 'public';\nALTER FUNCTION public.encrypt_payment_field(text, text) SET search_path TO 'public';\nALTER FUNCTION public.audit_payment_changes() SET search_path TO 'public';\nALTER FUNCTION public.get_payment_access_summary() SET search_path TO 'public';\n\n-- Create a secure client-side function to access payment data safely\nCREATE OR REPLACE FUNCTION public.get_user_payment_transactions(p_limit integer DEFAULT 10)\nRETURNS TABLE(\n  id uuid,\n  tripay_reference text,\n  payment_method text,\n  masked_amount text,\n  currency text,\n  status text,\n  created_at timestamptz,\n  paid_at timestamptz,\n  expires_at timestamptz\n)\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public'\nAS $$\nDECLARE\n  requesting_user_id uuid;\nBEGIN\n  requesting_user_id := auth.uid();\n  \n  -- Must be authenticated\n  IF requesting_user_id IS NULL THEN\n    RAISE EXCEPTION 'Authentication required';\n  END IF;\n  \n  -- Check rate limiting\n  IF NOT public.check_sensitive_data_rate_limit(requesting_user_id, 'payment_transactions') THEN\n    RAISE EXCEPTION 'Rate limit exceeded for payment data access';\n  END IF;\n  \n  -- Log the access\n  PERFORM public.log_sensitive_action(\n    'user_payment_list_access',\n    'payment_transactions',\n    NULL,\n    jsonb_build_object(\n      'requesting_user', requesting_user_id,\n      'limit_requested', p_limit\n    )\n  );\n  \n  -- Return user's own transactions with masked sensitive data\n  RETURN QUERY\n  SELECT \n    pt.id,\n    pt.tripay_reference,\n    pt.payment_method,\n    '***.' || RIGHT(pt.amount::text, 2) as masked_amount, -- Show last 2 digits only\n    pt.currency,\n    pt.status,\n    pt.created_at,\n    pt.paid_at,\n    pt.expires_at\n  FROM public.payment_transactions pt\n  WHERE pt.user_id = requesting_user_id\n  ORDER BY pt.created_at DESC\n  LIMIT COALESCE(p_limit, 10);\nEND;\n$$;\n\n-- Create function to validate payment transaction access with enhanced logging\nCREATE OR REPLACE FUNCTION public.validate_payment_transaction_access(\n  p_transaction_id uuid,\n  p_access_type text DEFAULT 'read'\n)\nRETURNS boolean\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public'\nAS $$\nDECLARE\n  requesting_user_id uuid;\n  transaction_owner uuid;\n  is_admin boolean;\n  access_granted boolean;\nBEGIN\n  requesting_user_id := auth.uid();\n  \n  -- Check authentication\n  IF requesting_user_id IS NULL THEN\n    RETURN false;\n  END IF;\n  \n  -- Get transaction owner\n  SELECT user_id INTO transaction_owner\n  FROM public.payment_transactions\n  WHERE id = p_transaction_id;\n  \n  -- Transaction must exist\n  IF transaction_owner IS NULL THEN\n    PERFORM public.log_sensitive_action(\n      'payment_access_invalid_transaction',\n      'payment_transactions',\n      p_transaction_id,\n      jsonb_build_object(\n        'requesting_user', requesting_user_id,\n        'access_type', p_access_type,\n        'result', 'transaction_not_found'\n      )\n    );\n    RETURN false;\n  END IF;\n  \n  -- Check if user is verified admin\n  is_admin := public.is_verified_admin(requesting_user_id);\n  \n  -- Determine access\n  access_granted := (requesting_user_id = transaction_owner) OR is_admin;\n  \n  -- Log access attempt\n  PERFORM public.log_sensitive_action(\n    'payment_transaction_access_validation',\n    'payment_transactions',\n    p_transaction_id,\n    jsonb_build_object(\n      'requesting_user', requesting_user_id,\n      'transaction_owner', transaction_owner,\n      'is_admin', is_admin,\n      'access_type', p_access_type,\n      'access_granted', access_granted\n    )\n  );\n  \n  RETURN access_granted;\nEND;\n$$;"}		elvisiondragon@gmail.com	\N
20250812050216	{"-- Enhanced Admin Role Security Fixes\n-- Fix comprehensive RLS policies for admin_roles table\n\n-- Drop existing policies to recreate with better security\nDROP POLICY IF EXISTS \\"Only super admins can manage admin roles\\" ON public.admin_roles;\nDROP POLICY IF EXISTS \\"Users can view relevant admin roles\\" ON public.admin_roles;\n\n-- Create comprehensive admin role management policies\nCREATE POLICY \\"Super admins can manage all admin roles\\" \nON public.admin_roles \nFOR ALL \nTO authenticated\nUSING (\n  EXISTS (\n    SELECT 1 FROM public.admin_roles ar \n    WHERE ar.user_id = auth.uid() \n    AND ar.role = 'super_admin' \n    AND ar.is_active = true \n    AND (ar.expires_at IS NULL OR ar.expires_at > now())\n  )\n)\nWITH CHECK (\n  EXISTS (\n    SELECT 1 FROM public.admin_roles ar \n    WHERE ar.user_id = auth.uid() \n    AND ar.role = 'super_admin' \n    AND ar.is_active = true \n    AND (ar.expires_at IS NULL OR ar.expires_at > now())\n  )\n);\n\n-- Restrict admin role viewing to super admins only (security hardening)\nCREATE POLICY \\"Only super admins can view admin roles\\" \nON public.admin_roles \nFOR SELECT \nTO authenticated\nUSING (\n  EXISTS (\n    SELECT 1 FROM public.admin_roles ar \n    WHERE ar.user_id = auth.uid() \n    AND ar.role = 'super_admin' \n    AND ar.is_active = true \n    AND (ar.expires_at IS NULL OR ar.expires_at > now())\n  )\n);\n\n-- Prevent privilege escalation - only super admins can grant super admin role\nCREATE POLICY \\"Prevent unauthorized super admin creation\\" \nON public.admin_roles \nFOR INSERT \nTO authenticated\nWITH CHECK (\n  -- If granting super_admin role, must be super_admin\n  (role != 'super_admin' OR EXISTS (\n    SELECT 1 FROM public.admin_roles ar \n    WHERE ar.user_id = auth.uid() \n    AND ar.role = 'super_admin' \n    AND ar.is_active = true \n    AND (ar.expires_at IS NULL OR ar.expires_at > now())\n  ))\n);\n\n-- Additional audit logging for admin role changes\nCREATE OR REPLACE FUNCTION public.enhanced_admin_role_audit()\nRETURNS TRIGGER AS $$\nBEGIN\n  -- Log all admin role operations with enhanced detail\n  IF TG_OP = 'INSERT' THEN\n    PERFORM public.log_sensitive_action(\n      'admin_role_created',\n      'admin_roles',\n      NEW.id,\n      jsonb_build_object(\n        'target_user', NEW.user_id,\n        'role_granted', NEW.role,\n        'granted_by', auth.uid(),\n        'expires_at', NEW.expires_at,\n        'operation_timestamp', now()\n      )\n    );\n  ELSIF TG_OP = 'UPDATE' THEN\n    PERFORM public.log_sensitive_action(\n      'admin_role_updated',\n      'admin_roles',\n      NEW.id,\n      jsonb_build_object(\n        'target_user', NEW.user_id,\n        'old_role', OLD.role,\n        'new_role', NEW.role,\n        'old_active', OLD.is_active,\n        'new_active', NEW.is_active,\n        'updated_by', auth.uid(),\n        'operation_timestamp', now()\n      )\n    );\n  ELSIF TG_OP = 'DELETE' THEN\n    PERFORM public.log_sensitive_action(\n      'admin_role_deleted',\n      'admin_roles',\n      OLD.id,\n      jsonb_build_object(\n        'target_user', OLD.user_id,\n        'deleted_role', OLD.role,\n        'deleted_by', auth.uid(),\n        'operation_timestamp', now()\n      )\n    );\n  END IF;\n  \n  RETURN COALESCE(NEW, OLD);\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER;\n\n-- Create trigger for enhanced admin role auditing\nDROP TRIGGER IF EXISTS enhanced_admin_role_audit_trigger ON public.admin_roles;\nCREATE TRIGGER enhanced_admin_role_audit_trigger\n  AFTER INSERT OR UPDATE OR DELETE ON public.admin_roles\n  FOR EACH ROW EXECUTE FUNCTION public.enhanced_admin_role_audit();\n\n-- Add additional security function for role validation\nCREATE OR REPLACE FUNCTION public.validate_admin_role_operation(\n  p_target_user_id uuid,\n  p_role text,\n  p_operation text\n)\nRETURNS boolean\nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nDECLARE\n  requesting_user_id uuid;\n  is_super_admin boolean;\nBEGIN\n  requesting_user_id := auth.uid();\n  \n  -- Check if requesting user is super admin\n  is_super_admin := EXISTS (\n    SELECT 1 FROM public.admin_roles \n    WHERE user_id = requesting_user_id \n    AND role = 'super_admin' \n    AND is_active = true \n    AND (expires_at IS NULL OR expires_at > now())\n  );\n  \n  -- Log the validation attempt\n  PERFORM public.log_sensitive_action(\n    'admin_role_validation',\n    'admin_roles',\n    p_target_user_id,\n    jsonb_build_object(\n      'requesting_user', requesting_user_id,\n      'target_user', p_target_user_id,\n      'requested_role', p_role,\n      'operation', p_operation,\n      'is_super_admin', is_super_admin,\n      'validation_result', is_super_admin\n    )\n  );\n  \n  RETURN is_super_admin;\nEND;\n$$;"}		elvisiondragon@gmail.com	\N
20250812050246	{"-- Fix function search path security warnings\n-- Update functions to include SET search_path directive\n\nCREATE OR REPLACE FUNCTION public.enhanced_admin_role_audit()\nRETURNS TRIGGER AS $$\nBEGIN\n  -- Log all admin role operations with enhanced detail\n  IF TG_OP = 'INSERT' THEN\n    PERFORM public.log_sensitive_action(\n      'admin_role_created',\n      'admin_roles',\n      NEW.id,\n      jsonb_build_object(\n        'target_user', NEW.user_id,\n        'role_granted', NEW.role,\n        'granted_by', auth.uid(),\n        'expires_at', NEW.expires_at,\n        'operation_timestamp', now()\n      )\n    );\n  ELSIF TG_OP = 'UPDATE' THEN\n    PERFORM public.log_sensitive_action(\n      'admin_role_updated',\n      'admin_roles',\n      NEW.id,\n      jsonb_build_object(\n        'target_user', NEW.user_id,\n        'old_role', OLD.role,\n        'new_role', NEW.role,\n        'old_active', OLD.is_active,\n        'new_active', NEW.is_active,\n        'updated_by', auth.uid(),\n        'operation_timestamp', now()\n      )\n    );\n  ELSIF TG_OP = 'DELETE' THEN\n    PERFORM public.log_sensitive_action(\n      'admin_role_deleted',\n      'admin_roles',\n      OLD.id,\n      jsonb_build_object(\n        'target_user', OLD.user_id,\n        'deleted_role', OLD.role,\n        'deleted_by', auth.uid(),\n        'operation_timestamp', now()\n      )\n    );\n  END IF;\n  \n  RETURN COALESCE(NEW, OLD);\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = 'public';\n\nCREATE OR REPLACE FUNCTION public.validate_admin_role_operation(\n  p_target_user_id uuid,\n  p_role text,\n  p_operation text\n)\nRETURNS boolean\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $$\nDECLARE\n  requesting_user_id uuid;\n  is_super_admin boolean;\nBEGIN\n  requesting_user_id := auth.uid();\n  \n  -- Check if requesting user is super admin\n  is_super_admin := EXISTS (\n    SELECT 1 FROM public.admin_roles \n    WHERE user_id = requesting_user_id \n    AND role = 'super_admin' \n    AND is_active = true \n    AND (expires_at IS NULL OR expires_at > now())\n  );\n  \n  -- Log the validation attempt\n  PERFORM public.log_sensitive_action(\n    'admin_role_validation',\n    'admin_roles',\n    p_target_user_id,\n    jsonb_build_object(\n      'requesting_user', requesting_user_id,\n      'target_user', p_target_user_id,\n      'requested_role', p_role,\n      'operation', p_operation,\n      'is_super_admin', is_super_admin,\n      'validation_result', is_super_admin\n    )\n  );\n  \n  RETURN is_super_admin;\nEND;\n$$;"}		elvisiondragon@gmail.com	\N
20250812050304	{"-- Fix function search path security warnings\n-- Update functions to include SET search_path directive\n\nCREATE OR REPLACE FUNCTION public.enhanced_admin_role_audit()\nRETURNS TRIGGER AS $$\nBEGIN\n  -- Log all admin role operations with enhanced detail\n  IF TG_OP = 'INSERT' THEN\n    PERFORM public.log_sensitive_action(\n      'admin_role_created',\n      'admin_roles',\n      NEW.id,\n      jsonb_build_object(\n        'target_user', NEW.user_id,\n        'role_granted', NEW.role,\n        'granted_by', auth.uid(),\n        'expires_at', NEW.expires_at,\n        'operation_timestamp', now()\n      )\n    );\n  ELSIF TG_OP = 'UPDATE' THEN\n    PERFORM public.log_sensitive_action(\n      'admin_role_updated',\n      'admin_roles',\n      NEW.id,\n      jsonb_build_object(\n        'target_user', NEW.user_id,\n        'old_role', OLD.role,\n        'new_role', NEW.role,\n        'old_active', OLD.is_active,\n        'new_active', NEW.is_active,\n        'updated_by', auth.uid(),\n        'operation_timestamp', now()\n      )\n    );\n  ELSIF TG_OP = 'DELETE' THEN\n    PERFORM public.log_sensitive_action(\n      'admin_role_deleted',\n      'admin_roles',\n      OLD.id,\n      jsonb_build_object(\n        'target_user', OLD.user_id,\n        'deleted_role', OLD.role,\n        'deleted_by', auth.uid(),\n        'operation_timestamp', now()\n      )\n    );\n  END IF;\n  \n  RETURN COALESCE(NEW, OLD);\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = 'public';\n\nCREATE OR REPLACE FUNCTION public.validate_admin_role_operation(\n  p_target_user_id uuid,\n  p_role text,\n  p_operation text\n)\nRETURNS boolean\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $$\nDECLARE\n  requesting_user_id uuid;\n  is_super_admin boolean;\nBEGIN\n  requesting_user_id := auth.uid();\n  \n  -- Check if requesting user is super admin\n  is_super_admin := EXISTS (\n    SELECT 1 FROM public.admin_roles \n    WHERE user_id = requesting_user_id \n    AND role = 'super_admin' \n    AND is_active = true \n    AND (expires_at IS NULL OR expires_at > now())\n  );\n  \n  -- Log the validation attempt\n  PERFORM public.log_sensitive_action(\n    'admin_role_validation',\n    'admin_roles',\n    p_target_user_id,\n    jsonb_build_object(\n      'requesting_user', requesting_user_id,\n      'target_user', p_target_user_id,\n      'requested_role', p_role,\n      'operation', p_operation,\n      'is_super_admin', is_super_admin,\n      'validation_result', is_super_admin\n    )\n  );\n  \n  RETURN is_super_admin;\nEND;\n$$;"}		elvisiondragon@gmail.com	\N
20250812050528	{"-- Advanced Admin System Security Hardening\n-- Multi-layered protection against admin system compromise\n\n-- 1. Create admin activity monitoring table\nCREATE TABLE IF NOT EXISTS public.admin_activity_log (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL,\n  action text NOT NULL,\n  target_user_id uuid,\n  target_resource text,\n  resource_id uuid,\n  metadata jsonb DEFAULT '{}',\n  ip_address text,\n  user_agent text,\n  risk_score integer DEFAULT 0,\n  requires_approval boolean DEFAULT false,\n  approved_by uuid,\n  approved_at timestamptz,\n  created_at timestamptz DEFAULT now()\n);\n\n-- Enable RLS on admin activity log\nALTER TABLE public.admin_activity_log ENABLE ROW LEVEL SECURITY;\n\n-- Only super admins can view admin activity logs\nCREATE POLICY \\"Super admins can view admin activity logs\\"\nON public.admin_activity_log\nFOR SELECT\nTO authenticated\nUSING (\n  EXISTS (\n    SELECT 1 FROM public.admin_roles ar\n    WHERE ar.user_id = auth.uid()\n    AND ar.role = 'super_admin'\n    AND ar.is_active = true\n    AND (ar.expires_at IS NULL OR ar.expires_at > now())\n  )\n);\n\n-- System can insert admin activity logs\nCREATE POLICY \\"System can insert admin activity logs\\"\nON public.admin_activity_log\nFOR INSERT\nTO authenticated\nWITH CHECK (true);\n\n-- 2. Create fail-safe admin verification function\nCREATE OR REPLACE FUNCTION public.verify_admin_with_failsafe(\n  p_user_id uuid,\n  p_required_role text DEFAULT 'admin'\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $$\nDECLARE\n  admin_record RECORD;\n  verification_result jsonb;\n  current_time timestamptz := now();\nBEGIN\n  -- Initialize result\n  verification_result := jsonb_build_object(\n    'is_admin', false,\n    'role', null,\n    'expires_at', null,\n    'verification_time', current_time,\n    'security_checks', jsonb_build_array()\n  );\n  \n  -- Security check 1: User must be authenticated\n  IF p_user_id IS NULL THEN\n    verification_result := verification_result || jsonb_build_object(\n      'security_checks', verification_result->'security_checks' || \n      jsonb_build_object('check', 'authentication', 'passed', false, 'reason', 'user_not_authenticated')\n    );\n    RETURN verification_result;\n  END IF;\n  \n  -- Security check 2: Fetch admin role with comprehensive validation\n  SELECT * INTO admin_record\n  FROM public.admin_roles\n  WHERE user_id = p_user_id\n  AND is_active = true\n  AND (expires_at IS NULL OR expires_at > current_time);\n  \n  -- Security check 3: Role exists and is valid\n  IF NOT FOUND THEN\n    verification_result := verification_result || jsonb_build_object(\n      'security_checks', verification_result->'security_checks' || \n      jsonb_build_object('check', 'role_exists', 'passed', false, 'reason', 'no_active_admin_role')\n    );\n    RETURN verification_result;\n  END IF;\n  \n  -- Security check 4: Role hierarchy validation\n  IF p_required_role = 'super_admin' AND admin_record.role != 'super_admin' THEN\n    verification_result := verification_result || jsonb_build_object(\n      'security_checks', verification_result->'security_checks' || \n      jsonb_build_object('check', 'role_hierarchy', 'passed', false, 'reason', 'insufficient_privileges')\n    );\n    RETURN verification_result;\n  END IF;\n  \n  -- Security check 5: Rate limiting for admin operations\n  IF NOT public.check_sensitive_data_rate_limit(p_user_id, 'admin_operations') THEN\n    verification_result := verification_result || jsonb_build_object(\n      'security_checks', verification_result->'security_checks' || \n      jsonb_build_object('check', 'rate_limit', 'passed', false, 'reason', 'rate_limit_exceeded')\n    );\n    RETURN verification_result;\n  END IF;\n  \n  -- All checks passed\n  verification_result := jsonb_build_object(\n    'is_admin', true,\n    'role', admin_record.role,\n    'expires_at', admin_record.expires_at,\n    'verification_time', current_time,\n    'security_checks', jsonb_build_array(\n      jsonb_build_object('check', 'authentication', 'passed', true),\n      jsonb_build_object('check', 'role_exists', 'passed', true),\n      jsonb_build_object('check', 'role_hierarchy', 'passed', true),\n      jsonb_build_object('check', 'rate_limit', 'passed', true)\n    )\n  );\n  \n  -- Log successful verification\n  PERFORM public.log_sensitive_action(\n    'admin_verification_success',\n    'admin_roles',\n    admin_record.id,\n    verification_result\n  );\n  \n  RETURN verification_result;\nEND;\n$$;\n\n-- 3. Enhanced admin role assignment with approval workflow\nCREATE OR REPLACE FUNCTION public.secure_admin_role_grant(\n  p_target_user_id uuid,\n  p_role text,\n  p_expires_at timestamptz DEFAULT NULL,\n  p_justification text DEFAULT NULL\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $$\nDECLARE\n  granting_user_id uuid;\n  verification_result jsonb;\n  requires_approval boolean := false;\n  result jsonb;\nBEGIN\n  granting_user_id := auth.uid();\n  \n  -- Verify granting user is super admin\n  verification_result := public.verify_admin_with_failsafe(granting_user_id, 'super_admin');\n  \n  IF NOT (verification_result->>'is_admin')::boolean THEN\n    -- Log failed attempt\n    PERFORM public.log_sensitive_action(\n      'admin_role_grant_denied',\n      'admin_roles',\n      p_target_user_id,\n      jsonb_build_object(\n        'target_user', p_target_user_id,\n        'requested_role', p_role,\n        'denied_reason', 'insufficient_privileges',\n        'verification_result', verification_result\n      )\n    );\n    \n    RETURN jsonb_build_object(\n      'success', false,\n      'error', 'Access denied: Super admin privileges required',\n      'verification_result', verification_result\n    );\n  END IF;\n  \n  -- Determine if approval is needed (super_admin grants always require approval)\n  requires_approval := (p_role = 'super_admin');\n  \n  -- Log the grant attempt with high detail\n  INSERT INTO public.admin_activity_log (\n    user_id,\n    action,\n    target_user_id,\n    metadata,\n    requires_approval\n  ) VALUES (\n    granting_user_id,\n    'admin_role_grant_attempt',\n    p_target_user_id,\n    jsonb_build_object(\n      'requested_role', p_role,\n      'expires_at', p_expires_at,\n      'justification', p_justification,\n      'requires_approval', requires_approval,\n      'verification_result', verification_result\n    ),\n    requires_approval\n  );\n  \n  -- If approval not required, grant immediately\n  IF NOT requires_approval THEN\n    INSERT INTO public.admin_roles (user_id, role, granted_by, expires_at)\n    VALUES (p_target_user_id, p_role, granting_user_id, p_expires_at)\n    ON CONFLICT (user_id) DO UPDATE SET\n      role = EXCLUDED.role,\n      granted_by = EXCLUDED.granted_by,\n      granted_at = now(),\n      expires_at = EXCLUDED.expires_at,\n      is_active = true;\n    \n    result := jsonb_build_object(\n      'success', true,\n      'message', 'Admin role granted successfully',\n      'role_granted', p_role,\n      'requires_approval', false\n    );\n  ELSE\n    result := jsonb_build_object(\n      'success', true,\n      'message', 'Admin role grant submitted for approval',\n      'role_requested', p_role,\n      'requires_approval', true\n    );\n  END IF;\n  \n  -- Enhanced logging\n  PERFORM public.log_sensitive_action(\n    'admin_role_grant_processed',\n    'admin_roles',\n    p_target_user_id,\n    result || jsonb_build_object('verification_result', verification_result)\n  );\n  \n  RETURN result;\nEND;\n$$;\n\n-- 4. Admin role emergency revocation function\nCREATE OR REPLACE FUNCTION public.emergency_revoke_admin_role(\n  p_target_user_id uuid,\n  p_reason text\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $$\nDECLARE\n  revoking_user_id uuid;\n  verification_result jsonb;\n  revoked_role text;\nBEGIN\n  revoking_user_id := auth.uid();\n  \n  -- Verify revoking user is super admin\n  verification_result := public.verify_admin_with_failsafe(revoking_user_id, 'super_admin');\n  \n  IF NOT (verification_result->>'is_admin')::boolean THEN\n    RETURN jsonb_build_object(\n      'success', false,\n      'error', 'Access denied: Super admin privileges required'\n    );\n  END IF;\n  \n  -- Get current role before revocation\n  SELECT role INTO revoked_role \n  FROM public.admin_roles \n  WHERE user_id = p_target_user_id AND is_active = true;\n  \n  -- Revoke the role\n  UPDATE public.admin_roles \n  SET is_active = false, updated_at = now()\n  WHERE user_id = p_target_user_id;\n  \n  -- Log emergency revocation\n  PERFORM public.log_sensitive_action(\n    'admin_role_emergency_revocation',\n    'admin_roles',\n    p_target_user_id,\n    jsonb_build_object(\n      'target_user', p_target_user_id,\n      'revoked_role', revoked_role,\n      'revoked_by', revoking_user_id,\n      'reason', p_reason,\n      'emergency_action', true\n    )\n  );\n  \n  RETURN jsonb_build_object(\n    'success', true,\n    'message', 'Admin role emergency revocation completed',\n    'revoked_role', revoked_role\n  );\nEND;\n$$;\n\n-- 5. Admin system health check function\nCREATE OR REPLACE FUNCTION public.admin_system_health_check()\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $$\nDECLARE\n  health_report jsonb;\n  super_admin_count integer;\n  expired_roles_count integer;\n  suspicious_activity_count integer;\nBEGIN\n  -- Count active super admins\n  SELECT COUNT(*) INTO super_admin_count\n  FROM public.admin_roles\n  WHERE role = 'super_admin' \n  AND is_active = true \n  AND (expires_at IS NULL OR expires_at > now());\n  \n  -- Count expired but still active roles\n  SELECT COUNT(*) INTO expired_roles_count\n  FROM public.admin_roles\n  WHERE is_active = true \n  AND expires_at IS NOT NULL \n  AND expires_at <= now();\n  \n  -- Count suspicious admin activity in last 24 hours\n  SELECT COUNT(*) INTO suspicious_activity_count\n  FROM public.security_audit_log\n  WHERE action LIKE '%admin%'\n  AND created_at > (now() - interval '24 hours')\n  AND metadata->>'suspicious_activity' = 'true';\n  \n  health_report := jsonb_build_object(\n    'timestamp', now(),\n    'super_admin_count', super_admin_count,\n    'expired_roles_count', expired_roles_count,\n    'suspicious_activity_count', suspicious_activity_count,\n    'status', CASE \n      WHEN super_admin_count = 0 THEN 'CRITICAL'\n      WHEN expired_roles_count > 0 THEN 'WARNING'\n      WHEN suspicious_activity_count > 5 THEN 'WARNING'\n      ELSE 'HEALTHY'\n    END,\n    'recommendations', CASE\n      WHEN super_admin_count = 0 THEN jsonb_build_array('No active super admins - system locked')\n      WHEN expired_roles_count > 0 THEN jsonb_build_array('Clean up expired admin roles')\n      WHEN suspicious_activity_count > 5 THEN jsonb_build_array('Review suspicious admin activity')\n      ELSE jsonb_build_array('System operating normally')\n    END\n  );\n  \n  -- Log health check\n  PERFORM public.log_sensitive_action(\n    'admin_system_health_check',\n    'admin_roles',\n    NULL,\n    health_report\n  );\n  \n  RETURN health_report;\nEND;\n$$;\n\n-- 6. Update existing admin role policies to use the enhanced verification\nDROP POLICY IF EXISTS \\"Super admins can manage all admin roles\\" ON public.admin_roles;\nDROP POLICY IF EXISTS \\"Only super admins can view admin roles\\" ON public.admin_roles;\nDROP POLICY IF EXISTS \\"Prevent unauthorized super admin creation\\" ON public.admin_roles;\n\n-- New fail-safe policies using the enhanced verification function\nCREATE POLICY \\"Enhanced super admin management\\"\nON public.admin_roles\nFOR ALL\nTO authenticated\nUSING (\n  (public.verify_admin_with_failsafe(auth.uid(), 'super_admin')->>'is_admin')::boolean\n)\nWITH CHECK (\n  (public.verify_admin_with_failsafe(auth.uid(), 'super_admin')->>'is_admin')::boolean\n);\n\n-- 7. Create automated cleanup function for expired roles\nCREATE OR REPLACE FUNCTION public.cleanup_expired_admin_roles()\nRETURNS integer\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $$\nDECLARE\n  cleanup_count integer;\nBEGIN\n  -- Deactivate expired roles\n  UPDATE public.admin_roles \n  SET is_active = false, updated_at = now()\n  WHERE is_active = true \n  AND expires_at IS NOT NULL \n  AND expires_at <= now();\n  \n  GET DIAGNOSTICS cleanup_count = ROW_COUNT;\n  \n  -- Log cleanup action\n  PERFORM public.log_sensitive_action(\n    'admin_roles_automated_cleanup',\n    'admin_roles',\n    NULL,\n    jsonb_build_object(\n      'cleaned_up_count', cleanup_count,\n      'cleanup_time', now()\n    )\n  );\n  \n  RETURN cleanup_count;\nEND;\n$$;"}		elvisiondragon@gmail.com	\N
20250814060232	{"-- Add DELETE policy for chat messages so users can delete their own messages\nCREATE POLICY \\"Users can delete their own chat messages\\" \nON public.chat_messages \nFOR DELETE \nUSING (auth.uid() = user_id);"}		elvisiondragon@gmail.com	\N
20250814084708	{"-- Phase 1: Critical Payment Security Fixes\n\n-- Drop the existing complex payment transaction policy that may be too permissive\nDROP POLICY IF EXISTS \\"Enhanced secure payment transaction access\\" ON public.payment_transactions;\n\n-- Create a much stricter, owner-only access policy for payment transactions\nCREATE POLICY \\"Strict owner-only payment access\\" \nON public.payment_transactions \nFOR SELECT \nUSING (\n  auth.uid() = user_id \n  AND check_sensitive_data_rate_limit(auth.uid(), 'payment_transactions')\n);\n\n-- Create a simple admin policy that's separate and more restrictive\nCREATE POLICY \\"Admin payment access with strict validation\\"\nON public.payment_transactions\nFOR SELECT\nUSING (\n  is_verified_admin(auth.uid()) \n  AND check_sensitive_data_rate_limit(auth.uid(), 'payment_transactions')\n);\n\n-- Ensure only owners can insert their own transactions\nDROP POLICY IF EXISTS \\"Users can insert their own transactions\\" ON public.payment_transactions;\nCREATE POLICY \\"Strict owner transaction insert\\"\nON public.payment_transactions\nFOR INSERT\nWITH CHECK (\n  auth.uid() = user_id\n  AND check_sensitive_data_rate_limit(auth.uid(), 'payment_transactions')\n);\n\n-- Add a function to safely retrieve payment data with masking\nCREATE OR REPLACE FUNCTION public.get_masked_payment_transaction(p_transaction_id uuid)\nRETURNS TABLE(\n  id uuid,\n  tripay_reference text,\n  payment_method text,\n  masked_amount text,\n  currency text,\n  status text,\n  created_at timestamp with time zone,\n  paid_at timestamp with time zone,\n  expires_at timestamp with time zone\n)\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $$\nDECLARE\n  transaction_record RECORD;\n  requesting_user_id uuid;\nBEGIN\n  requesting_user_id := auth.uid();\n  \n  -- Check if user is authenticated\n  IF requesting_user_id IS NULL THEN\n    RAISE EXCEPTION 'Authentication required';\n  END IF;\n  \n  -- Check rate limiting\n  IF NOT check_sensitive_data_rate_limit(requesting_user_id, 'payment_transactions') THEN\n    RAISE EXCEPTION 'Rate limit exceeded';\n  END IF;\n  \n  -- Get transaction and verify ownership\n  SELECT * INTO transaction_record\n  FROM public.payment_transactions pt\n  WHERE pt.id = p_transaction_id AND pt.user_id = requesting_user_id;\n  \n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Transaction not found or access denied';\n  END IF;\n  \n  -- Log access\n  PERFORM log_sensitive_action(\n    'masked_payment_access',\n    'payment_transactions',\n    p_transaction_id,\n    jsonb_build_object('user_id', requesting_user_id)\n  );\n  \n  -- Return masked data\n  RETURN QUERY SELECT\n    transaction_record.id,\n    transaction_record.tripay_reference,\n    transaction_record.payment_method,\n    -- Mask the amount for additional security\n    '***.' || RIGHT(transaction_record.amount::text, 2) as masked_amount,\n    transaction_record.currency,\n    transaction_record.status,\n    transaction_record.created_at,\n    transaction_record.paid_at,\n    transaction_record.expires_at;\nEND;\n$$;\n\n-- Phase 2: Email Encryption Setup\n-- Add encryption function for sensitive email data\nCREATE OR REPLACE FUNCTION public.encrypt_email(p_email text)\nRETURNS text\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $$\nBEGIN\n  -- Simple obfuscation for now - can be enhanced with pgcrypto\n  RETURN 'ENC:' || encode(p_email::bytea, 'base64');\nEND;\n$$;\n\n-- Add function to decrypt email data\nCREATE OR REPLACE FUNCTION public.decrypt_email(p_encrypted_email text)\nRETURNS text\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $$\nBEGIN\n  -- Check if already encrypted\n  IF p_encrypted_email LIKE 'ENC:%' THEN\n    RETURN decode(substring(p_encrypted_email from 5), 'base64')::text;\n  ELSE\n    -- Return as-is if not encrypted (for backward compatibility)\n    RETURN p_encrypted_email;\n  END IF;\nEND;\n$$;\n\n-- Add safer email access function\nCREATE OR REPLACE FUNCTION public.get_user_email_safe(p_user_id uuid)\nRETURNS text\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $$\nDECLARE\n  encrypted_email text;\nBEGIN\n  -- Only allow users to get their own email\n  IF auth.uid() != p_user_id THEN\n    RAISE EXCEPTION 'Access denied: Cannot retrieve email for other users';\n  END IF;\n  \n  -- Check rate limiting\n  IF NOT check_sensitive_data_rate_limit(auth.uid(), 'user_contact_info') THEN\n    RAISE EXCEPTION 'Rate limit exceeded';\n  END IF;\n  \n  -- Log access\n  PERFORM log_sensitive_action(\n    'safe_email_access',\n    'user_contact_info',\n    p_user_id,\n    jsonb_build_object('requesting_user', auth.uid())\n  );\n  \n  SELECT email_encrypted INTO encrypted_email\n  FROM public.user_contact_info\n  WHERE user_id = p_user_id;\n  \n  RETURN decrypt_email(encrypted_email);\nEND;\n$$;"}		elvisiondragon@gmail.com	\N
20250815023803	{"-- Security fix: Ensure admin_roles table has proper RLS policies for SELECT operations\n-- This addresses the security finding about admin role assignments being viewable by anyone\n\n-- Drop the existing overly broad \\"ALL\\" policy and create specific policies for better security\nDROP POLICY IF EXISTS \\"Enhanced super admin management\\" ON public.admin_roles;\n\n-- Create separate policies for different operations with stricter controls\n-- Policy for SELECT: Only verified super admins can view admin role assignments\nCREATE POLICY \\"Super admins can view admin roles\\"\nON public.admin_roles\nFOR SELECT\nTO authenticated\nUSING (\n  -- Use the security definer function to prevent recursion\n  (verify_admin_with_failsafe(auth.uid(), 'super_admin'::text) ->> 'is_admin'::text)::boolean\n);\n\n-- Policy for INSERT: Only verified super admins can create admin roles\nCREATE POLICY \\"Super admins can create admin roles\\"\nON public.admin_roles\nFOR INSERT\nTO authenticated\nWITH CHECK (\n  (verify_admin_with_failsafe(auth.uid(), 'super_admin'::text) ->> 'is_admin'::text)::boolean\n);\n\n-- Policy for UPDATE: Only verified super admins can update admin roles\nCREATE POLICY \\"Super admins can update admin roles\\"\nON public.admin_roles\nFOR UPDATE\nTO authenticated\nUSING (\n  (verify_admin_with_failsafe(auth.uid(), 'super_admin'::text) ->> 'is_admin'::text)::boolean\n)\nWITH CHECK (\n  (verify_admin_with_failsafe(auth.uid(), 'super_admin'::text) ->> 'is_admin'::text)::boolean\n);\n\n-- Policy for DELETE: Only verified super admins can delete admin roles\nCREATE POLICY \\"Super admins can delete admin roles\\"\nON public.admin_roles\nFOR DELETE\nTO authenticated\nUSING (\n  (verify_admin_with_failsafe(auth.uid(), 'super_admin'::text) ->> 'is_admin'::text)::boolean\n);\n\n-- Enhanced logging function for admin role access monitoring\nCREATE OR REPLACE FUNCTION public.enhanced_admin_role_access_log()\nRETURNS TRIGGER AS $$\nBEGIN\n  -- Log admin role table access for security monitoring\n  PERFORM public.log_sensitive_action(\n    'admin_roles_data_access',\n    'admin_roles',\n    COALESCE(NEW.id, OLD.id),\n    jsonb_build_object(\n      'operation', TG_OP,\n      'requesting_user', auth.uid(),\n      'target_user', COALESCE(NEW.user_id, OLD.user_id),\n      'role', COALESCE(NEW.role, OLD.role),\n      'timestamp', now()\n    )\n  );\n  \n  RETURN COALESCE(NEW, OLD);\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER;\n\n-- Create trigger for monitoring all operations on admin_roles\nDROP TRIGGER IF EXISTS enhanced_admin_role_access_monitor ON public.admin_roles;\nCREATE TRIGGER enhanced_admin_role_access_monitor\n  AFTER INSERT OR UPDATE OR DELETE ON public.admin_roles\n  FOR EACH ROW\n  EXECUTE FUNCTION public.enhanced_admin_role_access_log();"}		elvisiondragon@gmail.com	\N
20250816011220	{"-- Function to clean up existing user display names by removing email domains\nCREATE OR REPLACE FUNCTION public.cleanup_user_display_names()\nRETURNS INTEGER\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $$\nDECLARE\n  updated_count INTEGER;\nBEGIN\n  -- Update all profiles where display_name contains @ symbol\n  UPDATE public.profiles \n  SET display_name = CASE \n    WHEN display_name LIKE '%@%' THEN split_part(display_name, '@', 1)\n    ELSE display_name\n  END,\n  updated_at = now()\n  WHERE display_name LIKE '%@%';\n  \n  GET DIAGNOSTICS updated_count = ROW_COUNT;\n  \n  -- Log the cleanup action\n  PERFORM public.log_sensitive_action(\n    'user_display_names_cleanup',\n    'profiles',\n    NULL,\n    jsonb_build_object(\n      'updated_count', updated_count,\n      'cleanup_time', now()\n    )\n  );\n  \n  RETURN updated_count;\nEND;\n$$;\n\n-- Execute the cleanup function to fix existing users\nSELECT public.cleanup_user_display_names();\n\n-- Update the existing handle_new_user function to ensure it always extracts username from email\nCREATE OR REPLACE FUNCTION public.handle_new_user()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $$\nDECLARE\n  username TEXT;\nBEGIN\n  -- Extract username from email (part before @)\n  username := CASE \n    WHEN NEW.email LIKE '%@%' THEN split_part(NEW.email, '@', 1)\n    ELSE COALESCE(NEW.raw_user_meta_data->>'display_name', NEW.email, 'Anonymous')\n  END;\n  \n  INSERT INTO public.profiles (user_id, display_name)\n  VALUES (\n    NEW.id, \n    username\n  );\n  \n  RETURN NEW;\nEND;\n$$;"}		elvisiondragon@gmail.com	\N
20250816011645	{"-- Function to clean up chat message user names by removing email domains\nCREATE OR REPLACE FUNCTION public.cleanup_chat_message_user_names()\nRETURNS INTEGER\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $$\nDECLARE\n  updated_count INTEGER;\nBEGIN\n  -- Update all chat messages where user_name contains @ symbol\n  UPDATE public.chat_messages \n  SET user_name = CASE \n    WHEN user_name LIKE '%@%' THEN split_part(user_name, '@', 1)\n    ELSE user_name\n  END\n  WHERE user_name LIKE '%@%';\n  \n  GET DIAGNOSTICS updated_count = ROW_COUNT;\n  \n  -- Log the cleanup action\n  PERFORM public.log_sensitive_action(\n    'chat_messages_user_names_cleanup',\n    'chat_messages',\n    NULL,\n    jsonb_build_object(\n      'updated_count', updated_count,\n      'cleanup_time', now()\n    )\n  );\n  \n  RETURN updated_count;\nEND;\n$$;\n\n-- Execute the cleanup function to fix existing chat messages\nSELECT public.cleanup_chat_message_user_names();\n\n-- Update the create_chat_message function to use cleaned profile display_name\nCREATE OR REPLACE FUNCTION public.create_chat_message(p_message text, p_channel_id text DEFAULT 'community'::text, p_is_private boolean DEFAULT false, p_allowed_users uuid[] DEFAULT NULL::uuid[])\nRETURNS uuid\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $$\nDECLARE\n  message_id UUID;\n  user_profile RECORD;\n  clean_username TEXT;\nBEGIN\n  -- Check authentication\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'Authentication required';\n  END IF;\n  \n  -- Check rate limiting\n  IF NOT public.check_sensitive_data_rate_limit(auth.uid(), 'chat_messages') THEN\n    RAISE EXCEPTION 'Rate limit exceeded for chat messages';\n  END IF;\n  \n  -- Get user profile for level and pro status\n  SELECT level, 'pro' = ANY(achievements) as is_pro, display_name\n  INTO user_profile\n  FROM public.profiles\n  WHERE user_id = auth.uid();\n  \n  -- Clean the username (remove email domain if present)\n  clean_username := CASE \n    WHEN user_profile.display_name LIKE '%@%' THEN split_part(user_profile.display_name, '@', 1)\n    ELSE COALESCE(user_profile.display_name, 'Anonymous')\n  END;\n  \n  -- Insert the message with cleaned username\n  INSERT INTO public.chat_messages (\n    user_id,\n    user_name, \n    user_level,\n    is_pro,\n    message,\n    channel_id,\n    is_private,\n    allowed_users\n  ) VALUES (\n    auth.uid(),\n    clean_username,\n    COALESCE(user_profile.level, 1),\n    COALESCE(user_profile.is_pro, false),\n    p_message,\n    p_channel_id,\n    p_is_private,\n    p_allowed_users\n  ) RETURNING id INTO message_id;\n  \n  -- Log the message creation\n  PERFORM public.log_data_access(\n    'chat_messages',\n    'message_created',\n    message_id,\n    jsonb_build_object(\n      'channel_id', p_channel_id,\n      'is_private', p_is_private,\n      'message_length', length(p_message),\n      'username', clean_username\n    )\n  );\n  \n  RETURN message_id;\nEND;\n$$;"}		elvisiondragon@gmail.com	\N
20250816012124	{"-- First, let's create an admin role for the dragon user\n-- Find user by email pattern and update their profile to admin status\nUPDATE public.profiles \nSET achievements = ARRAY['admin'], \n    level = 999, -- Special admin level  \n    updated_at = now()\nWHERE user_id IN (\n  SELECT auth.users.id \n  FROM auth.users \n  WHERE email LIKE '%dragon%yahoo.com'\n);\n\n-- Create admin role entry\nINSERT INTO public.admin_roles (user_id, role, granted_by, is_active)\nSELECT auth.users.id, 'admin', auth.users.id, true\nFROM auth.users \nWHERE email LIKE '%dragon%yahoo.com'\nON CONFLICT (user_id) DO UPDATE SET\n  role = 'admin',\n  is_active = true,\n  granted_at = now();"}		elvisiondragon@gmail.com	\N
20250820020152	{"-- Create subscription_plans table to store available plans\nCREATE TABLE IF NOT EXISTS public.subscription_plans (\n  id TEXT PRIMARY KEY,\n  name TEXT NOT NULL,\n  description TEXT,\n  price INTEGER NOT NULL,\n  currency TEXT DEFAULT 'IDR',\n  duration_days INTEGER NOT NULL,\n  payment_method_code TEXT DEFAULT 'BCAVA',\n  payment_method TEXT DEFAULT 'BCA Virtual Account',\n  is_active BOOLEAN DEFAULT true,\n  created_at TIMESTAMP WITH TIME ZONE DEFAULT now(),\n  updated_at TIMESTAMP WITH TIME ZONE DEFAULT now()\n);\n\n-- Enable RLS\nALTER TABLE public.subscription_plans ENABLE ROW LEVEL SECURITY;\n\n-- Allow everyone to view active plans\nCREATE POLICY \\"Anyone can view active subscription plans\\" \nON public.subscription_plans \nFOR SELECT \nUSING (is_active = true);\n\n-- Insert the subscription plans\nINSERT INTO public.subscription_plans (id, name, description, price, duration_days, payment_method_code, payment_method) VALUES\n('1_year', '1 Year Subscription', 'Annual subscription with full access', 800000, 365, 'BCAVA', 'BCA Virtual Account'),\n('1_month', '1 Month Subscription', 'Monthly subscription with full access', 100000, 30, 'BCAVA', 'BCA Virtual Account'),\n('1_week', '1 Week Subscription', 'Weekly subscription with full access', 30000, 7, 'BCAVA', 'BCA Virtual Account'),\n('1_day', '1 Day Subscription', 'Daily subscription with full access', 4000, 1, 'BCAVA', 'BCA Virtual Account')\nON CONFLICT (id) DO UPDATE SET\n  name = EXCLUDED.name,\n  description = EXCLUDED.description,\n  price = EXCLUDED.price,\n  duration_days = EXCLUDED.duration_days,\n  updated_at = now();"}		elvisiondragon@gmail.com	\N
20250820020222	{"-- Enable RLS on tables that are missing it\nALTER TABLE public.orders ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.packages ENABLE ROW LEVEL SECURITY;  \nALTER TABLE public.subscriptions ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.transactions ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.user_memberships ENABLE ROW LEVEL SECURITY;\n\n-- Add basic policies for orders table\nCREATE POLICY \\"Users can view their own orders\\" ON public.orders \nFOR SELECT USING (customer_email = (SELECT email FROM auth.users WHERE id = auth.uid()));\n\nCREATE POLICY \\"Service can insert orders\\" ON public.orders \nFOR INSERT WITH CHECK (true);\n\nCREATE POLICY \\"Service can update orders\\" ON public.orders \nFOR UPDATE USING (true);\n\n-- Add basic policies for packages table (public read access)\nCREATE POLICY \\"Anyone can view packages\\" ON public.packages \nFOR SELECT USING (true);\n\n-- Add basic policies for subscriptions table  \nCREATE POLICY \\"Users can view their own subscriptions\\" ON public.subscriptions \nFOR SELECT USING (customer_email = (SELECT email FROM auth.users WHERE id = auth.uid()));\n\nCREATE POLICY \\"Service can insert subscriptions\\" ON public.subscriptions \nFOR INSERT WITH CHECK (true);\n\nCREATE POLICY \\"Service can update subscriptions\\" ON public.subscriptions \nFOR UPDATE USING (true);\n\n-- Add basic policies for transactions table\nCREATE POLICY \\"Users can view their own transactions\\" ON public.transactions \nFOR SELECT USING (user_id = auth.uid());\n\nCREATE POLICY \\"Service can insert transactions\\" ON public.transactions \nFOR INSERT WITH CHECK (true);\n\nCREATE POLICY \\"Service can update transactions\\" ON public.transactions \nFOR UPDATE USING (true);\n\n-- Add basic policies for user_memberships table\nCREATE POLICY \\"Users can view their own memberships\\" ON public.user_memberships \nFOR SELECT USING (user_id = auth.uid());\n\nCREATE POLICY \\"Service can insert memberships\\" ON public.user_memberships \nFOR INSERT WITH CHECK (true);\n\nCREATE POLICY \\"Service can update memberships\\" ON public.user_memberships \nFOR UPDATE USING (true);"}		elvisiondragon@gmail.com	\N
20250821041906	{"-- Add pro achievement to profiles and create subscription sync system\n\n-- Function to grant pro status to a user\nCREATE OR REPLACE FUNCTION public.grant_pro_status(p_user_id uuid)\nRETURNS void\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $$\nBEGIN\n  -- Add 'pro' to achievements array if not already present\n  UPDATE public.profiles \n  SET achievements = CASE \n    WHEN 'pro' = ANY(achievements) THEN achievements\n    ELSE array_append(achievements, 'pro')\n  END,\n  updated_at = now()\n  WHERE user_id = p_user_id;\n  \n  -- Create profile if it doesn't exist\n  IF NOT FOUND THEN\n    INSERT INTO public.profiles (user_id, achievements)\n    VALUES (p_user_id, ARRAY['pro'])\n    ON CONFLICT (user_id) DO UPDATE SET\n      achievements = CASE \n        WHEN 'pro' = ANY(excluded.achievements) THEN excluded.achievements\n        ELSE array_append(profiles.achievements, 'pro')\n      END,\n      updated_at = now();\n  END IF;\nEND;\n$$;\n\n-- Function to revoke pro status from a user  \nCREATE OR REPLACE FUNCTION public.revoke_pro_status(p_user_id uuid)\nRETURNS void\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $$\nBEGIN\n  -- Remove 'pro' from achievements array\n  UPDATE public.profiles \n  SET achievements = array_remove(achievements, 'pro'),\n      updated_at = now()\n  WHERE user_id = p_user_id;\nEND;\n$$;\n\n-- Function to sync pro status based on subscription\nCREATE OR REPLACE FUNCTION public.sync_pro_status_from_subscription(p_user_id uuid)\nRETURNS boolean\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $$\nDECLARE\n  has_active_subscription boolean := false;\n  sub_record RECORD;\nBEGIN\n  -- Check if user has active VIP subscription\n  SELECT * INTO sub_record\n  FROM public.vip_subscriptions\n  WHERE user_id = p_user_id\n  ORDER BY created_at DESC\n  LIMIT 1;\n  \n  IF FOUND THEN\n    -- Check if subscription is active and not expired\n    IF sub_record.status = 'active' THEN\n      IF sub_record.subscription_type = 'trial' AND sub_record.trial_end_date > now() THEN\n        has_active_subscription := true;\n      ELSIF sub_record.subscription_type IN ('monthly', 'yearly') AND \n            (sub_record.subscription_end_date IS NULL OR sub_record.subscription_end_date > now()) THEN\n        has_active_subscription := true;\n      END IF;\n    END IF;\n  END IF;\n  \n  -- Grant or revoke pro status based on subscription\n  IF has_active_subscription THEN\n    PERFORM public.grant_pro_status(p_user_id);\n  ELSE\n    PERFORM public.revoke_pro_status(p_user_id);\n  END IF;\n  \n  RETURN has_active_subscription;\nEND;\n$$;\n\n-- Function to check if user has pro achievement\nCREATE OR REPLACE FUNCTION public.has_pro_achievement(p_user_id uuid)\nRETURNS boolean\nLANGUAGE plpgsql\nSTABLE\nSECURITY DEFINER\nSET search_path = 'public'\nAS $$\nBEGIN\n  RETURN EXISTS (\n    SELECT 1 FROM public.profiles \n    WHERE user_id = p_user_id \n    AND 'pro' = ANY(achievements)\n  );\nEND;\n$$;\n\n-- Trigger function to auto-sync pro status when VIP subscription changes\nCREATE OR REPLACE FUNCTION public.auto_sync_pro_on_subscription_change()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $$\nBEGIN\n  -- Sync pro status for the user whose subscription changed\n  PERFORM public.sync_pro_status_from_subscription(COALESCE(NEW.user_id, OLD.user_id));\n  \n  RETURN COALESCE(NEW, OLD);\nEND;\n$$;\n\n-- Create trigger on vip_subscriptions table\nDROP TRIGGER IF EXISTS trigger_auto_sync_pro ON public.vip_subscriptions;\nCREATE TRIGGER trigger_auto_sync_pro\n  AFTER INSERT OR UPDATE OR DELETE ON public.vip_subscriptions\n  FOR EACH ROW\n  EXECUTE FUNCTION public.auto_sync_pro_on_subscription_change();\n\n-- Sync pro status for all existing users with VIP subscriptions\nDO $$\nDECLARE\n  user_record RECORD;\nBEGIN\n  FOR user_record IN \n    SELECT DISTINCT user_id FROM public.vip_subscriptions \n  LOOP\n    PERFORM public.sync_pro_status_from_subscription(user_record.user_id);\n  END LOOP;\nEND $$;"}		elvisiondragon@gmail.com	\N
20250821042044	{"-- Update create_chat_message function to use pro achievement from achievements array\nCREATE OR REPLACE FUNCTION public.create_chat_message(p_message text, p_channel_id text DEFAULT 'community'::text, p_is_private boolean DEFAULT false, p_allowed_users uuid[] DEFAULT NULL::uuid[])\nRETURNS uuid\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $$\nDECLARE\n  message_id UUID;\n  user_profile RECORD;\n  clean_username TEXT;\nBEGIN\n  -- Check authentication\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'Authentication required';\n  END IF;\n  \n  -- Check rate limiting\n  IF NOT public.check_sensitive_data_rate_limit(auth.uid(), 'chat_messages') THEN\n    RAISE EXCEPTION 'Rate limit exceeded for chat messages';\n  END IF;\n  \n  -- Get user profile for level and pro status from achievements\n  SELECT level, 'pro' = ANY(achievements) as is_pro, display_name\n  INTO user_profile\n  FROM public.profiles\n  WHERE user_id = auth.uid();\n  \n  -- Clean the username (remove email domain if present)\n  clean_username := CASE \n    WHEN user_profile.display_name LIKE '%@%' THEN split_part(user_profile.display_name, '@', 1)\n    ELSE COALESCE(user_profile.display_name, 'Anonymous')\n  END;\n  \n  -- Insert the message with cleaned username and proper pro status\n  INSERT INTO public.chat_messages (\n    user_id,\n    user_name, \n    user_level,\n    is_pro,\n    message,\n    channel_id,\n    is_private,\n    allowed_users\n  ) VALUES (\n    auth.uid(),\n    clean_username,\n    COALESCE(user_profile.level, 1),\n    COALESCE(user_profile.is_pro, false),\n    p_message,\n    p_channel_id,\n    p_is_private,\n    p_allowed_users\n  ) RETURNING id INTO message_id;\n  \n  -- Log the message creation\n  PERFORM public.log_data_access(\n    'chat_messages',\n    'message_created',\n    message_id,\n    jsonb_build_object(\n      'channel_id', p_channel_id,\n      'is_private', p_is_private,\n      'message_length', length(p_message),\n      'username', clean_username,\n      'is_pro', COALESCE(user_profile.is_pro, false)\n    )\n  );\n  \n  RETURN message_id;\nEND;\n$$;"}		elvisiondragon@gmail.com	\N
20250821042413	{"-- Fix the audit function for VIP subscriptions (remove email reference)\nCREATE OR REPLACE FUNCTION public.audit_vip_changes()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $$\nBEGIN\n  -- Log subscription status changes\n  IF TG_OP = 'UPDATE' AND OLD.status != NEW.status THEN\n    PERFORM public.log_sensitive_action(\n      'vip_subscription_status_change',\n      'vip_subscriptions',\n      NEW.id,\n      jsonb_build_object(\n        'old_status', OLD.status,\n        'new_status', NEW.status,\n        'user_id', NEW.user_id\n      )\n    );\n  END IF;\n  \n  -- Log new subscriptions\n  IF TG_OP = 'INSERT' THEN\n    PERFORM public.log_sensitive_action(\n      'vip_subscription_created',\n      'vip_subscriptions',\n      NEW.id,\n      jsonb_build_object(\n        'subscription_type', NEW.subscription_type,\n        'user_id', NEW.user_id\n      )\n    );\n  END IF;\n  \n  RETURN COALESCE(NEW, OLD);\nEND;\n$$;\n\n-- Now grant hendi a 30-day subscription and pro status\nINSERT INTO vip_subscriptions (\n  user_id, \n  subscription_type, \n  status, \n  subscription_start_date, \n  subscription_end_date,\n  amount_paid,\n  currency\n) VALUES (\n  '8fa357c9-4450-4e90-b3c9-6886f7159287'::uuid,\n  'monthly',\n  'active',\n  now(),\n  now() + interval '30 days',\n  25000,\n  'IDR'\n);"}		elvisiondragon@gmail.com	\N
20250821042511	{"-- Update hendi's existing chat message to show pro status\nUPDATE chat_messages \nSET is_pro = true \nWHERE user_id = '8fa357c9-4450-4e90-b3c9-6886f7159287';"}		elvisiondragon@gmail.com	\N
20250821043540	{"-- First, add the email column\nALTER TABLE public.pro_subscriptions \nADD COLUMN IF NOT EXISTS user_email text;\n\n-- Update the sync function to reference pro_subscriptions instead of vip_subscriptions\nCREATE OR REPLACE FUNCTION public.sync_pro_status_from_subscription(p_user_id uuid)\nRETURNS boolean\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $$\nDECLARE\n  has_active_subscription boolean := false;\n  sub_record RECORD;\nBEGIN\n  -- Check if user has active pro subscription (updated table name)\n  SELECT * INTO sub_record\n  FROM public.pro_subscriptions\n  WHERE user_id = p_user_id\n  ORDER BY created_at DESC\n  LIMIT 1;\n  \n  IF FOUND THEN\n    -- Check if subscription is active and not expired\n    IF sub_record.status = 'active' THEN\n      IF sub_record.subscription_type = 'trial' AND sub_record.trial_end_date > now() THEN\n        has_active_subscription := true;\n      ELSIF sub_record.subscription_type IN ('monthly', 'yearly') AND \n            (sub_record.subscription_end_date IS NULL OR sub_record.subscription_end_date > now()) THEN\n        has_active_subscription := true;\n      END IF;\n    END IF;\n  END IF;\n  \n  -- Grant or revoke pro status based on subscription\n  IF has_active_subscription THEN\n    PERFORM public.grant_pro_status(p_user_id);\n  ELSE\n    PERFORM public.revoke_pro_status(p_user_id);\n  END IF;\n  \n  RETURN has_active_subscription;\nEND;\n$$;"}		elvisiondragon@gmail.com	\N
20250821043617	{"-- Populate the user_email column with emails from auth.users\nUPDATE public.pro_subscriptions \nSET user_email = u.email\nFROM auth.users u \nWHERE pro_subscriptions.user_id = u.id \nAND (pro_subscriptions.user_email IS NULL OR pro_subscriptions.user_email = '');\n\n-- Set default email for any records without matching users\nUPDATE public.pro_subscriptions \nSET user_email = 'unknown@example.com'\nWHERE user_email IS NULL OR user_email = '';\n\n-- Create index for better performance on email searches\nCREATE INDEX IF NOT EXISTS idx_pro_subscriptions_email ON public.pro_subscriptions(user_email);\n\n-- Create a helpful admin view for easy identification\nCREATE OR REPLACE VIEW public.pro_subscriptions_admin_view AS\nSELECT \n  ps.id,\n  ps.user_id,\n  ps.user_email,\n  p.display_name,\n  ps.subscription_type,\n  ps.status,\n  ps.amount_paid,\n  ps.currency,\n  ps.subscription_start_date,\n  ps.subscription_end_date,\n  ps.trial_start_date,\n  ps.trial_end_date,\n  CASE \n    WHEN ps.status = 'active' AND ps.subscription_type = 'trial' AND ps.trial_end_date > now() THEN 'Active Trial'\n    WHEN ps.status = 'active' AND ps.subscription_type IN ('monthly', 'yearly') AND (ps.subscription_end_date IS NULL OR ps.subscription_end_date > now()) THEN 'Active Paid'\n    WHEN ps.subscription_end_date < now() OR ps.trial_end_date < now() THEN 'Expired'\n    ELSE ps.status\n  END as readable_status,\n  ps.created_at,\n  ps.updated_at\nFROM public.pro_subscriptions ps\nLEFT JOIN public.profiles p ON ps.user_id = p.user_id\nORDER BY ps.created_at DESC;"}		elvisiondragon@gmail.com	\N
20250821044020	{"-- Ensure the start_pro_trial function is properly created\nCREATE OR REPLACE FUNCTION public.start_pro_trial(p_user_id uuid, p_email text, p_ip_address text DEFAULT NULL::text)\nRETURNS uuid\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $$\nDECLARE\n  subscription_id UUID;\n  trial_end TIMESTAMPTZ;\nBEGIN\n  -- Calculate trial end date (3 days from now)\n  trial_end := now() + INTERVAL '3 days';\n  \n  -- Insert or update Pro subscription\n  INSERT INTO public.pro_subscriptions (\n    user_id, \n    user_email,\n    ip_address,\n    subscription_type,\n    status,\n    trial_start_date,\n    trial_end_date\n  ) VALUES (\n    p_user_id, \n    p_email, \n    p_ip_address,\n    'trial',\n    'active',\n    now(),\n    trial_end\n  )\n  ON CONFLICT (user_id) \n  DO UPDATE SET\n    subscription_type = 'trial',\n    status = 'active',\n    trial_start_date = now(),\n    trial_end_date = trial_end,\n    updated_at = now()\n  RETURNING id INTO subscription_id;\n  \n  RETURN subscription_id;\nEND;\n$$;\n\n-- Update audit trigger to use proper table name\nCREATE OR REPLACE FUNCTION public.audit_pro_changes()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $$\nBEGIN\n  -- Log subscription status changes\n  IF TG_OP = 'UPDATE' AND OLD.status != NEW.status THEN\n    PERFORM public.log_sensitive_action(\n      'pro_subscription_status_change',\n      'pro_subscriptions',\n      NEW.id,\n      jsonb_build_object(\n        'old_status', OLD.status,\n        'new_status', NEW.status,\n        'user_id', NEW.user_id,\n        'user_email', NEW.user_email\n      )\n    );\n  END IF;\n  \n  -- Log new subscriptions\n  IF TG_OP = 'INSERT' THEN\n    PERFORM public.log_sensitive_action(\n      'pro_subscription_created',\n      'pro_subscriptions',\n      NEW.id,\n      jsonb_build_object(\n        'subscription_type', NEW.subscription_type,\n        'user_id', NEW.user_id,\n        'user_email', NEW.user_email\n      )\n    );\n  END IF;\n  \n  RETURN COALESCE(NEW, OLD);\nEND;\n$$;\n\n-- Replace the old audit trigger\nDROP TRIGGER IF EXISTS audit_vip_changes_trigger ON public.pro_subscriptions;\nCREATE TRIGGER audit_pro_changes_trigger\n  AFTER INSERT OR UPDATE ON public.pro_subscriptions\n  FOR EACH ROW\n  EXECUTE FUNCTION public.audit_pro_changes();"}		elvisiondragon@gmail.com	\N
20250821045452	{"-- Enable RLS on pro_subscriptions table (if not already enabled)\nDO $$ \nBEGIN\n  IF NOT (SELECT rowsecurity FROM pg_tables WHERE tablename = 'pro_subscriptions' AND schemaname = 'public') THEN\n    ALTER TABLE public.pro_subscriptions ENABLE ROW LEVEL SECURITY;\n  END IF;\nEND $$;\n\n-- Drop existing policies if they exist and recreate them\nDROP POLICY IF EXISTS \\"Users can view their own subscription\\" ON public.pro_subscriptions;\nDROP POLICY IF EXISTS \\"Users can insert their own subscription\\" ON public.pro_subscriptions;\nDROP POLICY IF EXISTS \\"Users can update their own subscription\\" ON public.pro_subscriptions;\nDROP POLICY IF EXISTS \\"Verified admins can view subscriptions\\" ON public.pro_subscriptions;\n\n-- Create comprehensive RLS policies\nCREATE POLICY \\"Users can view their own subscription\\"\nON public.pro_subscriptions\nFOR SELECT\nUSING (auth.uid() = user_id);\n\nCREATE POLICY \\"Users can insert their own subscription\\"\nON public.pro_subscriptions\nFOR INSERT\nWITH CHECK (auth.uid() = user_id);\n\nCREATE POLICY \\"Users can update their own subscription\\"\nON public.pro_subscriptions\nFOR UPDATE\nUSING (auth.uid() = user_id);\n\nCREATE POLICY \\"Verified admins can view all subscriptions\\"\nON public.pro_subscriptions\nFOR SELECT\nUSING (is_verified_admin(auth.uid()));\n\n-- Create function to automatically start trial for new users\nCREATE OR REPLACE FUNCTION public.handle_new_user_trial()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $$\nDECLARE\n  user_email TEXT;\nBEGIN\n  -- Get user email\n  user_email := NEW.email;\n  \n  -- Start 2-day trial automatically\n  INSERT INTO public.pro_subscriptions (\n    user_id,\n    user_email,\n    subscription_type,\n    status,\n    trial_start_date,\n    trial_end_date\n  ) VALUES (\n    NEW.id,\n    user_email,\n    'trial',\n    'active',\n    now(),\n    now() + INTERVAL '2 days'\n  );\n  \n  RETURN NEW;\nEND;\n$$;\n\n-- Create trigger to start trial on user signup (drop existing first)\nDROP TRIGGER IF EXISTS on_auth_user_created_trial ON auth.users;\nCREATE TRIGGER on_auth_user_created_trial\n  AFTER INSERT ON auth.users\n  FOR EACH ROW \n  EXECUTE FUNCTION public.handle_new_user_trial();\n\n-- Function to check verse access based on level and pro status\nCREATE OR REPLACE FUNCTION public.can_access_verse(p_user_id uuid, p_verse_number integer)\nRETURNS boolean\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $$\nDECLARE\n  user_level INTEGER;\n  is_pro_user BOOLEAN;\n  pro_status RECORD;\nBEGIN\n  -- Get user level\n  SELECT level INTO user_level\n  FROM public.profiles\n  WHERE user_id = p_user_id;\n  \n  -- Get pro status\n  SELECT * INTO pro_status\n  FROM public.check_pro_status(p_user_id);\n  \n  is_pro_user := COALESCE(pro_status.is_pro, false);\n  \n  -- Pro users can access verses 1-4 regardless of level\n  IF is_pro_user AND p_verse_number <= 4 THEN\n    RETURN true;\n  END IF;\n  \n  -- Level-based access for non-pro users\n  CASE p_verse_number\n    WHEN 1 THEN RETURN user_level >= 3;\n    WHEN 2 THEN RETURN user_level >= 4; \n    WHEN 3 THEN RETURN user_level >= 4;\n    WHEN 4 THEN RETURN user_level >= 5;\n    ELSE RETURN false;\n  END CASE;\nEND;\n$$;"}		elvisiondragon@gmail.com	\N
20250821055351	{"-- Drop existing view if it exists\nDROP VIEW IF EXISTS pro_subscriptions_admin_view;\n\n-- Create admin view for pro_subscriptions with reordered columns\nCREATE VIEW pro_subscriptions_admin_view AS\nSELECT \n  id,\n  user_id,\n  user_email,\n  status,\n  subscription_type,\n  subscription_start_date,\n  subscription_end_date,\n  trial_start_date,\n  trial_end_date,\n  amount_paid,\n  currency,\n  created_at,\n  updated_at,\n  -- Add helper columns for display\n  (SELECT display_name FROM profiles WHERE user_id = ps.user_id) as display_name,\n  CASE \n    WHEN status = 'active' AND subscription_type = 'trial' AND trial_end_date > now() THEN 'Active Trial'\n    WHEN status = 'active' AND subscription_type IN ('monthly', 'yearly', 'weekly', 'daily') AND (subscription_end_date IS NULL OR subscription_end_date > now()) THEN 'Active Subscription'\n    WHEN status = 'expired' THEN 'Expired'\n    WHEN status = 'pending' THEN 'Pending Activation'\n    ELSE status\n  END as readable_status\nFROM pro_subscriptions ps\nORDER BY created_at DESC;\n\n-- Create function to manually update subscription status with duration\nCREATE OR REPLACE FUNCTION update_subscription_status_manually(\n  p_subscription_id UUID,\n  p_status TEXT,\n  p_subscription_type TEXT,\n  p_duration_type TEXT DEFAULT 'monthly'\n) RETURNS JSONB\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public'\nAS $$\nDECLARE\n  subscription_record RECORD;\n  new_end_date TIMESTAMP WITH TIME ZONE;\n  result JSONB;\nBEGIN\n  -- Check if user is admin\n  IF NOT is_verified_admin(auth.uid()) THEN\n    RAISE EXCEPTION 'Only verified admins can manually update subscription status';\n  END IF;\n  \n  -- Get the subscription\n  SELECT * INTO subscription_record\n  FROM pro_subscriptions\n  WHERE id = p_subscription_id;\n  \n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Subscription not found';\n  END IF;\n  \n  -- Calculate end date based on duration type\n  IF p_status = 'active' AND p_subscription_type != 'trial' THEN\n    CASE p_duration_type\n      WHEN 'daily' THEN new_end_date := now() + INTERVAL '1 day';\n      WHEN 'weekly' THEN new_end_date := now() + INTERVAL '1 week';\n      WHEN 'monthly' THEN new_end_date := now() + INTERVAL '1 month';\n      WHEN 'yearly' THEN new_end_date := now() + INTERVAL '1 year';\n      ELSE new_end_date := now() + INTERVAL '1 month'; -- Default to monthly\n    END CASE;\n  END IF;\n  \n  -- Update the subscription\n  UPDATE pro_subscriptions\n  SET \n    status = p_status,\n    subscription_type = p_subscription_type,\n    subscription_start_date = CASE \n      WHEN p_status = 'active' AND p_subscription_type != 'trial' THEN now()\n      ELSE subscription_start_date\n    END,\n    subscription_end_date = CASE \n      WHEN p_status = 'active' AND p_subscription_type != 'trial' THEN new_end_date\n      ELSE subscription_end_date\n    END,\n    updated_at = now()\n  WHERE id = p_subscription_id;\n  \n  -- Sync pro status for the user\n  PERFORM sync_pro_status_from_subscription(subscription_record.user_id);\n  \n  -- Log the manual update\n  PERFORM log_sensitive_action(\n    'manual_subscription_update',\n    'pro_subscriptions',\n    p_subscription_id,\n    jsonb_build_object(\n      'admin_user', auth.uid(),\n      'target_user', subscription_record.user_id,\n      'old_status', subscription_record.status,\n      'new_status', p_status,\n      'old_type', subscription_record.subscription_type,\n      'new_type', p_subscription_type,\n      'duration_type', p_duration_type,\n      'new_end_date', new_end_date\n    )\n  );\n  \n  result := jsonb_build_object(\n    'success', true,\n    'subscription_id', p_subscription_id,\n    'status', p_status,\n    'subscription_type', p_subscription_type,\n    'end_date', new_end_date,\n    'message', 'Subscription updated successfully'\n  );\n  \n  RETURN result;\nEND;\n$$;"}		elvisiondragon@gmail.com	\N
20250821055432	{"-- Remove SECURITY DEFINER from view and create a proper function for admin access\nDROP VIEW IF EXISTS pro_subscriptions_admin_view;\n\n-- Create a regular view without SECURITY DEFINER\nCREATE VIEW pro_subscriptions_admin_view AS\nSELECT \n  id,\n  user_id,\n  user_email,\n  status,\n  subscription_type,\n  subscription_start_date,\n  subscription_end_date,\n  trial_start_date,\n  trial_end_date,\n  amount_paid,\n  currency,\n  created_at,\n  updated_at,\n  -- Add helper columns for display\n  (SELECT display_name FROM profiles WHERE user_id = ps.user_id) as display_name,\n  CASE \n    WHEN status = 'active' AND subscription_type = 'trial' AND trial_end_date > now() THEN 'Active Trial'\n    WHEN status = 'active' AND subscription_type IN ('monthly', 'yearly', 'weekly', 'daily') AND (subscription_end_date IS NULL OR subscription_end_date > now()) THEN 'Active Subscription'\n    WHEN status = 'expired' THEN 'Expired'\n    WHEN status = 'pending' THEN 'Pending Activation'\n    ELSE status\n  END as readable_status\nFROM pro_subscriptions ps\nORDER BY created_at DESC;"}		elvisiondragon@gmail.com	\N
20250821060008	{"-- Step 1: Grant super_admin role to yourself (replace with your actual user_id)\n-- First, let's create a super admin manually (this is a one-time setup)\nINSERT INTO public.admin_roles (user_id, role, granted_by, is_active)\nVALUES (\n  '8fa357c9-4450-4e90-b3c9-6886f7159287', -- Replace with your user_id (hendi in this case)\n  'super_admin',\n  '8fa357c9-4450-4e90-b3c9-6886f7159287', -- Self-granted for initial setup\n  true\n)\nON CONFLICT (user_id) DO UPDATE SET\n  role = 'super_admin',\n  is_active = true,\n  granted_at = now();"}		elvisiondragon@gmail.com	\N
20250821060143	{"-- Revoke super_admin from hendi@yahoo.com\nUPDATE public.admin_roles \nSET is_active = false \nWHERE user_id = '8fa357c9-4450-4e90-b3c9-6886f7159287' AND role = 'super_admin';\n\n-- Grant super_admin to elvisiondragon@gmail.com\nINSERT INTO public.admin_roles (user_id, role, granted_by, is_active)\nVALUES ('8c2cd3b1-6b77-4df9-92c5-467182ecd13d', 'super_admin', '8fa357c9-4450-4e90-b3c9-6886f7159287', true)\nON CONFLICT (user_id) DO UPDATE SET\n  role = 'super_admin',\n  granted_by = '8fa357c9-4450-4e90-b3c9-6886f7159287',\n  granted_at = now(),\n  is_active = true;"}		elvisiondragon@gmail.com	\N
20250822022634	{"-- Fix the ambiguous status column in check_pro_status function\nCREATE OR REPLACE FUNCTION public.check_pro_status(p_user_id uuid)\nRETURNS TABLE(\n  is_pro boolean,\n  subscription_type text,\n  status text,\n  expires_at timestamptz,\n  days_remaining integer\n) \nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public'\nAS $$\nDECLARE\n  subscription_record RECORD;\n  current_time timestamptz := now();\nBEGIN\n  -- Get the most recent active subscription\n  SELECT * INTO subscription_record\n  FROM public.pro_subscriptions ps\n  WHERE ps.user_id = p_user_id\n  ORDER BY ps.created_at DESC\n  LIMIT 1;\n  \n  -- If no subscription found\n  IF NOT FOUND THEN\n    RETURN QUERY SELECT false, null::text, null::text, null::timestamptz, null::integer;\n    RETURN;\n  END IF;\n  \n  -- Check if subscription is active based on type\n  IF subscription_record.subscription_type = 'trial' THEN\n    IF subscription_record.status = 'active' AND \n       subscription_record.trial_end_date IS NOT NULL AND \n       subscription_record.trial_end_date > current_time THEN\n      RETURN QUERY SELECT \n        true,\n        subscription_record.subscription_type,\n        subscription_record.status,\n        subscription_record.trial_end_date,\n        EXTRACT(days FROM (subscription_record.trial_end_date - current_time))::integer;\n    ELSE\n      RETURN QUERY SELECT false, subscription_record.subscription_type, 'expired', subscription_record.trial_end_date, 0;\n    END IF;\n  ELSIF subscription_record.subscription_type IN ('monthly', 'yearly') THEN\n    IF subscription_record.status = 'active' AND\n       (subscription_record.subscription_end_date IS NULL OR subscription_record.subscription_end_date > current_time) THEN\n      RETURN QUERY SELECT \n        true,\n        subscription_record.subscription_type,\n        subscription_record.status,\n        COALESCE(subscription_record.subscription_end_date, subscription_record.trial_end_date),\n        CASE \n          WHEN subscription_record.subscription_end_date IS NOT NULL \n          THEN EXTRACT(days FROM (subscription_record.subscription_end_date - current_time))::integer\n          ELSE null::integer\n        END;\n    ELSE\n      RETURN QUERY SELECT false, subscription_record.subscription_type, 'expired', subscription_record.subscription_end_date, 0;\n    END IF;\n  ELSE\n    RETURN QUERY SELECT false, subscription_record.subscription_type, subscription_record.status, null::timestamptz, null::integer;\n  END IF;\n  \n  RETURN;\nEND;\n$$;"}		elvisiondragon@gmail.com	\N
20250822122609	{"-- Create pro_user table for subscription management\nCREATE TABLE public.pro_user (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  email TEXT NOT NULL,\n  status TEXT NOT NULL DEFAULT 'pending',\n  subscription_type TEXT NOT NULL DEFAULT 'monthly',\n  start_date TIMESTAMP WITH TIME ZONE,\n  end_date TIMESTAMP WITH TIME ZONE,\n  amount NUMERIC,\n  currency TEXT DEFAULT 'IDR',\n  tripay_reference TEXT,\n  payment_method TEXT,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()\n);\n\n-- Create index for faster email lookups\nCREATE INDEX idx_pro_user_email ON public.pro_user(email);\nCREATE INDEX idx_pro_user_status ON public.pro_user(status);\nCREATE INDEX idx_pro_user_end_date ON public.pro_user(end_date);\n\n-- Enable Row Level Security but with team-friendly policies\nALTER TABLE public.pro_user ENABLE ROW LEVEL SECURITY;\n\n-- Policy for team members to manage all subscriptions (no restrictions)\nCREATE POLICY \\"Team can manage all pro_user records\\" \nON public.pro_user \nFOR ALL \nUSING (true) \nWITH CHECK (true);\n\n-- Function to calculate subscription end date\nCREATE OR REPLACE FUNCTION public.calculate_subscription_end_date(\n  p_subscription_type TEXT,\n  p_start_date TIMESTAMP WITH TIME ZONE DEFAULT now()\n)\nRETURNS TIMESTAMP WITH TIME ZONE\nLANGUAGE plpgsql\nAS $$\nBEGIN\n  CASE p_subscription_type\n    WHEN 'daily' THEN\n      RETURN p_start_date + INTERVAL '1 day';\n    WHEN 'weekly' THEN\n      RETURN p_start_date + INTERVAL '7 days';\n    WHEN 'monthly' THEN\n      RETURN p_start_date + INTERVAL '30 days';\n    WHEN 'yearly' THEN\n      RETURN p_start_date + INTERVAL '365 days';\n    ELSE\n      RETURN p_start_date + INTERVAL '30 days'; -- Default to monthly\n  END CASE;\nEND;\n$$;\n\n-- Function to check pro status from pro_user table\nCREATE OR REPLACE FUNCTION public.check_pro_status(p_user_id UUID)\nRETURNS TABLE(\n  is_pro BOOLEAN,\n  subscription_type TEXT,\n  status TEXT,\n  expires_at TIMESTAMP WITH TIME ZONE,\n  days_remaining INTEGER\n)\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public'\nAS $$\nDECLARE\n  user_email TEXT;\n  user_record RECORD;\n  remaining_days INTEGER;\nBEGIN\n  -- Get user email from auth.users\n  SELECT email INTO user_email\n  FROM auth.users\n  WHERE id = p_user_id;\n  \n  IF user_email IS NULL THEN\n    RETURN QUERY SELECT false, NULL::TEXT, NULL::TEXT, NULL::TIMESTAMPTZ, NULL::INTEGER;\n    RETURN;\n  END IF;\n  \n  -- Get user's pro subscription\n  SELECT * INTO user_record\n  FROM public.pro_user\n  WHERE email = user_email\n  AND status = 'active'\n  ORDER BY created_at DESC\n  LIMIT 1;\n  \n  IF NOT FOUND THEN\n    RETURN QUERY SELECT false, NULL::TEXT, NULL::TEXT, NULL::TIMESTAMPTZ, NULL::INTEGER;\n    RETURN;\n  END IF;\n  \n  -- Calculate remaining days\n  remaining_days := EXTRACT(DAY FROM (user_record.end_date - now()));\n  \n  -- Check if subscription is still active\n  IF user_record.end_date > now() THEN\n    RETURN QUERY SELECT \n      true,\n      user_record.subscription_type,\n      user_record.status,\n      user_record.end_date,\n      remaining_days;\n  ELSE\n    -- Update expired subscriptions\n    UPDATE public.pro_user \n    SET status = 'expired', updated_at = now()\n    WHERE email = user_email AND status = 'active';\n    \n    RETURN QUERY SELECT \n      false,\n      user_record.subscription_type,\n      'expired'::TEXT,\n      user_record.end_date,\n      remaining_days;\n  END IF;\nEND;\n$$;\n\n-- Trigger to update updated_at timestamp\nCREATE TRIGGER update_pro_user_updated_at\n  BEFORE UPDATE ON public.pro_user\n  FOR EACH ROW\n  EXECUTE FUNCTION public.update_updated_at_column();\n\n-- Enable realtime for live monitoring\nALTER TABLE public.pro_user REPLICA IDENTITY FULL;\nALTER PUBLICATION supabase_realtime ADD TABLE public.pro_user;"}		elvisiondragon@gmail.com	\N
20250822021033	{"-- Add unique constraint to pro_user email column\nALTER TABLE public.pro_user ADD CONSTRAINT pro_user_email_unique UNIQUE (email);\n\n-- Create function to manually add pro users by email\nCREATE OR REPLACE FUNCTION public.add_pro_user_by_email(\n  p_email TEXT,\n  p_subscription_type TEXT DEFAULT 'monthly',\n  p_duration_days INTEGER DEFAULT 30\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public'\nAS $function$\nDECLARE\n  user_record RECORD;\n  start_date TIMESTAMPTZ;\n  end_date TIMESTAMPTZ;\n  result jsonb;\nBEGIN\n  -- Calculate dates\n  start_date := now();\n  end_date := start_date + (p_duration_days || ' days')::INTERVAL;\n  \n  -- Get user info if they exist\n  SELECT u.id, p.display_name INTO user_record\n  FROM auth.users u\n  LEFT JOIN public.profiles p ON p.user_id = u.id\n  WHERE u.email = p_email;\n  \n  -- Insert/update pro_user record\n  INSERT INTO public.pro_user (\n    email,\n    status,\n    subscription_type,\n    start_date,\n    end_date,\n    amount,\n    currency,\n    payment_method\n  ) VALUES (\n    p_email,\n    'active',\n    p_subscription_type,\n    start_date,\n    end_date,\n    CASE \n      WHEN p_subscription_type = 'yearly' THEN 1200000.00  -- 1.2M IDR yearly\n      ELSE 100000.00  -- 100K IDR monthly\n    END,\n    'IDR',\n    'Manual Grant'\n  )\n  ON CONFLICT (email) \n  DO UPDATE SET\n    status = 'active',\n    subscription_type = EXCLUDED.subscription_type,\n    start_date = EXCLUDED.start_date,\n    end_date = EXCLUDED.end_date,\n    amount = EXCLUDED.amount,\n    updated_at = now();\n  \n  -- If user exists, create/update pro_subscription record and sync pro status\n  IF user_record.id IS NOT NULL THEN\n    -- Create pro_subscription record\n    INSERT INTO public.pro_subscriptions (\n      user_id,\n      user_email,\n      subscription_type,\n      status,\n      subscription_start_date,\n      subscription_end_date,\n      amount_paid,\n      currency\n    ) VALUES (\n      user_record.id,\n      p_email,\n      p_subscription_type,\n      'active',\n      start_date,\n      end_date,\n      CASE \n        WHEN p_subscription_type = 'yearly' THEN 1200000.00\n        ELSE 100000.00\n      END,\n      'IDR'\n    )\n    ON CONFLICT (user_id)\n    DO UPDATE SET\n      subscription_type = EXCLUDED.subscription_type,\n      status = 'active',\n      subscription_start_date = EXCLUDED.subscription_start_date,\n      subscription_end_date = EXCLUDED.subscription_end_date,\n      amount_paid = EXCLUDED.amount_paid,\n      updated_at = now();\n    \n    -- Sync pro status to add 'pro' achievement\n    PERFORM public.sync_pro_status_from_subscription(user_record.id);\n    \n    result := jsonb_build_object(\n      'success', true,\n      'message', 'Pro status granted successfully',\n      'user_found', true,\n      'user_id', user_record.id,\n      'display_name', user_record.display_name,\n      'email', p_email,\n      'subscription_type', p_subscription_type,\n      'start_date', start_date,\n      'end_date', end_date\n    );\n  ELSE\n    result := jsonb_build_object(\n      'success', true,\n      'message', 'Pro user record created (user not yet registered)',\n      'user_found', false,\n      'email', p_email,\n      'subscription_type', p_subscription_type,\n      'start_date', start_date,\n      'end_date', end_date,\n      'note', 'Pro status will activate when user registers'\n    );\n  END IF;\n  \n  RETURN result;\nEND;\n$function$;\n\n-- Add the two pro users\nSELECT public.add_pro_user_by_email('evira.rotorasiko37@gmail.com', 'monthly', 30);\nSELECT public.add_pro_user_by_email('jraymondsusilo@gmail.com', 'yearly', 365);"}		elvisiondragon@gmail.com	\N
20250822021159	{"-- Fix security warnings by setting proper search_path on functions\n\n-- Update check_pro_status function\nDROP FUNCTION IF EXISTS public.check_pro_status(uuid);\nCREATE OR REPLACE FUNCTION public.check_pro_status(p_user_id uuid)\nRETURNS TABLE(\n  is_pro boolean,\n  subscription_type text,\n  status text,\n  expires_at timestamp with time zone,\n  days_remaining integer\n)\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $function$\nDECLARE\n  pro_record RECORD;\n  has_pro_achievement boolean;\n  expires TIMESTAMPTZ;\n  remaining_days INTEGER;\nBEGIN\n  -- Check if user has 'pro' achievement in profile\n  SELECT 'pro' = ANY(achievements) INTO has_pro_achievement\n  FROM public.profiles\n  WHERE user_id = p_user_id;\n  \n  has_pro_achievement := COALESCE(has_pro_achievement, false);\n  \n  -- Get active pro subscription\n  SELECT * INTO pro_record\n  FROM public.pro_subscriptions\n  WHERE user_id = p_user_id\n    AND status = 'active'\n  ORDER BY created_at DESC\n  LIMIT 1;\n  \n  -- Determine expiration date\n  IF pro_record.subscription_type = 'trial' THEN\n    expires := pro_record.trial_end_date;\n  ELSE\n    expires := pro_record.subscription_end_date;\n  END IF;\n  \n  -- Calculate remaining days\n  remaining_days := EXTRACT(DAY FROM (expires - now()));\n  \n  -- Check if expired and update status if needed\n  IF expires IS NOT NULL AND expires < now() AND pro_record.status = 'active' THEN\n    -- Update status to expired\n    UPDATE public.pro_subscriptions \n    SET status = 'expired', updated_at = now()\n    WHERE user_id = p_user_id AND status = 'active';\n    \n    -- Remove pro achievement\n    PERFORM public.revoke_pro_status(p_user_id);\n    \n    RETURN QUERY SELECT false, pro_record.subscription_type, 'expired'::text, expires, remaining_days;\n  ELSE\n    RETURN QUERY SELECT \n      has_pro_achievement AND (expires IS NULL OR expires > now()),\n      COALESCE(pro_record.subscription_type, 'none'), \n      COALESCE(pro_record.status, 'inactive'), \n      expires, \n      remaining_days;\n  END IF;\nEND;\n$function$;\n\n-- Update sync_pro_status_from_subscription function\nCREATE OR REPLACE FUNCTION public.sync_pro_status_from_subscription(p_user_id uuid)\nRETURNS boolean\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $function$\nDECLARE\n  has_active_subscription boolean := false;\n  sub_record RECORD;\nBEGIN\n  -- Check if user has active pro subscription (updated table name)\n  SELECT * INTO sub_record\n  FROM public.pro_subscriptions\n  WHERE user_id = p_user_id\n  ORDER BY created_at DESC\n  LIMIT 1;\n  \n  IF FOUND THEN\n    -- Check if subscription is active and not expired\n    IF sub_record.status = 'active' THEN\n      IF sub_record.subscription_type = 'trial' AND sub_record.trial_end_date > now() THEN\n        has_active_subscription := true;\n      ELSIF sub_record.subscription_type IN ('monthly', 'yearly') AND \n            (sub_record.subscription_end_date IS NULL OR sub_record.subscription_end_date > now()) THEN\n        has_active_subscription := true;\n      END IF;\n    END IF;\n  END IF;\n  \n  -- Grant or revoke pro status based on subscription\n  IF has_active_subscription THEN\n    PERFORM public.grant_pro_status(p_user_id);\n  ELSE\n    PERFORM public.revoke_pro_status(p_user_id);\n  END IF;\n  \n  RETURN has_active_subscription;\nEND;\n$function$;"}		elvisiondragon@gmail.com	\N
20250822021407	{"-- Drop and recreate functions to fix search_path warnings\n\n-- Drop existing function first\nDROP FUNCTION IF EXISTS public.calculate_subscription_end_date(text, timestamp with time zone);\n\n-- Recreate with proper search_path\nCREATE OR REPLACE FUNCTION public.calculate_subscription_end_date(\n  p_subscription_type text,\n  p_start_date timestamp with time zone\n)\nRETURNS timestamp with time zone\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $function$\nBEGIN\n  CASE p_subscription_type\n    WHEN 'trial' THEN\n      RETURN p_start_date + INTERVAL '3 days';\n    WHEN 'monthly', '1_month' THEN\n      RETURN p_start_date + INTERVAL '1 month';\n    WHEN 'yearly', '1_year' THEN\n      RETURN p_start_date + INTERVAL '1 year';\n    ELSE\n      -- Default to 1 month\n      RETURN p_start_date + INTERVAL '1 month';\n  END CASE;\nEND;\n$function$;\n\n-- Update auto_sync_pro_on_subscription_change trigger function\nCREATE OR REPLACE FUNCTION public.auto_sync_pro_on_subscription_change()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $function$\nBEGIN\n  -- Sync pro status for the user whose subscription changed\n  PERFORM public.sync_pro_status_from_subscription(COALESCE(NEW.user_id, OLD.user_id));\n  \n  RETURN COALESCE(NEW, OLD);\nEND;\n$function$;"}		elvisiondragon@gmail.com	\N
20250822021529	{"-- Check and fix remaining functions without search_path\n\n-- Update start_vip_trial function (if exists)\nCREATE OR REPLACE FUNCTION public.start_vip_trial(p_user_id uuid, p_email text, p_ip_address text DEFAULT NULL::text)\nRETURNS uuid\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $function$\nDECLARE\n  subscription_id UUID;\n  trial_end TIMESTAMPTZ;\nBEGIN\n  -- Calculate trial end date (3 days from now)\n  trial_end := now() + INTERVAL '3 days';\n  \n  -- Insert or update VIP subscription\n  INSERT INTO public.vip_subscriptions (\n    user_id, \n    email, \n    ip_address,\n    subscription_type,\n    status,\n    trial_start_date,\n    trial_end_date\n  ) VALUES (\n    p_user_id, \n    p_email, \n    p_ip_address,\n    'trial',\n    'active',\n    now(),\n    trial_end\n  )\n  ON CONFLICT (user_id) \n  DO UPDATE SET\n    subscription_type = 'trial',\n    status = 'active',\n    trial_start_date = now(),\n    trial_end_date = trial_end,\n    updated_at = now()\n  RETURNING id INTO subscription_id;\n  \n  RETURN subscription_id;\nEND;\n$function$;\n\n-- Update check_vip_status function (if exists)\nCREATE OR REPLACE FUNCTION public.check_vip_status(p_user_id uuid)\nRETURNS TABLE(is_vip boolean, subscription_type text, status text, expires_at timestamp with time zone, days_remaining integer)\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $function$\nDECLARE\n  sub_record RECORD;\n  expires TIMESTAMPTZ;\n  remaining_days INTEGER;\nBEGIN\n  SELECT * INTO sub_record\n  FROM public.vip_subscriptions\n  WHERE user_id = p_user_id;\n  \n  IF NOT FOUND THEN\n    RETURN QUERY SELECT false, NULL::TEXT, NULL::TEXT, NULL::TIMESTAMPTZ, NULL::INTEGER;\n    RETURN;\n  END IF;\n  \n  -- Determine expiration date\n  IF sub_record.subscription_type = 'trial' THEN\n    expires := sub_record.trial_end_date;\n  ELSE\n    expires := sub_record.subscription_end_date;\n  END IF;\n  \n  -- Calculate remaining days\n  remaining_days := EXTRACT(DAY FROM (expires - now()));\n  \n  -- Check if expired\n  IF expires < now() AND sub_record.status = 'active' THEN\n    -- Update status to expired\n    UPDATE public.vip_subscriptions \n    SET status = 'expired', updated_at = now()\n    WHERE user_id = p_user_id;\n    \n    RETURN QUERY SELECT false, sub_record.subscription_type, 'expired'::TEXT, expires, remaining_days;\n  ELSE\n    RETURN QUERY SELECT \n      (sub_record.status = 'active'), \n      sub_record.subscription_type, \n      sub_record.status, \n      expires, \n      remaining_days;\n  END IF;\nEND;\n$function$;"}		elvisiondragon@gmail.com	\N
20250822021909	{"-- Add srcindocs@gmail.com as PRO user for 365 days\nSELECT public.add_pro_user_by_email('srcindocs@gmail.com', 'yearly', 365);"}		elvisiondragon@gmail.com	\N
20250826051620	{"-- Database cleanup: Drop packages table since subscription_plans provides complete functionality\n-- Verification: No foreign key constraints found, data is redundant\n\nDROP TABLE IF EXISTS public.packages CASCADE;\n\n-- Verify subscription_plans has all necessary data\nSELECT id, name, price, duration_days, is_active FROM public.subscription_plans;"}		elvisiondragon@gmail.com	\N
20250822041605	{"-- Fix the check_pro_status function with proper timestamp handling\nCREATE OR REPLACE FUNCTION public.check_pro_status(p_user_id uuid)\nRETURNS TABLE(is_pro boolean, subscription_type text, status text, expires_at timestamp with time zone, days_remaining integer)\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public'\nAS $function$\nDECLARE\n  subscription_record RECORD;\n  current_time timestamp with time zone := now();\nBEGIN\n  -- Get the most recent active subscription\n  SELECT * INTO subscription_record\n  FROM public.pro_subscriptions ps\n  WHERE ps.user_id = p_user_id\n  ORDER BY ps.created_at DESC\n  LIMIT 1;\n  \n  -- If no subscription found\n  IF NOT FOUND THEN\n    RETURN QUERY SELECT false, null::text, null::text, null::timestamp with time zone, null::integer;\n    RETURN;\n  END IF;\n  \n  -- Check if subscription is active based on type\n  IF subscription_record.subscription_type = 'trial' THEN\n    IF subscription_record.status = 'active' AND \n       subscription_record.trial_end_date IS NOT NULL AND \n       subscription_record.trial_end_date::timestamp with time zone > current_time THEN\n      RETURN QUERY SELECT \n        true,\n        subscription_record.subscription_type,\n        subscription_record.status,\n        subscription_record.trial_end_date::timestamp with time zone,\n        EXTRACT(days FROM (subscription_record.trial_end_date::timestamp with time zone - current_time))::integer;\n    ELSE\n      RETURN QUERY SELECT false, subscription_record.subscription_type, 'expired'::text, subscription_record.trial_end_date::timestamp with time zone, 0;\n    END IF;\n  ELSIF subscription_record.subscription_type IN ('monthly', 'yearly') THEN\n    IF subscription_record.status = 'active' AND\n       (subscription_record.subscription_end_date IS NULL OR subscription_record.subscription_end_date::timestamp with time zone > current_time) THEN\n      RETURN QUERY SELECT \n        true,\n        subscription_record.subscription_type,\n        subscription_record.status,\n        COALESCE(subscription_record.subscription_end_date::timestamp with time zone, subscription_record.trial_end_date::timestamp with time zone),\n        CASE \n          WHEN subscription_record.subscription_end_date IS NOT NULL \n          THEN EXTRACT(days FROM (subscription_record.subscription_end_date::timestamp with time zone - current_time))::integer\n          ELSE null::integer\n        END;\n    ELSE\n      RETURN QUERY SELECT false, subscription_record.subscription_type, 'expired'::text, subscription_record.subscription_end_date::timestamp with time zone, 0;\n    END IF;\n  ELSE\n    RETURN QUERY SELECT false, subscription_record.subscription_type, subscription_record.status, null::timestamp with time zone, null::integer;\n  END IF;\n  \n  RETURN;\nEND;\n$function$"}		elvisiondragon@gmail.com	\N
20250822054511	{"-- Drop the problematic check_pro_status function\nDROP FUNCTION IF EXISTS public.check_pro_status(uuid);\n\n-- Create a new, working check_pro_status function\nCREATE OR REPLACE FUNCTION public.check_pro_status(p_user_id uuid)\nRETURNS TABLE(\n  is_pro boolean,\n  subscription_type text,\n  status text,\n  expires_at timestamp with time zone,\n  days_remaining integer\n)\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public'\nAS $$\nDECLARE\n  sub_record RECORD;\n  current_time timestamptz := now();\nBEGIN\n  -- Get the most recent subscription for the user\n  SELECT * INTO sub_record\n  FROM public.pro_subscriptions\n  WHERE user_id = p_user_id\n  ORDER BY created_at DESC\n  LIMIT 1;\n  \n  -- If no subscription found, return not pro\n  IF NOT FOUND THEN\n    RETURN QUERY SELECT false, null::text, null::text, null::timestamptz, null::integer;\n    RETURN;\n  END IF;\n  \n  -- Check if subscription is active and not expired\n  IF sub_record.status = 'active' THEN\n    -- Handle trial subscriptions\n    IF sub_record.subscription_type = 'trial' THEN\n      IF sub_record.trial_end_date > current_time THEN\n        RETURN QUERY SELECT \n          true,\n          sub_record.subscription_type,\n          sub_record.status,\n          sub_record.trial_end_date,\n          EXTRACT(days FROM (sub_record.trial_end_date - current_time))::integer;\n        RETURN;\n      END IF;\n    -- Handle paid subscriptions\n    ELSIF sub_record.subscription_type IN ('monthly', 'yearly') THEN\n      IF sub_record.subscription_end_date IS NULL OR sub_record.subscription_end_date > current_time THEN\n        RETURN QUERY SELECT \n          true,\n          sub_record.subscription_type,\n          sub_record.status,\n          sub_record.subscription_end_date,\n          CASE \n            WHEN sub_record.subscription_end_date IS NULL THEN null::integer\n            ELSE EXTRACT(days FROM (sub_record.subscription_end_date - current_time))::integer\n          END;\n        RETURN;\n      END IF;\n    END IF;\n  END IF;\n  \n  -- If we get here, subscription is not active or expired\n  RETURN QUERY SELECT false, sub_record.subscription_type, sub_record.status, sub_record.subscription_end_date, null::integer;\nEND;\n$$;"}		elvisiondragon@gmail.com	\N
20250823085409	{"-- EMERGENCY FIX: Remove the phone validation trigger that's blocking authentication\nDROP TRIGGER IF EXISTS phone_required_trigger ON auth.users;\nDROP FUNCTION IF EXISTS public.check_phone_not_null();"}		elvisiondragon@gmail.com	\N
20250825122210	{"-- Update profile achievements for user charismoch259 to add 'pro' status\nUPDATE public.profiles \nSET achievements = array_append(achievements, 'pro'),\n    updated_at = now()\nWHERE user_id = 'b2803bb9-d737-4420-8eb0-4a6deed56216';"}		elvisiondragon@gmail.com	\N
20250825122307	{"-- Fix security issue: Restrict pro_user table access to protect sensitive payment data\n-- Drop the overly permissive policy that allows anyone to manage all records\nDROP POLICY IF EXISTS \\"Team can manage all pro_user records\\" ON public.pro_user;\n\n-- Create secure policies for pro_user table\n-- Users can only view their own pro_user records based on email match\nCREATE POLICY \\"Users can view own pro subscription\\" \nON public.pro_user \nFOR SELECT \nUSING (\n  email = (SELECT email FROM auth.users WHERE id = auth.uid())\n);\n\n-- Only authenticated users can insert their own records\nCREATE POLICY \\"Users can create own pro subscription\\" \nON public.pro_user \nFOR INSERT \nWITH CHECK (\n  auth.uid() IS NOT NULL AND \n  email = (SELECT email FROM auth.users WHERE id = auth.uid())\n);\n\n-- Only allow system/service updates (for payment processing)\nCREATE POLICY \\"System can update pro subscriptions\\" \nON public.pro_user \nFOR UPDATE \nUSING (true)\nWITH CHECK (true);\n\n-- Verified admins can view all records for support purposes\nCREATE POLICY \\"Admins can view all pro subscriptions\\" \nON public.pro_user \nFOR SELECT \nUSING (is_verified_admin(auth.uid()));"}		elvisiondragon@gmail.com	\N
20250825103433	{"-- Add columns for streak tracking if they don't exist\nALTER TABLE public.profiles \nADD COLUMN IF NOT EXISTS last_login_date DATE,\nADD COLUMN IF NOT EXISTS last_streak_bonus_date DATE;\n\n-- Create function to handle daily login and streak tracking\nCREATE OR REPLACE FUNCTION public.handle_daily_login(p_user_id uuid)\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $$\nDECLARE\n  user_profile RECORD;\n  today_date DATE := CURRENT_DATE;\n  yesterday_date DATE := CURRENT_DATE - INTERVAL '1 day';\n  new_streak INTEGER := 0;\n  xp_awarded INTEGER := 0;\n  streak_bonus_awarded BOOLEAN := false;\n  result jsonb;\nBEGIN\n  -- Get current user profile\n  SELECT * INTO user_profile\n  FROM public.profiles\n  WHERE user_id = p_user_id;\n  \n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'User profile not found';\n  END IF;\n  \n  -- Check if user already logged in today\n  IF user_profile.last_login_date = today_date THEN\n    -- User already logged in today, return current streak\n    RETURN jsonb_build_object(\n      'streak_days', user_profile.streak_days,\n      'xp_awarded', 0,\n      'streak_bonus_awarded', false,\n      'message', 'Already logged in today'\n    );\n  END IF;\n  \n  -- Determine new streak\n  IF user_profile.last_login_date = yesterday_date THEN\n    -- Consecutive login, increment streak\n    new_streak := user_profile.streak_days + 1;\n  ELSIF user_profile.last_login_date IS NULL OR user_profile.last_login_date < yesterday_date THEN\n    -- First login or missed days, reset streak\n    new_streak := 1;\n  ELSE\n    -- This shouldn't happen, but handle it\n    new_streak := 1;\n  END IF;\n  \n  -- Check for 7-day streak bonus\n  IF new_streak >= 7 AND (new_streak % 7 = 0) THEN\n    -- Award streak bonus (only once per 7-day cycle)\n    IF user_profile.last_streak_bonus_date IS NULL OR \n       user_profile.last_streak_bonus_date < (today_date - INTERVAL '6 days') THEN\n      xp_awarded := 50;\n      streak_bonus_awarded := true;\n      \n      -- Award XP using existing function\n      PERFORM public.award_xp(\n        p_user_id,\n        xp_awarded,\n        'weekly_streak_bonus',\n        'Completed 7-day login streak',\n        jsonb_build_object('streak_days', new_streak, 'bonus_date', today_date)\n      );\n    END IF;\n  END IF;\n  \n  -- Update profile with new streak and login date\n  UPDATE public.profiles\n  SET \n    streak_days = new_streak,\n    last_login_date = today_date,\n    last_streak_bonus_date = CASE \n      WHEN streak_bonus_awarded THEN today_date \n      ELSE last_streak_bonus_date \n    END,\n    updated_at = now()\n  WHERE user_id = p_user_id;\n  \n  -- Build result\n  result := jsonb_build_object(\n    'streak_days', new_streak,\n    'xp_awarded', xp_awarded,\n    'streak_bonus_awarded', streak_bonus_awarded,\n    'message', CASE \n      WHEN streak_bonus_awarded THEN 'Weekly streak bonus earned!'\n      WHEN new_streak = 1 THEN 'Login streak started!'\n      ELSE 'Login streak continued!'\n    END\n  );\n  \n  RETURN result;\nEND;\n$$;"}		elvisiondragon@gmail.com	\N
20250825103713	{"-- Enable realtime for profiles table\nALTER TABLE public.profiles REPLICA IDENTITY FULL;\n\n-- Add profiles table to realtime publication\nALTER PUBLICATION supabase_realtime ADD TABLE public.profiles;"}		elvisiondragon@gmail.com	\N
20250826011153	{"-- Fix notification spamming by adding timestamp-based cooldown to handle_daily_login\n-- Add last_notification_time column to track when notifications were last sent\nALTER TABLE public.profiles \nADD COLUMN IF NOT EXISTS last_notification_time TIMESTAMP WITH TIME ZONE;\n\n-- Update handle_daily_login function with proper notification throttling\nCREATE OR REPLACE FUNCTION public.handle_daily_login(p_user_id uuid)\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $$\nDECLARE\n  user_profile RECORD;\n  today_date DATE := CURRENT_DATE;\n  yesterday_date DATE := CURRENT_DATE - INTERVAL '1 day';\n  current_timestamp TIMESTAMP WITH TIME ZONE := now();\n  new_streak INTEGER := 0;\n  xp_awarded INTEGER := 0;\n  streak_bonus_awarded BOOLEAN := false;\n  should_notify BOOLEAN := false;\n  result jsonb;\nBEGIN\n  -- Get current user profile\n  SELECT * INTO user_profile\n  FROM public.profiles\n  WHERE user_id = p_user_id;\n  \n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'User profile not found';\n  END IF;\n  \n  -- Check if user already logged in today AND was notified recently\n  IF user_profile.last_login_date = today_date THEN\n    -- Check if notification was sent in the last hour (prevent spam)\n    IF user_profile.last_notification_time IS NOT NULL AND \n       user_profile.last_notification_time > (current_timestamp - INTERVAL '1 hour') THEN\n      -- User already logged in today and was notified recently\n      RETURN jsonb_build_object(\n        'streak_days', user_profile.streak_days,\n        'xp_awarded', 0,\n        'streak_bonus_awarded', false,\n        'message', 'Already logged in today',\n        'should_notify', false\n      );\n    END IF;\n  END IF;\n  \n  -- Determine new streak\n  IF user_profile.last_login_date = yesterday_date THEN\n    -- Consecutive login, increment streak\n    new_streak := user_profile.streak_days + 1;\n  ELSIF user_profile.last_login_date IS NULL OR user_profile.last_login_date < yesterday_date THEN\n    -- First login or missed days, reset streak\n    new_streak := 1;\n  ELSE\n    -- This shouldn't happen, but handle it\n    new_streak := 1;\n  END IF;\n  \n  -- Only process if this is actually a new login (not already processed today)\n  IF user_profile.last_login_date != today_date THEN\n    should_notify := true;\n    \n    -- Check for 7-day streak bonus\n    IF new_streak >= 7 AND (new_streak % 7 = 0) THEN\n      -- Award streak bonus (only once per 7-day cycle)\n      IF user_profile.last_streak_bonus_date IS NULL OR \n         user_profile.last_streak_bonus_date < (today_date - INTERVAL '6 days') THEN\n        xp_awarded := 50;\n        streak_bonus_awarded := true;\n        \n        -- Award XP using existing function\n        PERFORM public.award_xp(\n          p_user_id,\n          xp_awarded,\n          'weekly_streak_bonus',\n          'Completed 7-day login streak',\n          jsonb_build_object('streak_days', new_streak, 'bonus_date', today_date)\n        );\n      END IF;\n    END IF;\n    \n    -- Update profile with new streak, login date, and notification time\n    UPDATE public.profiles\n    SET \n      streak_days = new_streak,\n      last_login_date = today_date,\n      last_notification_time = current_timestamp,\n      last_streak_bonus_date = CASE \n        WHEN streak_bonus_awarded THEN today_date \n        ELSE last_streak_bonus_date \n      END,\n      updated_at = now()\n    WHERE user_id = p_user_id;\n  ELSE\n    -- Just update notification time to prevent spam\n    UPDATE public.profiles\n    SET last_notification_time = current_timestamp\n    WHERE user_id = p_user_id;\n  END IF;\n  \n  -- Build result\n  result := jsonb_build_object(\n    'streak_days', new_streak,\n    'xp_awarded', xp_awarded,\n    'streak_bonus_awarded', streak_bonus_awarded,\n    'should_notify', should_notify,\n    'message', CASE \n      WHEN NOT should_notify THEN 'Already logged in today'\n      WHEN streak_bonus_awarded THEN 'Weekly streak bonus earned!'\n      WHEN new_streak = 1 THEN 'Login streak started!'\n      ELSE 'Login streak continued!'\n    END\n  );\n  \n  RETURN result;\nEND;\n$$;"}		elvisiondragon@gmail.com	\N
20250826085707	{"-- Consolidate Pro System - Single Source of Truth Migration\n-- This migration eliminates the need for profiles.achievements and pro_user tables\n-- by making pro_subscriptions the only source for pro status\n\n-- 1. Enhance pro_subscriptions table with additional columns\nALTER TABLE public.pro_subscriptions \nADD COLUMN IF NOT EXISTS verse_access BOOLEAN DEFAULT true,\nADD COLUMN IF NOT EXISTS pro_badge BOOLEAN DEFAULT true;\n\n-- 2. Create unified pro check function\nCREATE OR REPLACE FUNCTION public.check_unified_pro_status(p_user_id UUID)\nRETURNS TABLE(\n  is_pro BOOLEAN,\n  subscription_type TEXT,\n  status TEXT,\n  expires_at TIMESTAMPTZ,\n  days_remaining INTEGER,\n  verse_access BOOLEAN,\n  pro_badge BOOLEAN\n) \nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $$\nBEGIN\n  RETURN QUERY\n  SELECT\n    CASE \n      WHEN ps.status = 'active' AND (\n        (ps.subscription_type = 'trial' AND ps.trial_end_date > now()) OR\n        (ps.subscription_type IN ('monthly', 'yearly') AND ps.subscription_end_date > now())\n      ) THEN true \n      ELSE false \n    END as is_pro,\n    ps.subscription_type,\n    ps.status,\n    CASE\n      WHEN ps.subscription_type = 'trial' THEN ps.trial_end_date\n      ELSE ps.subscription_end_date\n    END as expires_at,\n    CASE\n      WHEN ps.subscription_type = 'trial' THEN \n        EXTRACT(DAY FROM (ps.trial_end_date - now()))::INTEGER\n      ELSE \n        EXTRACT(DAY FROM (ps.subscription_end_date - now()))::INTEGER\n    END as days_remaining,\n    COALESCE(ps.verse_access, true) as verse_access,\n    COALESCE(ps.pro_badge, true) as pro_badge\n  FROM public.pro_subscriptions ps\n  WHERE ps.user_id = p_user_id\n  ORDER BY ps.created_at DESC\n  LIMIT 1;\nEND;\n$$;\n\n-- 3. Create auto-expire function for subscriptions\nCREATE OR REPLACE FUNCTION public.expire_subscriptions()\nRETURNS void \nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $$\nBEGIN\n  -- Auto-expire trial subscriptions\n  UPDATE public.pro_subscriptions\n  SET status = 'expired'\n  WHERE subscription_type = 'trial' \n    AND trial_end_date < now() \n    AND status = 'active';\n  \n  -- Auto-expire paid subscriptions\n  UPDATE public.pro_subscriptions\n  SET status = 'expired'\n  WHERE subscription_type IN ('monthly', 'yearly') \n    AND subscription_end_date < now() \n    AND status = 'active';\nEND;\n$$;\n\n-- 4. Create trigger to automatically sync pro status with profiles.achievements\n-- This ensures backward compatibility during transition\nCREATE OR REPLACE FUNCTION public.sync_pro_achievements()\nRETURNS TRIGGER \nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $$\nDECLARE\n  is_active_pro BOOLEAN;\nBEGIN\n  -- Check if user has active pro subscription\n  SELECT EXISTS(\n    SELECT 1 FROM public.pro_subscriptions ps\n    WHERE ps.user_id = COALESCE(NEW.user_id, OLD.user_id)\n    AND ps.status = 'active'\n    AND (\n      (ps.subscription_type = 'trial' AND ps.trial_end_date > now()) OR\n      (ps.subscription_type IN ('monthly', 'yearly') AND ps.subscription_end_date > now())\n    )\n  ) INTO is_active_pro;\n  \n  -- Update profiles achievements accordingly\n  IF is_active_pro THEN\n    -- Add 'pro' to achievements if not present\n    UPDATE public.profiles \n    SET achievements = CASE \n      WHEN 'pro' = ANY(achievements) THEN achievements\n      ELSE array_append(achievements, 'pro')\n    END,\n    updated_at = now()\n    WHERE user_id = COALESCE(NEW.user_id, OLD.user_id);\n  ELSE\n    -- Remove 'pro' from achievements\n    UPDATE public.profiles \n    SET achievements = array_remove(achievements, 'pro'),\n        updated_at = now()\n    WHERE user_id = COALESCE(NEW.user_id, OLD.user_id);\n  END IF;\n  \n  RETURN COALESCE(NEW, OLD);\nEND;\n$$;\n\n-- 5. Create trigger on pro_subscriptions changes\nDROP TRIGGER IF EXISTS sync_pro_achievements_trigger ON public.pro_subscriptions;\nCREATE TRIGGER sync_pro_achievements_trigger\n  AFTER INSERT OR UPDATE OR DELETE ON public.pro_subscriptions\n  FOR EACH ROW\n  EXECUTE FUNCTION public.sync_pro_achievements();\n\n-- 6. Migrate existing pro_user data to pro_subscriptions if not already present\nINSERT INTO public.pro_subscriptions (\n  user_id,\n  user_email,\n  subscription_type,\n  status,\n  amount_paid,\n  currency,\n  subscription_start_date,\n  subscription_end_date,\n  tripay_reference,\n  verse_access,\n  pro_badge\n)\nSELECT \n  (SELECT id FROM auth.users WHERE email = pu.email LIMIT 1) as user_id,\n  pu.email,\n  pu.subscription_type,\n  pu.status,\n  pu.amount,\n  pu.currency,\n  pu.start_date,\n  pu.end_date,\n  pu.tripay_reference,\n  true as verse_access,\n  true as pro_badge\nFROM public.pro_user pu\nWHERE NOT EXISTS (\n  SELECT 1 FROM public.pro_subscriptions ps \n  WHERE ps.user_email = pu.email\n)\nON CONFLICT DO NOTHING;\n\n-- 7. Update existing pro_subscriptions to have proper end dates for active subscriptions\nUPDATE public.pro_subscriptions \nSET subscription_end_date = CASE\n  WHEN subscription_type = 'monthly' AND subscription_start_date IS NOT NULL \n    THEN subscription_start_date + INTERVAL '30 days'\n  WHEN subscription_type = 'yearly' AND subscription_start_date IS NOT NULL \n    THEN subscription_start_date + INTERVAL '365 days'\n  ELSE subscription_end_date\nEND\nWHERE subscription_end_date IS NULL \n  AND subscription_type IN ('monthly', 'yearly')\n  AND status = 'active'\n  AND subscription_start_date IS NOT NULL;\n\n-- 8. Run initial expiry check\nSELECT public.expire_subscriptions();\n\n-- 9. Update can_access_verse function to use unified pro status\nCREATE OR REPLACE FUNCTION public.can_access_verse(p_user_id uuid, p_verse_number integer)\nRETURNS boolean\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $$\nDECLARE\n  user_level INTEGER;\n  pro_data RECORD;\nBEGIN\n  -- Get user level\n  SELECT level INTO user_level\n  FROM public.profiles\n  WHERE user_id = p_user_id;\n  \n  -- Get unified pro status\n  SELECT * INTO pro_data\n  FROM public.check_unified_pro_status(p_user_id);\n  \n  -- Pro users with verse access can access verses 1-4 regardless of level\n  IF pro_data.is_pro AND pro_data.verse_access AND p_verse_number <= 4 THEN\n    RETURN true;\n  END IF;\n  \n  -- Level-based access for non-pro users or verses beyond 4\n  CASE p_verse_number\n    WHEN 1 THEN RETURN user_level >= 3;\n    WHEN 2 THEN RETURN user_level >= 4; \n    WHEN 3 THEN RETURN user_level >= 4;\n    WHEN 4 THEN RETURN user_level >= 5;\n    ELSE RETURN false;\n  END CASE;\nEND;\n$$;"}		elvisiondragon@gmail.com	\N
20250826114909	{"-- Pro System Cleanup: Remove obsolete tables and fix webhooks\n\n-- 1. Drop unused empty tables\nDROP TABLE IF EXISTS public.orders CASCADE;\nDROP TABLE IF EXISTS public.subscriptions CASCADE; \nDROP TABLE IF EXISTS public.transactions CASCADE;\nDROP TABLE IF EXISTS public.user_memberships CASCADE;\n\n-- 2. Remove backward compatibility trigger that creates circular dependency  \nDROP TRIGGER IF EXISTS sync_pro_achievements_trigger ON public.pro_subscriptions;\nDROP FUNCTION IF EXISTS public.sync_pro_achievements();\n\n-- 3. Remove obsolete functions\nDROP FUNCTION IF EXISTS public.check_pro_status(UUID);\nDROP FUNCTION IF EXISTS public.calculate_subscription_end_date(TEXT, TIMESTAMPTZ);\n\n-- 4. Create proper subscription end date calculation for unified system\nCREATE OR REPLACE FUNCTION public.calculate_subscription_end_date(\n  p_subscription_type TEXT,\n  p_start_date TIMESTAMPTZ DEFAULT now()\n) RETURNS TIMESTAMPTZ AS $$\nBEGIN\n  CASE p_subscription_type\n    WHEN 'trial' THEN \n      RETURN p_start_date + INTERVAL '2 days';\n    WHEN 'monthly' THEN \n      RETURN p_start_date + INTERVAL '30 days';\n    WHEN 'yearly' THEN \n      RETURN p_start_date + INTERVAL '365 days';\n    ELSE \n      RETURN p_start_date + INTERVAL '30 days';\n  END CASE;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER;\n\n-- 5. Update pro_subscriptions with proper subscription end dates for existing records\nUPDATE public.pro_subscriptions \nSET subscription_end_date = calculate_subscription_end_date(subscription_type, subscription_start_date)\nWHERE subscription_end_date IS NULL \n  AND subscription_start_date IS NOT NULL \n  AND subscription_type IN ('monthly', 'yearly');\n\n-- 6. Ensure all trial subscriptions have trial_end_date\nUPDATE public.pro_subscriptions \nSET trial_end_date = trial_start_date + INTERVAL '2 days'\nWHERE subscription_type = 'trial' \n  AND trial_end_date IS NULL \n  AND trial_start_date IS NOT NULL;"}		elvisiondragon@gmail.com	\N
20250826115110	{"-- Enable required extensions for cron jobs\nCREATE EXTENSION IF NOT EXISTS pg_cron;\nCREATE EXTENSION IF NOT EXISTS http;\n\n-- Create cron job for automatic subscription expiry (runs every hour)\nSELECT cron.schedule(\n  'expire-subscriptions-hourly',\n  '0 * * * *', -- Every hour at minute 0\n  $$\n  SELECT\n    net.http_post(\n        url:='https://nlrgdhpmsittuwiiindq.supabase.co/functions/v1/expire-subscriptions',\n        headers:='{\\"Content-Type\\": \\"application/json\\", \\"Authorization\\": \\"Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Im5scmdkaHBtc2l0dHV3aWlpbmRxIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NTQ0MDk0NTQsImV4cCI6MjA2OTk4NTQ1NH0.62U0WBImD8aT8mJvHv4xysGsp4IyV1A4a26OlTdOpVw\\"}'::jsonb\n    ) as request_id;\n  $$\n);\n\n-- Safe to drop pro_user table now - no longer needed\nDROP TABLE IF EXISTS public.pro_user CASCADE;"}		elvisiondragon@gmail.com	\N
20250826011629	{"-- Fix XP/Level system and create comprehensive days_remaining management\n-- PART 1: Fix the XP level calculation issue\n\n-- Fix award_xp function to properly update level when XP threshold is reached\nCREATE OR REPLACE FUNCTION public.award_xp(p_user_id uuid, p_xp_amount integer, p_activity_type text, p_reason text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)\nRETURNS void\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public'\nAS $$\nDECLARE\n  new_total_xp INTEGER;\n  new_level INTEGER;\n  old_level INTEGER;\n  old_xp INTEGER;\nBEGIN\n  -- Get current level and XP\n  SELECT level, experience_points INTO old_level, old_xp \n  FROM public.profiles WHERE user_id = p_user_id;\n  \n  -- Update experience points\n  UPDATE public.profiles \n  SET experience_points = experience_points + p_xp_amount,\n      updated_at = now()\n  WHERE user_id = p_user_id\n  RETURNING experience_points INTO new_total_xp;\n  \n  -- Calculate new level based on total XP\n  new_level := public.calculate_level_from_xp(new_total_xp);\n  \n  -- Update level if changed\n  IF new_level != old_level THEN\n    UPDATE public.profiles \n    SET level = new_level,\n        updated_at = now()\n    WHERE user_id = p_user_id;\n    \n    -- Log level up\n    INSERT INTO public.user_activities (user_id, activity_type, xp_earned, metadata)\n    VALUES (p_user_id, 'level_up', 0, jsonb_build_object('old_level', old_level, 'new_level', new_level, 'total_xp', new_total_xp));\n  END IF;\n  \n  -- Log the activity\n  INSERT INTO public.user_activities (user_id, activity_type, xp_earned, metadata)\n  VALUES (p_user_id, p_activity_type, p_xp_amount, p_metadata);\n  \n  -- Log the XP transaction\n  INSERT INTO public.xp_transactions (user_id, xp_amount, transaction_type, reason)\n  VALUES (p_user_id, p_xp_amount, 'earned', COALESCE(p_reason, p_activity_type));\nEND;\n$$;\n\n-- PART 2: Create days_remaining table and management system\n\n-- Add days_remaining column to pro_subscriptions if it doesn't exist\nALTER TABLE public.pro_subscriptions \nADD COLUMN IF NOT EXISTS days_remaining INTEGER;\n\n-- Create comprehensive days_remaining table\nCREATE TABLE IF NOT EXISTS public.days_remaining (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id UUID NOT NULL REFERENCES public.profiles(user_id) ON DELETE CASCADE,\n  email TEXT NOT NULL,\n  subscription_id UUID REFERENCES public.pro_subscriptions(id) ON DELETE CASCADE,\n  subscription_type TEXT NOT NULL CHECK (subscription_type IN ('trial', 'monthly', 'yearly')),\n  days_remaining INTEGER NOT NULL DEFAULT 0,\n  subscription_start_date TIMESTAMPTZ,\n  subscription_end_date TIMESTAMPTZ,\n  trial_start_date TIMESTAMPTZ,\n  trial_end_date TIMESTAMPTZ,\n  is_active BOOLEAN DEFAULT true,\n  created_at TIMESTAMPTZ DEFAULT now(),\n  updated_at TIMESTAMPTZ DEFAULT now(),\n  UNIQUE(user_id)\n);\n\n-- Enable RLS\nALTER TABLE public.days_remaining ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for days_remaining table\nCREATE POLICY \\"Verified admins can manage days_remaining\\" ON public.days_remaining\n  FOR ALL USING (is_verified_admin(auth.uid()));\n\nCREATE POLICY \\"Users can view their own days_remaining\\" ON public.days_remaining\n  FOR SELECT USING (auth.uid() = user_id);\n\n-- Remove the old duplicate trigger \nDROP TRIGGER IF EXISTS update_days_remaining_trigger ON public.pro_subscriptions;"}		elvisiondragon@gmail.com	\N
20250826012030	{"-- Final fix for all subscription type variations and complete admin dashboard setup\n\n-- Update all invalid subscription types in pro_subscriptions first\nUPDATE public.pro_subscriptions \nSET subscription_type = CASE \n  WHEN subscription_type IN ('1_day', '7_day') THEN 'trial'\n  WHEN subscription_type IN ('30_day', '1_month') THEN 'monthly'\n  WHEN subscription_type IN ('365_day', '1_year') THEN 'yearly'\n  WHEN subscription_type NOT IN ('trial', 'monthly', 'yearly') THEN 'trial'\n  ELSE subscription_type\nEND;\n\n-- Update the constraint to include all variations we might encounter\nALTER TABLE public.days_remaining \nDROP CONSTRAINT IF EXISTS days_remaining_subscription_type_check;\n\nALTER TABLE public.days_remaining \nADD CONSTRAINT days_remaining_subscription_type_check \nCHECK (subscription_type IN ('trial', 'monthly', 'yearly'));\n\n-- Update sync function with comprehensive normalization\nCREATE OR REPLACE FUNCTION public.sync_days_remaining_table()\nRETURNS TRIGGER\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $$\nDECLARE\n  user_email TEXT;\n  calculated_days INTEGER;\n  normalized_sub_type TEXT;\nBEGIN\n  -- Handle DELETE operations\n  IF TG_OP = 'DELETE' THEN\n    DELETE FROM public.days_remaining WHERE subscription_id = OLD.id;\n    RETURN OLD;\n  END IF;\n  \n  -- Skip if user_id is NULL\n  IF NEW.user_id IS NULL THEN\n    RETURN NEW;\n  END IF;\n  \n  -- Get user email from user_contact_info\n  SELECT decrypt_email(uci.email_encrypted) INTO user_email\n  FROM user_contact_info uci \n  WHERE uci.user_id = NEW.user_id;\n  \n  -- Comprehensive normalization of subscription type\n  normalized_sub_type := CASE \n    WHEN NEW.subscription_type IN ('1_day', '7_day', 'trial') THEN 'trial'\n    WHEN NEW.subscription_type IN ('30_day', '1_month', 'monthly') THEN 'monthly'\n    WHEN NEW.subscription_type IN ('365_day', '1_year', 'yearly') THEN 'yearly'\n    ELSE 'trial'  -- Default fallback\n  END;\n  \n  -- Calculate days remaining\n  IF normalized_sub_type = 'trial' AND NEW.trial_end_date IS NOT NULL THEN\n    calculated_days = GREATEST(0, EXTRACT(DAY FROM (NEW.trial_end_date - now()))::INTEGER);\n  ELSIF normalized_sub_type IN ('monthly', 'yearly') AND NEW.subscription_end_date IS NOT NULL THEN\n    calculated_days = GREATEST(0, EXTRACT(DAY FROM (NEW.subscription_end_date - now()))::INTEGER);\n  ELSE\n    calculated_days = 0;\n  END IF;\n  \n  -- Update days_remaining column in pro_subscriptions\n  NEW.days_remaining = calculated_days;\n  \n  -- Upsert to days_remaining table\n  INSERT INTO public.days_remaining (\n    user_id, \n    email, \n    subscription_id, \n    subscription_type, \n    days_remaining,\n    subscription_start_date,\n    subscription_end_date,\n    trial_start_date,\n    trial_end_date,\n    is_active\n  ) VALUES (\n    NEW.user_id,\n    COALESCE(user_email, NEW.user_email, 'unknown@email.com'),\n    NEW.id,\n    normalized_sub_type,\n    calculated_days,\n    NEW.subscription_start_date,\n    NEW.subscription_end_date,\n    NEW.trial_start_date,\n    NEW.trial_end_date,\n    NEW.status = 'active'\n  )\n  ON CONFLICT (user_id) DO UPDATE SET\n    email = EXCLUDED.email,\n    subscription_id = EXCLUDED.subscription_id,\n    subscription_type = EXCLUDED.subscription_type,\n    days_remaining = EXCLUDED.days_remaining,\n    subscription_start_date = EXCLUDED.subscription_start_date,\n    subscription_end_date = EXCLUDED.subscription_end_date,\n    trial_start_date = EXCLUDED.trial_start_date,\n    trial_end_date = EXCLUDED.trial_end_date,\n    is_active = EXCLUDED.is_active,\n    updated_at = now();\n    \n  RETURN NEW;\nEND;\n$$;\n\n-- Update sync_all function with comprehensive normalization\nCREATE OR REPLACE FUNCTION public.sync_all_days_remaining()\nRETURNS INTEGER\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $$\nDECLARE\n  updated_count INTEGER := 0;\n  rec RECORD;\n  calculated_days INTEGER;\n  normalized_sub_type TEXT;\nBEGIN\n  -- Update all pro_subscriptions with current days_remaining (skip NULL user_id)\n  FOR rec IN \n    SELECT ps.*, COALESCE(decrypt_email(uci.email_encrypted), ps.user_email, 'unknown@email.com') as email\n    FROM public.pro_subscriptions ps\n    LEFT JOIN public.user_contact_info uci ON uci.user_id = ps.user_id\n    WHERE ps.user_id IS NOT NULL\n  LOOP\n    -- Comprehensive normalization of subscription type\n    normalized_sub_type := CASE \n      WHEN rec.subscription_type IN ('1_day', '7_day', 'trial') THEN 'trial'\n      WHEN rec.subscription_type IN ('30_day', '1_month', 'monthly') THEN 'monthly'\n      WHEN rec.subscription_type IN ('365_day', '1_year', 'yearly') THEN 'yearly'\n      ELSE 'trial'  -- Default fallback\n    END;\n    \n    -- Calculate days remaining\n    IF normalized_sub_type = 'trial' AND rec.trial_end_date IS NOT NULL THEN\n      calculated_days = GREATEST(0, EXTRACT(DAY FROM (rec.trial_end_date - now()))::INTEGER);\n    ELSIF normalized_sub_type IN ('monthly', 'yearly') AND rec.subscription_end_date IS NOT NULL THEN\n      calculated_days = GREATEST(0, EXTRACT(DAY FROM (rec.subscription_end_date - now()))::INTEGER);\n    ELSE\n      calculated_days = 0;\n    END IF;\n    \n    -- Update pro_subscriptions\n    UPDATE public.pro_subscriptions \n    SET days_remaining = calculated_days\n    WHERE id = rec.id;\n    \n    -- Upsert to days_remaining table\n    INSERT INTO public.days_remaining (\n      user_id, \n      email, \n      subscription_id, \n      subscription_type, \n      days_remaining,\n      subscription_start_date,\n      subscription_end_date,\n      trial_start_date,\n      trial_end_date,\n      is_active\n    ) VALUES (\n      rec.user_id,\n      rec.email,\n      rec.id,\n      normalized_sub_type,\n      calculated_days,\n      rec.subscription_start_date,\n      rec.subscription_end_date,\n      rec.trial_start_date,\n      rec.trial_end_date,\n      rec.status = 'active'\n    )\n    ON CONFLICT (user_id) DO UPDATE SET\n      email = EXCLUDED.email,\n      subscription_id = EXCLUDED.subscription_id,\n      subscription_type = EXCLUDED.subscription_type,\n      days_remaining = EXCLUDED.days_remaining,\n      subscription_start_date = EXCLUDED.subscription_start_date,\n      subscription_end_date = EXCLUDED.subscription_end_date,\n      trial_start_date = EXCLUDED.trial_start_date,\n      trial_end_date = EXCLUDED.trial_end_date,\n      is_active = EXCLUDED.is_active,\n      updated_at = now();\n      \n    updated_count := updated_count + 1;\n  END LOOP;\n  \n  RETURN updated_count;\nEND;\n$$;\n\n-- Recreate the trigger\nDROP TRIGGER IF EXISTS sync_days_remaining_table_trigger ON public.pro_subscriptions;\nCREATE TRIGGER sync_days_remaining_table_trigger\n  BEFORE INSERT OR UPDATE OR DELETE ON public.pro_subscriptions\n  FOR EACH ROW\n  EXECUTE FUNCTION public.sync_days_remaining_table();\n\n-- Populate the table with cleaned data\nSELECT public.sync_all_days_remaining();"}		elvisiondragon@gmail.com	\N
20250826012308	{"-- Fix any users who have incorrect levels based on their XP\n-- This will update all users to have the correct level based on their current XP\n\nUPDATE public.profiles \nSET level = public.calculate_level_from_xp(experience_points),\n    updated_at = now()\nWHERE level != public.calculate_level_from_xp(experience_points);\n\n-- Log how many users were updated\nCREATE OR REPLACE FUNCTION public.fix_user_levels()\nRETURNS INTEGER\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $$\nDECLARE\n  updated_count INTEGER;\nBEGIN\n  UPDATE public.profiles \n  SET level = public.calculate_level_from_xp(experience_points),\n      updated_at = now()\n  WHERE level != public.calculate_level_from_xp(experience_points);\n  \n  GET DIAGNOSTICS updated_count = ROW_COUNT;\n  \n  -- Log the fix\n  PERFORM public.log_sensitive_action(\n    'user_levels_corrected',\n    'profiles',\n    NULL,\n    jsonb_build_object(\n      'updated_count', updated_count,\n      'fix_time', now()\n    )\n  );\n  \n  RETURN updated_count;\nEND;\n$$;"}		elvisiondragon@gmail.com	\N
20250826050235	{"-- Drop existing award_xp function first to allow changing return type\nDROP FUNCTION IF EXISTS public.award_xp(uuid, integer, text, text, jsonb);\n\n-- Update level thresholds according to new system\n-- New thresholds: Level 1: 0 XP, Level 2: 150 XP, Level 3: 500 XP, Level 4: 1,200 XP, \n-- Level 5: 2,500 XP, Level 6: 4,500 XP, Level 7: 7,000 XP, Level 8: 9,000 XP, \n-- Level 9: 12,000 XP, Level 10: 15,000 XP\n\nCREATE OR REPLACE FUNCTION public.calculate_level_from_xp(total_xp integer)\nRETURNS integer\nLANGUAGE plpgsql\nSET search_path = 'public'\nAS $function$\nDECLARE\n  level INTEGER := 1;\nBEGIN\n  -- Updated level requirements with new thresholds\n  IF total_xp >= 15000 THEN\n    RETURN 10;\n  ELSIF total_xp >= 12000 THEN\n    RETURN 9;\n  ELSIF total_xp >= 9000 THEN\n    RETURN 8;\n  ELSIF total_xp >= 7000 THEN\n    RETURN 7;\n  ELSIF total_xp >= 4500 THEN\n    RETURN 6;\n  ELSIF total_xp >= 2500 THEN\n    RETURN 5;\n  ELSIF total_xp >= 1200 THEN\n    RETURN 4;\n  ELSIF total_xp >= 500 THEN\n    RETURN 3;\n  ELSIF total_xp >= 150 THEN\n    RETURN 2;\n  ELSE\n    RETURN 1;\n  END IF;\nEND;\n$function$;\n\n-- Update get_xp_for_next_level function with new thresholds\nCREATE OR REPLACE FUNCTION public.get_xp_for_next_level(current_level integer)\nRETURNS integer\nLANGUAGE plpgsql\nSET search_path = 'public'\nAS $function$\nBEGIN\n  CASE current_level\n    WHEN 1 THEN RETURN 150;\n    WHEN 2 THEN RETURN 500;\n    WHEN 3 THEN RETURN 1200;\n    WHEN 4 THEN RETURN 2500;\n    WHEN 5 THEN RETURN 4500;\n    WHEN 6 THEN RETURN 7000;\n    WHEN 7 THEN RETURN 9000;\n    WHEN 8 THEN RETURN 12000;\n    WHEN 9 THEN RETURN 15000;\n    ELSE RETURN 15000; -- Max level reached\n  END CASE;\nEND;\n$function$;\n\n-- Enhanced award_xp function with automatic level promotions and achievement badges\nCREATE OR REPLACE FUNCTION public.award_xp(p_user_id uuid, p_xp_amount integer, p_activity_type text, p_reason text DEFAULT NULL, p_metadata jsonb DEFAULT '{}')\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $function$\nDECLARE\n  old_level INTEGER;\n  new_level INTEGER;\n  old_xp INTEGER;\n  new_xp INTEGER;\n  level_up_occurred BOOLEAN := false;\n  achievement_earned BOOLEAN := false;\n  result jsonb;\nBEGIN\n  -- Get current profile data\n  SELECT level, experience_points INTO old_level, old_xp\n  FROM public.profiles\n  WHERE user_id = p_user_id;\n  \n  -- If no profile exists, create one\n  IF NOT FOUND THEN\n    INSERT INTO public.profiles (user_id, level, experience_points)\n    VALUES (p_user_id, 1, 0)\n    ON CONFLICT (user_id) DO NOTHING;\n    old_level := 1;\n    old_xp := 0;\n  END IF;\n  \n  -- Calculate new XP and level\n  new_xp := old_xp + p_xp_amount;\n  new_level := public.calculate_level_from_xp(new_xp);\n  level_up_occurred := new_level > old_level;\n  \n  -- Update profile with new XP and level\n  UPDATE public.profiles\n  SET experience_points = new_xp,\n      level = new_level,\n      updated_at = now()\n  WHERE user_id = p_user_id;\n  \n  -- Award level 3 achievement badge if reached for first time\n  IF new_level >= 3 AND old_level < 3 THEN\n    UPDATE public.profiles\n    SET achievements = CASE \n      WHEN 'level_3' = ANY(achievements) THEN achievements\n      ELSE array_append(achievements, 'level_3')\n    END\n    WHERE user_id = p_user_id;\n    achievement_earned := true;\n  END IF;\n  \n  -- Log the XP transaction\n  INSERT INTO public.user_activities (\n    user_id,\n    activity_type,\n    xp_earned,\n    metadata\n  ) VALUES (\n    p_user_id,\n    p_activity_type,\n    p_xp_amount,\n    p_metadata || jsonb_build_object(\n      'reason', p_reason,\n      'old_level', old_level,\n      'new_level', new_level,\n      'level_up', level_up_occurred,\n      'achievement_earned', achievement_earned\n    )\n  );\n  \n  -- Create XP transaction record\n  INSERT INTO public.xp_transactions (\n    user_id,\n    xp_amount,\n    transaction_type,\n    reason\n  ) VALUES (\n    p_user_id,\n    p_xp_amount,\n    p_activity_type,\n    p_reason\n  );\n  \n  -- Return comprehensive result\n  result := jsonb_build_object(\n    'success', true,\n    'old_xp', old_xp,\n    'new_xp', new_xp,\n    'xp_awarded', p_xp_amount,\n    'old_level', old_level,\n    'new_level', new_level,\n    'level_up', level_up_occurred,\n    'achievement_earned', achievement_earned\n  );\n  \n  RETURN result;\nEND;\n$function$;\n\n-- Fix existing user levels based on new thresholds\nUPDATE public.profiles \nSET level = public.calculate_level_from_xp(experience_points),\n    updated_at = now()\nWHERE level != public.calculate_level_from_xp(experience_points);\n\n-- Award level 3 achievements to users who already reached it\nUPDATE public.profiles\nSET achievements = CASE \n  WHEN 'level_3' = ANY(achievements) THEN achievements\n  ELSE array_append(achievements, 'level_3')\nEND\nWHERE level >= 3 AND NOT ('level_3' = ANY(achievements));"}		elvisiondragon@gmail.com	\N
20250826090202	{"-- Fix the NULL values issue first, then apply the constraints\n\n-- 1. Update NULL values to 0 first\nUPDATE public.pro_subscriptions \nSET days_remaining = 0 \nWHERE days_remaining IS NULL;\n\n-- 2. Now set the NOT NULL constraint and default\nALTER TABLE public.pro_subscriptions \nALTER COLUMN days_remaining SET DEFAULT 0;\n\n-- Try to set NOT NULL, but skip if it fails\nDO $$\nBEGIN\n    ALTER TABLE public.pro_subscriptions \n    ALTER COLUMN days_remaining SET NOT NULL;\nEXCEPTION\n    WHEN check_violation OR not_null_violation THEN\n        RAISE NOTICE 'Could not set NOT NULL constraint on days_remaining, but continuing...';\nEND\n$$;\n\n-- 3. Standardize subscription types in existing data  \nUPDATE pro_subscriptions \nSET subscription_type = CASE \n  WHEN subscription_type = 'monthly' THEN '1_month'\n  WHEN subscription_type = 'yearly' THEN '1_year'  \n  WHEN subscription_type = 'weekly' THEN '1_week'\n  WHEN subscription_type = 'daily' THEN '1_day'\n  ELSE subscription_type\nEND\nWHERE subscription_type IN ('monthly', 'yearly', 'weekly', 'daily');\n\n-- 4. Update check_unified_pro_status function to use new subscription types\nCREATE OR REPLACE FUNCTION public.check_unified_pro_status(p_user_id uuid)\nRETURNS TABLE(is_pro boolean, subscription_type text, status text, expires_at timestamp with time zone, days_remaining integer, verse_access boolean, pro_badge boolean)\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public'\nAS $function$\nBEGIN\n  RETURN QUERY\n  SELECT\n    CASE \n      WHEN ps.status = 'active' AND (\n        (ps.subscription_type = 'trial' AND ps.trial_end_date > now()) OR\n        (ps.subscription_type IN ('1_month', '1_year', '1_week', '1_day') AND ps.subscription_end_date > now())\n      ) THEN true \n      ELSE false \n    END as is_pro,\n    ps.subscription_type,\n    ps.status,\n    CASE\n      WHEN ps.subscription_type = 'trial' THEN ps.trial_end_date\n      ELSE ps.subscription_end_date\n    END as expires_at,\n    CASE\n      WHEN ps.subscription_type = 'trial' THEN \n        EXTRACT(DAY FROM (ps.trial_end_date - now()))::INTEGER\n      ELSE \n        EXTRACT(DAY FROM (ps.subscription_end_date - now()))::INTEGER\n    END as days_remaining,\n    COALESCE(ps.verse_access, true) as verse_access,\n    COALESCE(ps.pro_badge, true) as pro_badge\n  FROM public.pro_subscriptions ps\n  WHERE ps.user_id = p_user_id\n  ORDER BY ps.created_at DESC\n  LIMIT 1;\nEND;\n$function$;\n\n-- 5. Update sync_pro_status_from_subscription function\nCREATE OR REPLACE FUNCTION public.sync_pro_status_from_subscription(p_user_id uuid)\nRETURNS boolean\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public'\nAS $function$\nDECLARE\n  has_active_subscription boolean := false;\n  sub_record RECORD;\nBEGIN\n  -- Check if user has active pro subscription\n  SELECT * INTO sub_record\n  FROM public.pro_subscriptions\n  WHERE user_id = p_user_id\n  ORDER BY created_at DESC\n  LIMIT 1;\n  \n  IF FOUND THEN\n    -- Check if subscription is active and not expired\n    IF sub_record.status = 'active' THEN\n      IF sub_record.subscription_type = 'trial' AND sub_record.trial_end_date > now() THEN\n        has_active_subscription := true;\n      ELSIF sub_record.subscription_type IN ('1_month', '1_year', '1_week', '1_day') AND \n            (sub_record.subscription_end_date IS NULL OR sub_record.subscription_end_date > now()) THEN\n        has_active_subscription := true;\n      END IF;\n    END IF;\n  END IF;\n  \n  -- Grant or revoke pro status based on subscription\n  IF has_active_subscription THEN\n    PERFORM public.grant_pro_status(p_user_id);\n  ELSE\n    PERFORM public.revoke_pro_status(p_user_id);\n  END IF;\n  \n  RETURN has_active_subscription;\nEND;\n$function$;\n\n-- 6. Update expire_subscriptions function\nCREATE OR REPLACE FUNCTION public.expire_subscriptions()\nRETURNS void\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public'\nAS $function$\nBEGIN\n  -- Auto-expire trial subscriptions\n  UPDATE public.pro_subscriptions\n  SET status = 'expired'\n  WHERE subscription_type = 'trial' \n    AND trial_end_date < now() \n    AND status = 'active';\n  \n  -- Auto-expire paid subscriptions\n  UPDATE public.pro_subscriptions\n  SET status = 'expired'\n  WHERE subscription_type IN ('1_month', '1_year', '1_week', '1_day') \n    AND subscription_end_date < now() \n    AND status = 'active';\nEND;\n$function$;\n\n-- 7. Create new AFTER trigger for days_remaining calculation (non-blocking)\nCREATE OR REPLACE FUNCTION public.calculate_days_remaining_after()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public'\nAS $function$\nDECLARE\n  calculated_days integer := 0;\nBEGIN\n  -- Calculate days remaining based on subscription type and end dates\n  IF NEW.subscription_type = 'trial' AND NEW.trial_end_date IS NOT NULL THEN\n    calculated_days := GREATEST(0, EXTRACT(DAY FROM (NEW.trial_end_date - now()))::INTEGER);\n  ELSIF NEW.subscription_type IN ('1_month', '1_year', '1_week', '1_day') AND NEW.subscription_end_date IS NOT NULL THEN\n    calculated_days := GREATEST(0, EXTRACT(DAY FROM (NEW.subscription_end_date - now()))::INTEGER);\n  END IF;\n  \n  -- Update days_remaining in a separate transaction to avoid blocking\n  BEGIN\n    UPDATE public.pro_subscriptions \n    SET days_remaining = calculated_days,\n        updated_at = now()\n    WHERE id = NEW.id;\n  EXCEPTION \n    WHEN OTHERS THEN\n      -- Log error but don't block the main operation\n      RAISE NOTICE 'Failed to update days_remaining for subscription %: %', NEW.id, SQLERRM;\n  END;\n  \n  RETURN NEW;\nEND;\n$function$;\n\n-- 8. Drop old BEFORE trigger if it exists and create new AFTER trigger\nDROP TRIGGER IF EXISTS calculate_days_remaining_trigger ON public.pro_subscriptions;\n\nCREATE TRIGGER calculate_days_remaining_after_trigger\n    AFTER INSERT OR UPDATE ON public.pro_subscriptions\n    FOR EACH ROW\n    WHEN (NEW.subscription_type IS NOT NULL)\n    EXECUTE FUNCTION public.calculate_days_remaining_after();\n\n-- 9. Recalculate days_remaining for all active subscriptions\nUPDATE public.pro_subscriptions \nSET days_remaining = CASE\n  WHEN subscription_type = 'trial' AND trial_end_date IS NOT NULL THEN\n    GREATEST(0, EXTRACT(DAY FROM (trial_end_date - now()))::INTEGER)\n  WHEN subscription_type IN ('1_month', '1_year', '1_week', '1_day') AND subscription_end_date IS NOT NULL THEN\n    GREATEST(0, EXTRACT(DAY FROM (subscription_end_date - now()))::INTEGER)\n  ELSE 0\nEND\nWHERE status = 'active';"}		elvisiondragon@gmail.com	\N
